(window.GIM_TS=window.GIM_TS||{})["Arakhin.1"]={"from":24,"a":[["\u0003מלתא אגב אורחיה קמשמע לן\u0004 \u0005[דבר\u0006 נוסף \u0005בדרך אגב משמיע לנו],\u0006 \u0003כ\u0004דברי \u0003רב יהודה אמר רב,\u0004 ש\u0003אמר רב יהודה אמר רב: אסור לאדם שיאמר \"כמה נאה גוי זה\",\u0004 כפי שדרשו חכמים את הכתוב \"ולא תחנם\" (דברים ז, ב) שאסור להזכיר חן שיש בגוי.","ושואלים: אם רק מטעם זה, \u0003וליתני\u0004 \u0005[ושישנה]\u0006 במשנה: \u0003\"את הנאה שבישראל ואת הכעור שבגוים\"!\u0004 ומשיבים: אין בכך קושי, מפני שהתנא \u0003בחד אומה קמיירי\u0004 \u0005[באומה אחת מדבר]\u0006 בדרך כלל, באותה קבוצת אנשים, \u0003בתרי אומה לא מיירי\u0004 \u0005[בשתי אומות אינו מדבר].\u0006","ושואלים: \u0003ולא,\u0004 והאם אינו עוסק בשתי קבוצות אנשים שונות? \u0003והא קתני\u0004 \u0005[והרי הוא שונה]\u0006 במשנתנו: אחד שאנס ופיתה את \u0003הגדולה שבכהונה ואת הקטנה שבישראל\u0004 נותן חמישים סלע! ומשיבים: \u0003התם חד אומה הוא\u0004 \u0005[שם אומה אחת היא],\u0006 \u0003אלא מקדיש הוא דקדישי כהנים טפי\u0004 \u0005[מקודשים הם הכהנים יותר].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר למשנתנו, גם לדעת ר' מאיר, הסבור שהגוי גם כן נערך: \u0003איידי דקא בעי למתני סיפא\u0004 \u0005[מתוך שרצה לשנות\u0006 ב\u0005סוף\u0006 המשנה\u0005]\u0006 את דין המקדיש \u0003שדה אחוזה,\u0004 ש\u0003בישראל הוא דמשכחת לה\u0004 \u0005[שאתה מוצא אותה],\u0006 \u0003בגוי לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה],\u0006 \u0003דלאו\u0004 \u0005[\u0006מפני \u0005שלא]\u0006 \u0003בני אחוזה\u0004 בארץ ישראל \u0003נינהו\u0004 \u0005[הם],\u0006 \u0003משום הכי קתני לה\u0004 \u0005[משום כך הוא שונה אותה]\u0006 כולה \u0003בישראל.\u0004","מה ששנינו במשנה הקודמת שיש \u0003ב\u0004דין \u0003שדה אחוזה להקל ולהחמיר. כיצד? אחד המקדיש\u0004 שדה אחוזה (נחלת אבותיו) \u0003בחולת המחוז,\u0004 ששם הקרקע גרועה וזולה, \u0003ואחד המקדיש בפרדיסות\u0004 של \u0003סבסטי,\u0004 שהיו מעולים ביותר, \u0003נותן\u0004 בפדיונה לפי החשבון האמור בתורה של \u0003זרע חומר שעורים\u0004 (שטח הראוי לזריעת כור שעורים) \u0003בחמשים שקל כסף\u0004 (ויקרא כז, טז), \u0003ו\u0004אילו \u0003ב\u0004מקדיש \u0003שדה מקנה\u0004 (שדה שקנה מאדם אחר), והוא בא לפדותו — \u0003נותן את שוויו\u0004 של השדה, לפי מספר השנים שנותרו עד היובל.","\u0003ר' אליעזר אומר: אחד שדה מקנה ואחד שדה אחוזה\u0004 נותן בפדיונם זרע חומר שעורים בחמישים שקל כסף, ו\u0003מה בין שדה אחוזה לשדה מקנה? שבשדה אחוזה הוא נותן\u0004 (מוסיף) \u0003חומש\u0004 להקדש, כאשר הוא עצמו פודה אותה (ויקרא כז, יט), \u0003ו\u0004אלו \u0003בשדה מקנה,\u0004 כאשר המקדיש רוצה לפדות, \u0003אינו נותן חומש.\u0004","\u0003אמר רב הונא: הקדיש שדה\u0004 אחוזה \u0003מליאה אילנות, כשהוא פודן\u0004 — \u0003פודה\u0004 את ה\u0003אילנות בשווין, וחוזר ופודה\u0004 את ה\u0003קרקע\u0004 לפי המחיר של \u0003בית זרע חומר שעורים בחמשים שקל כסף.\u0004 ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 \u0003רב הונא: אדם\u0004 ש\u0003מקדיש\u0004 — \u0003בעין יפה\u0004 (נדיבה) הוא \u0003מקדיש,\u0004 ולכן הקדיש כל דבר בפני עצמו, כדי לפדותו לחוד.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן לרב הונא\u0004 ממשנתנו: \u0003אחד המקדיש בחולת המחוז ואחד המקדיש בפרדיסות סבסטי, נותן בית זרע חומר שעורים בחמשים שקל כסף,\u0004 משמע שגם בפרדיסות אינו נותן יותר, למרות שיש שם עצים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרב נחמן: בקרקע \u0003ראויה לפרדיסות קאמינא\u0004 \u0005[אומר אני]\u0006 שמדובר במשנה, ולא בפרדס נטוע.","עוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב נחמן לרב הונא מברייתא: בפרשת המקדיש שדה אחוזה הוזכר דוקא \u0003בית זרע,\u0004 כלומר, שדה תבואה, שזורעים אותה, שנאמר: \"ואם משדה אחוזתו יקדיש איש לה' והיה ערכך לפי זרעו זרע חמר שערים בחמישים שקל כסף\" (ויקרא כז, טז) — \u0003אין לי אלא\u0004 \u0003בית זרע,\u0004 ואולם \u0003שדה גפנים, ושדה קנים, ושדה אילנות, מנין\u0004 שפודה לפי חשבון זה?","\u0003תלמוד לומר:\u0004 \"מ \u0003שדה\"\u0004 (\"ואם משדה אחוזתו יקדיש\", שם) \u0003מכל מקום,\u0004 שעל כל שדה נותן סכום זה, בין שזורעים אותה ובין שיש בה אילנות! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לפרש ש\u0003פודה\u0004 את האילנות \u0003וחוזר ופודה\u0004 את הקרקע לפי החשבון.","עוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב נחמן לרב הונא ממה ששנינו בברייתא: ד הקדיש שלשה אילנות הנטועים בצפיפות של \u0003מטע עשרה\u0004 אילנות \u0003ל\u0004שטח של \u0003בית סאה\u0004 — \u0003הרי זה הקדיש\u0004 גם \u0003את הקרקע ואת האילנות\u0004 הקטנים \u0003שביניהם,\u0004 מפני שפיזור זה ראוי לשדה אילנות, ולכן ברור שדעתו היתה לאילנות ולקרקע שהם גדלים בה, ו\u0003כשהוא פודה\u0004 — \u0003פודה\u0004 לפי חשבון \u0003בית זרע חומר שעורים בחמשים שקל כסף.\u0004","היו האילנות שהקדיש צפופים \u0003פחות מיכן,\u0004 \u0003או יתר על כן, או שהקדישן בזה אחר זה\u0004 — \u0003הרי זה לא הקדיש לא את הקרקע ולא את האילנות שביניהם,\u0004 אלא רק אותם.","\u0003ולא עוד,\u0004 לא רק במקרה שהקדיש את האילנות בלבד הריהם נפדים לעצמם, \u0003אלא אפילו הקדיש אילנותיו ואחר כך הקדיש\u0004 בפירוש גם את ה\u0003קרקע, כשהוא פודה\u0004 — \u0003פודה\u0004 תחילה \u0003את האילנות בשוויהן, וחוזר ופודה\u0004 את ה\u0003קרקע\u0004 לפי חשבון של \u0003בית זרע חומר שעורים בחמשים שקל כסף.\u0004 ומשמע שבדין הראשון, כשהוקדשו האילנות יחד עם הקרקע שביניהם, הריהם נפדים יחד לפי חשבון בית זרע שעורים בחמישים שקל, שלא כדברי רב הונא!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר ש\u0003פודה\u0004 את האילנות בשוויים \u0003וחוזר ופודה\u0004 קרקע לפי חשבון בית זרע שעורים בחמישים שקל, \u0003הא מדסיפא\u0004 \u0005[הלא ממה שבסוף]\u0006 נאמר ש\u0003פודה וחוזר ופודה, מכלל\u0004 הדברים אתה למד \u0003דרישא לא\u0004 \u0005[שבראש,\u0006 בדין הראשון, \u0005אין\u0006 עושים כך\u0005],\u0006 אלא פודים הכל יחד!","\u0003אלא\u0004 כך צריך לדחות קושיה זו: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: מקדיש בעין רעה\u0004 (כמה שפחות) הוא \u0003מקדיש,\u0004 ולכן כשהקדיש שלושה אילנות עם הקרקע שביניהם — הקדישם על דעת שייפדו אגב הקרקע, ולא בנפרד. ואילו רב הונא האומר שפודה אותם בפני עצמם, הולך כשיטת חכמים, שהמקדיש בעין יפה מקדיש. ומנין שלדעת ר' שמעון, המקדיש בעין רעה מקדיש? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003המקדיש את השדה\u0004 — \u0003הקדיש את כולה,\u0004 כל מה שמצוי בה באופן קבוע, גם מה שאינו נמכר בדרך כלל עם השדה, כגון בור וגת, וכן חרוב המורכב וסדן השקמה, שהם עצים חשובים. \u0003ר' שמעון אומר: לא הקדיש\u0004 כל מה שמצוי בה, מפני שהמקדיש בעין רעה מקדיש, \u0003אלא\u0004 רק \u0003חרוב המורכב וסדן השקמה\u0004 בלבד, מפני שאם אינו מקדישם, אלא משיירם לעצמו, נמצא שהם יונקים משל הקדש.","ומקשים על הסבר זה: \u0003אי\u0004 \u0005[אם]\u0006 אתה מפרש את הברייתא כשיטת \u0003ר' שמעון, אימא סיפא\u0004 \u0005[אמור את סופה]:\u0006 \u0003ולא עוד, אלא אפילו הקדיש אילנותיו ואחר כך הקדיש קרקע, כשהוא פודה\u0004 — \u0003פודה את האילנות בשוויהן, וחוזר ופודה בית זרע חומר שעורים בחמשים שקל כסף.\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' שמעון\u0004 היא — \u0003ליזיל בתר\u0004 \u0005[שנלך אחר]\u0006 שעת ה\u0003פדיון,\u0004 שאז גם הקרקע וגם העצים שייכים להקדש ועומדים לפדייה, \u0003וליפרקו אגב ארעייהו\u0004 \u0005[וייפדו\u0006 האילנות \u0005אגב הקרקע שלהם],\u0006 \u0003דהא שמעינן ליה\u0004 \u0005[שהרי שמענו אותו]\u0006 את \u0003ר' שמעון דאזיל בתר\u0004 \u0005[שהולך אחר]\u0006 שעת ה\u0003פדיון!\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין ללוקח\u0004 (קונה) \u0003שדה מאביו, והקדישה\u0004 הבן, \u0003ואחר כך מת אביו, מנין\u0004 שלא יפדה הבן את השדה בשוויה, כדין שדה שקנה והקדיש, אלא \u0003שתהא לפניו כשדה אחוזה,\u0004 כאילו ירש אותה מאביו ואחר כך הקדישה, ויפדה לפי חשבון בית זרע שעורים בחמישים שקל? \u0003תלמוד לומר\u0004 בפדיון שדה מקנה: \"ו \u0003אם את שדה מקנתו אשר לא משדה אחזתו\"\u0004 (ויקרא כז, כב), ללמדנו שרק אם הקדיש","\u0003שדה שאינה ראויה להיות שדה אחוזה\u0004 פודה אותה בשוויה, \u0003יצתה\u0004 שדה \u0003זו שראויה\u0004 היתה \u0003להיות שדה אחוזה\u0004 כשהקדישה, שהיא נפדית כשדה אחוזה, אלו \u0003דברי ר' יהודה ור' שמעון.\u0004","\u0003ר' מאיר אומר:\u0004 במקרה שהקדישה קודם שמת האב דינה כשדה מקנה. אלא כך יש ללמוד מן הכתוב: \u0003מנין ללוקח שדה מאביו, ו\u0004אחר כך \u0003מת אביו, ואחר כך הקדישה\u0004 הבן, \u0003מנין שתהא לפניו כשדה אחוזה?\u0004"],["\u0003תלמוד לומר:\u0004 \"ו \u0003אם את שדה מקנתו אשר לא משדה אחזתו\u0004 יקדיש לה' \"(ויקרא כז, כב), ללמד כי מדובר ב\u0003שדה שאינה שדה אחוזה\u0004 בשעה שהקדישה, \u0003יצתה\u0004 שדה \u0003זו\u0004 שהקדישה לאחר מות אביו, \u0003שהיא שדה אחוזה\u0004 בשעה שהקדישה.","ו\u0003אילו ל\u0004דעת \u0003ר' יהודה ול\u0004דעת \u0003ר' שמעון,\u0004 שנינו כי \u0003אפילו הקדישה ואחר כך מת אב,\u0004 מכיוון שבשעה שבא הבן לפדותה כבר מת האב — \u0003שדה אחוזה הויא\u0004 \u0005[היא].\u0006 ויש לשאול: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום קרא\u0004 \u0005[\u0006ה\u0005מקרא]\u0006 — שמא \u0003קרא\u0004 \u0005[\u0006ה\u0005מקרא]\u0006 \u0003ל\u0004למד את המקרה שדיבר עליו \u0003ר' מאיר הוא דאתא\u0004 \u0005[שבא]!\u0006","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 סבור כן ר' שמעון (ור' יהודה) \u0003משום דאזיל בתר\u0004 \u0005[ש\u0006הוא \u0005הולך\u0006 באופן עקרוני \u0005אחר]\u0006 שעת ה\u0003פדיון?\u0004 והואיל ובשעת הפדיון כבר מת אביו — הרי שדה זו נחשבת שדה אחוזה. ולדרך זו, המקדיש אילנות ואחר כך קרקע, צריך לפדותם יחדיו, שהרי בשעת הפדיון עומדים שניהם לפדייה, ולא כפי שנאמר בברייתא, שפודה כל אחד בפני עצמו. ואם כן, לא ניתן להעמיד ברייתא זו לשיטת ר' שמעון, כפי שהציע רב הונא!","\u0003אמר רב נחמן בר יצחק:\u0004 אין להקשות מכאן על רב הונא, שכן טעמו של ר' שמעון אינו משום שהוא הולך אחר שעת הפדיון, אלא \u0003ר' יהודה ור' שמעון קרא אשכחו ודרוש\u0004 \u0005[מקרא\u0006 זה \u0005מצאו ודרשו]\u0006 ממנו את דינם, ש","\u0003אם כן,\u0004 כדברי ר' מאיר, שרק שדה שהקדישה קודם מות אביו אינה בכלל שדה מקנה — \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]:\u0006 \u0003\"אם את שדה מקנתו אשר לא אחזתו\", מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 נאמר \"אשר לא \u0003משדה\u0004 אחוזתו\"? לומר שרק \u0003שדה שאינה ראויה\u0004 כלל \u0003להיות שדה אחוזה\u0004 בשעה שהקדישה — הריהי שדה מקנה ונפדית בשוויה, אבל אם הקדיש שדה שהוא עומד לירש אותה — נפדית מההקדש כשדה אחוזה.","\u0003אמר רב פפא: הקדיש\u0004 מאחוזתו \u0003טרשין,\u0004 קרקעות קשות ומסולעות — \u0003פודן בשווין,\u0004 ולא כדין שדה אחוזה (לפי חשבון בית זרע שעורים בחמישים שקל כסף), \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003בית זרע\u0004 \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \"והיה ערכך לפי זרעו\" (ויקרא כז, טז), \u0003והני לאו\u0004 \u0005[ואלה לא]\u0006 \u0003בני זריעה נינהו\u0004 \u0005[הם].\u0006","אך מצד אחר, אם המקדיש \u0003לא גאלן\u0004 — \u0003יוצאין ביובל\u0004 לכהנים, כדין שדה אחוזה, \u0003מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 \u0003\"שדה\" אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \"ואם לא יגאל את השדה... והיה השדה בצאתו ביובל קדש לה' כשדה החרם לכהן תהיה אחוזתו\" (שם כ—כא), שדה \u0003כל דהו\u0004 \u0005[כל שהוא],\u0006 ואפילו שדה טרשים.","\u0003מכר\u0004 מאחוזתו \u0003טרשין\u0004 — \u0003נגאלין\u0004 מהקונה אפילו עברו \u0003פחות משתי שנים\u0004 מאז שנמכרו, שלא כדין שדה אחוזה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \"ב \u0003מספר שני תבואות\u0004 ימכור לך\" (שם כה, טו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומשם למדו חכמים שאין גואלים לפני שתי שנים, \u0003והאי לאו\u0004 \u0005[ואלה,\u0006 טרשים, \u0005לא]\u0006 \u0003בני תבואה נינהו\u0004 \u0005[הם].\u0006 אך מצד אחר, אם \u0003לא גאלן\u0004 (פדאם) הבעלים מיד הקונה — \u0003חוזרת לבעלים ביובל,\u0004 כדין שדה אחוזה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \"ויצא ביובל \u0003ושב לאחזתו\"\u0004 (שם כה, כח) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והאי נמי\u0004 \u0005[וזו גם כן]\u0006 \u0003אחוזה היא.\u0004","ועוד הוסיף רב פפא: \u0003הקדיש\u0004 מאחוזתו \u0003אילנות\u0004 בלבד — \u0003פודה\u0004 אותם \u0003בשוויהן, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003בית זרע אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא אילנות.\u0004 ואם המקדיש \u0003לא גאלן\u0004 מיד ההקדש, ומכרן הגזבר — \u0003אין\u0004 האילנות \u0003יוצאין לכהנים ביובל,\u0004 מפני ש\u0003\"והיה השדה\u0004 בצאתו ביובל\" (ויקרא כז, כא) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003ולא אילנות.\u0004","\u0003מכר\u0004 מאחוזתו \u0003אילנות\u0004 בלבד — \u0003אין נגאלין\u0004 מהקונה לפני \u0003פחות משתי שנים, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003\"שני תבואות\u0004 ימכור לך\" (שם כה, טו) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומשם למדו חכמים שאין גואלים בפחות משתי שנים, \u0003והני\u0004 \u0005[ואלה]\u0006 האילנות \u0003בני תבואות נינהו\u0004 \u0005[הם].\u0006 ואם המוכר \u0003לא גאלן\u0004 מהקונה — \u0003אין\u0004 המכירה \u0003חוזרת לבעלים ביובל, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003\"ושב לאחזתו\"\u0004 (שם כז) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003ולא\u0004 ל\u0003אילנות\u0004 שאינם קיימים לעולם.","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם,\u0006 רב פפא\u0005]:\u0006 \u0003הקדיש\u0004 מאחוזתו \u0003אילנות\u0004 בלבד — \u0003פודה בשווין.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003וליקדשו אגב ארעייהו וליפרקוה אגב ארעייהו\u0004 \u0005[ושיתקדשו אגב הקרקע שלהם,\u0006 שהיא שדה אחוזה, \u0005וייפדו אגב הקרקע שלהם],\u0006 לפי חשבון בית זרע שעורים בחמישים שקל כסף!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אילנות אקדיש\u0004 \u0005[הקדיש],\u0006 \u0003ארעא לא אקדיש\u0004 \u0005[\u0006את \u0005הקרקע\u0006 שתחתם \u0005לא הקדיש]\u0006 — \u0003והאמרי נהרדעי\u0004 \u0005[והרי אמרו חכמי נהרדעא]:\u0006 \u0003מאן דמזבן ליה דקלא לחבריה\u0004 \u0005[מי שמוכר לו דקל לחבירו],\u0006 \u0003קני ליה משיפולא ועד תהומא\u0004 \u0005[קונה לו\u0006 גם קרקע \u0005מתחתית\u0006 הדקל \u0005ועד התהום]!\u0006 ומשיבים: \u0003לאו מי איתמר עלה\u0004 \u0005[האם לא נאמר עליה]\u0006 שמדובר שם \u0003בבא מחמת טענה,\u0004 שהקונה טוען שקנה במפורש גם את הקרקע שתחת האילן? אבל אם לא הזכירו במפורש את הקרקע שתחת האילן — אין דעת המוכר (ולענייננו, המקדיש) לתת אותה.","שנינו במשנה כי לדעת חכמים המקדיש \u0003שדה מקנה\u0004 ופודה — \u0003נותן שוויו,\u0004 ואילו ר' אליעזר סבור שדין שדה מקנה כדין שדה אחוזה לענין זה, שנפדית לפי חשבון בית זרע שעורים בחמישים שקל. אלא ההבדל ביניהם הוא, שאם הקדיש שדה אחוזה, כשהוא עצמו פודה אותה — מוסיף חומש, והמקדיש שדה מקנה ופודה אותה — אינו מוסיף חומש. ובביאור טעמיהם של ר' אליעזר וחכמים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: מה שנאמר בפדיון שדה מקנה \"במכסת\" (\"וחישב לו הכהן את מכסת הערכך עד שנת היובל\", ויקרא כז, כג) \u0003מה בא ללמוד? לפי שנאמר\u0004 בשדה אחוזה: \"והיה ערכך לפי זרעו \u0003זרע חמר שעורים בחמשים שקל כסף\"\u0004 (שם טז), \u0003יכול אף שדה מקנה כן? תלמוד לומר: \"מכסת\",\u0004 שמשמעו סכום דמיו, שוויו.","\u0003ר' אליעזר אומר: נאמר כאן\u0004 בשדה מקנה: \u0003\"וחשב\", ונאמר להלן\u0004 בשדה אחוזה: \u0003\"וחשב\"\u0004 (שם יח), \u0003מה להלן\u0004 בשדה אחוזה \u0003דבר קצוב,\u0004 בית זרע שעורים בחמישים שקל, \u0003אף כאן\u0004 בשדה מקנה — \u0003דבר קצוב\u0004 שנאמר לגבי שדה אחוזה.","איבעיא להו \u0005[נשאלה להם]\u0006 ללומדים: האם \u0003רבנן אית להו\u0004 \u0005[חכמים יש להם]\u0006 \u0003גזירה שוה\u0004 זו, שהשתמש בה ר' אליעזר, \u0003ומפקין ליה\u0004 \u0005[ו\u0006הם \u0005מוציאים אותו,\u0006 משתמשים בו\u0005]\u0006 \u0003ל\u0004ענין \u0003חומש,\u0004 שכשם שהמקדיש שדה אחוזה ופודהו בעצמו מוסיף חומש (שם יט) — גם הפודה שדה מקנה בעצמו מוסיף חומש, ושלא כדעת ר' אליעזר. \u0003או דלמא לית להו\u0004 \u0005[שמא אין להם]\u0006 \u0003גזירה שוה\u0004 זו, \u0003ולית להו\u0004 \u0005[ואין להם]\u0006 דין \u0003חומש\u0004 במקדיש שדה מקנה?","\u0003אמר רבא: מסתברא לית להו\u0004 \u0005[מסתבר\u0006 לומר ש\u0005אין להם]\u0006 \u0003גזירה שוה\u0004 זו; וטעם הדבר, \u0003מדגלי רחמנא\u0004 \u0005[מכיון שגילתה התורה]\u0006 שצריך הפודה בעצמו להוסיף \u0003חומש גבי\u0004 \u0005[אצל]\u0006 \u0003שדה אחוזה, וגבי\u0004 \u0005[ו\u0006גם \u0005אצל]\u0006 \u0003מקדיש ביתו\u0004 (שם טו), \u0003הוו ליה\u0004 \u0005[הרי הם]\u0006 \u0003שני כתובין הבאין כאחד,\u0004 שנאמר בהם אותו דין, אף שיכול היה להאמר רק באחד מהם, \u0003ו\u0004כלל הוא: \u0003כל שני כתובין הבאין כאחד אין מלמדין\u0004 למקום אחר, מפני שרואים אותם כיוצאים מן הכלל.","ומוסיפים: \u0003ולמאן דאמר\u0004 \u0005[ו\u0006גם לדעת \u0005מי שאומר]\u0006 ששני כתובים \u0003מלמדין\u0004 למקום אחר, \u0003מדגלי רחמנא\u0004 \u0005[מכיון שגילתה התורה]\u0006 שהפודה בעצמו מוסיף \u0003חומש\u0004 גם \u0003ב\u0004פודה \u0003מעשר\u0004 שני (שם לא), וגם \u0003ב\u0004פודה \u0003בהמה טהורה\u0004 שהקדישה ונפל בה מום (שם יג), \u0003ו\u0004גם \u0003ב\u0004פודה \u0003בהמה טמאה\u0004 שהקדישה לבדק הבית (שם כז) — \u0003הוה ליה טובא\u0004 \u0005[הרי הם\u0006 כתובים \u0005רבים]\u0006 הבאים כאחד, \u0003ואין מלמדין\u0004 לכל הדעות.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא\u0004 להלכה, \u0003ולא מטעמיה\u0004 \u0005[מטעמו],\u0006 וכך \u0003תניא\u0004 \u0005[\u0006היא \u0005שנויה]:\u0006 במה שאמרה התורה לגבי פדיון שדה מקנה \u0003\"במכסת הערכך\"\u0004 (שם כז, כג) \u0003הקישו הכתוב לערכין,\u0004 שנאמר בהם \"ערכך\" (שם ב), \u0003מה ערכין אין מוסיף חומש, אף שדה מקנה אין\u0004 הפודה בעצמו \u0003מוסיף חומש.\u0004","מה ששנינו בתחילת פרק זה שיש \u0003בשור המועד שהמית את העבד\u0004 צדדים \u0003להקל ולהחמיר, כיצד? אחד\u0004 שור \u0003שהמית את הנאה שבעבדים,\u0004 ששוויו מרובה, \u0003ו\u0004אחד שור שהמית \u0003את הכעור שבעבדים,\u0004 ששוויו מועט — \u0003נותן שלשים סלע\u0004 (שקל) האמורים בתורה (שמות כא, לב), ואולם אם \u0003המית\u0004 השור \u0003בן חורין\u0004 — \u0003נותן\u0004 בעליו את \u0003שוויו\u0004 ליורשיו. \u0003חבל\u0004 השור (הזיק) \u0003בזה ובזה\u0004 בבן חורין ובעבד — \u0003נותן\u0004 בעליו \u0003נזק שלם.\u0004","נאמר במשנה ששור שחבל באדם משלם נזק שלם, ומדייקים: \u0003ב\u0004שור \u0003מועד,\u0004 עליו דיברה המשנה מתחילה — \u0003אין\u0004 \u0005[כן]\u0006 שייך דין זה, \u0003ב\u0004שור \u0003תם\u0004 — \u0003לא,\u0004 שור תם שחבל באדם משלם חצי נזק, כדין שור תם שנגח שור. ושואלים: \u0003לימא מתניתין\u0004 \u0005[האם נאמר שמשנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא,\u0004 הסבור שדינו לשלם נזק שלם? ומניין שכך הוא סבור — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 לגבי שור ואדם שחבלו זה בזה, \u0003ר' עקיבא אומר: אף\u0004 שור \u0003תם שחבל באדם,\u0004 והזיק לו יותר ממה שהזיק לו האדם — \u0003משלם\u0004 בעליו של השור \u0003במותר\u0004 (בהפרש) שבין החבלות \u0003נזק שלם\u0004 כלומר, את מלוא ההפרש, ולא כדין שור תם שנגח שור, שמשלם את מחצית המותר!","ומשיבים: יש לפרש את משנתנו \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כשיטת \u0003ר' עקיבא,\u0004 ו\u0003הוא הדין\u0004 ש\u0003אפילו תם\u0004 שחבל באדם \u0003נמי\u0004 \u0005[גם כן]\u0006 משלם נזק שלם. \u0003ואיידי דקא בעי למתנא סיפא\u0004 \u0005[ו\u0006רק \u0005מתוך שהוא רוצה לשנות בסוף]\u0006 שאם \u0003המית עבד\u0004 נותן שלשים ואם \u0003המית בן חורין\u0004 נותן שוויו, ש\u0003במועד הוא דמשכחת לה\u0004 \u0005[שאתה מוצא אותה]\u0006 את ההבדל הזה, \u0003בתם לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה],\u0006 מפני ששור תם שהמית בין עבד ובין בן חורין בעליו פטורים — \u0003משום הכי קתני\u0004 \u0005[משום כך הוא שונה]\u0006 בתחילת המשנה שור \u0003מועד.\u0004","בפירוט מה ששנינו בתחילת פרק זה שיש \u0003באונס ובמפתה\u0004 נערה בתולה, צדדים \u0003להקל ולהחמיר, כיצד? אחד שאנס\u0004 או \u0003פיתה את\u0004 ה\u0003גדולה\u0004 (החשובה) \u0003שבכהונה\u0004 או \u0003את הקטנה\u0004 (הפשוטה) \u0003שבישראל\u0004 — \u0003נותן חמשים סלעים\u0004 בתשלום הקנס האמור בתורה (דברים כב, כט), \u0003והבושת והפגם\u0004 שצריך לשלם מלבד הקנס — אין להם קיצבה, אלא \u0003הכל לפי המבייש והמתבייש.\u0004","ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 צריך להוסיף תשלום עבור הבושת והפגם? \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003חמשים סלעים אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003מכל מילי\u0004 \u0005[מכל הדברים]!\u0006","\u0003אמר רב זעירא,\u0004 לא ניתן לומר כך, כי \u0003יאמרו\u0004 אנשים: אם \u0003בעל בת מלכים\u0004 שבושתה מרובה נותן \u0003חמשים,\u0004 ואם \u0003בעל בת הדיוטות\u0004 נותן גם כן \u0003חמשים?\u0004 אלא בוודאי יש להוסיף תשלום נפרד עבור הבושת והפגם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך]\u0006 לפי סברה זו, \u0003גבי\u0004 \u0005[אצל]\u0006 שור שהמית \u0003עבד נמי\u0004 \u0005[גם כן],\u0006 ששנינו שעל כל עבד אינו נותן אלא שלושים סלעים, \u0003יאמרו\u0004 בתמיהה: אם המית השור \u0003עבד נוקב מרגלית,\u0004 שערכו רב, נותן לבעליו \u0003שלשים\u0004 שקל, ואם המית \u0003עבד\u0004 ש\u0003עושה מעשה מחט\u0004 שהיא מלאכה פשוטה, נותן גם כן \u0003שלשים?\u0004 אלא בהכרח סכום קצוב וכולל הוא! \u0003אלא אמר רב זעירא:\u0004"],["\u0003אילו באו עליה שנים,\u0004 בתחילה \u0003אחד שלא כדרכה\u0004 ונותרה בתולה, \u0003ו\u0004אחריו \u0003אחד כדרכה,\u0004 והשני מתחייב בחמישים שקלים הכתובים בתורה, \u0003יאמרו\u0004 בתמיהה: זה השני ש\u0003בעל פגומה\u0004 נותן \u0003חמשים,\u0004 כדין אדם אחר ש\u0003בעל שלמה,\u0004 שגם הוא נותן \u0003חמשים?\u0004 אלא בוודאי יש הבדל ביניהן — בתשלום הבושת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך],\u0006 לפי סברה זו, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עבד נמי\u0004 \u0005[גם כן]\u0006 \u0003יאמרו:\u0004 שור שהמית \u0003עבד בריא,\u0004 שערכו מרובה, משלם \u0003שלשים,\u0004 כדין שור שהמית \u0003עבד מוכה שחין\u0004 שגם כן נותן \u0003שלשים,\u0004 והרי אין התורה מחלקת ביניהם!","\u0003אלא אמר אביי,\u0004 לא זה הטעם, אלא \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ונתן האיש השוכב עמה וכו' חמשים כסף... \u0003תחת אשר ענה\"\u0004 (דברים כב, כט), \u0003מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 תשלומים נוספים, שהם \u0003בושת ופגם.\u0004","\u0003רבא אמר\u0004 מכאן יש ללמוד, \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"ונתן האיש השכב עמה...\u0004 חמשים כסף\" \u0003וגו'\u0004 (שם), ומכאן יש לדייק — עבור \u0003הנאת שכיבה\u0004 נותן \u0003חמשים,\u0004 ו\u0003מכלל\u0004 הדברים אתה למד \u0003דאיכא מילתא אחריתי\u0004 \u0005[שיש דבר אחר]\u0006 שהוא משלם, \u0003ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 \u0003בושת ופגם.\u0004","מה ששנינו בראש פרק זה שיש \u0003במוציא שם רע\u0004 על אשתו, שנשאה ולא מצא לה בתולים (דברים כב, יג—יט) צדדים \u0003להקל ולהחמיר, כיצד? אחד שהוציא שם רע על גדולה\u0004 (חשובה) \u0003שבכהונה ו\u0004אחד שהוציא שם רע \u0003על קטנה\u0004 (פשוטה) \u0003שבישראל\u0004 — \u0003נותן מאה סלע\u0004 (שקל).","ומעירים: מגובה הקנס שהטילה התורה על מוציא שם רע, פי שנים ממה שהטילה על האונס או מפתה, \u0003נמצא\u0004 כי \u0003האומר בפיו\u0004 דבר רע, שטען שאין לה בתולים, \u0003חמור\u0004 בעונשו \u0003מן העושה\u0004 דבר זה ב\u0003מעשה,\u0004 כשבעל בתולה. ומוסיפים: \u0003שכן\u0004 גם \u0003מצינו שלא נתחתם גזר דין על אבותינו במדבר\u0004 שלא ייכנסו לארץ, \u0003אלא על\u0004 עוון \u0003לשון הרע,\u0004 שהוציאו המרגלים דיבת הארץ רעה, \u0003שנאמר\u0004 באותה שעה: \"כי כל האנשים הרואים את כבודי וכו' \u0003וינסו אותי זה עשר פעמים...\u0004 אם יראו את הארץ\" (במדבר יד, כב—כג).","שנינו במשנה כי מעונשו של מוציא שם רע למדנו שחמור עונשו של האומר בפיו יותר מהעושה מעשה. ושואלים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 אתה מוכיח? \u0003דלמא\u0004 \u0005[שמא\u0006 עונשו חמור\u0005]\u0006 \u0003משום דקא גרים לה קטלא\u0004 \u0005[שהוא\u0006 עומד \u0005לגרום לה מיתה]\u0006 באמירה זו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואם אמת היה הדבר וגו' והוציאו את הנערה\u0004 אל פתח בית אביה וסקלוה\" (דברים כב, כ—כא)!","\u0003אמר רבא, אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין זה: \"וענשו אתו מאה כסף... \u0003כי הוציא שם רע\"\u0004 (שם כב, יט), משמע ש\u0003על שם רע שהוציא\u0004 עליה הוא נענש.","שנינו במשנה: \u0003וכן מצינו שלא נתחתם גזר דין\u0004 על אבותינו במדבר אלא על לשון הרע. ושואלים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 שעוון זה כשלעצמו גרם עונש זה? \u0003דלמא דאכתי\u0004 \u0005[שמא\u0006 לא נענשו עד אז משום שעדיין] \u0003לא מלא\u0004 \u0003סאתן\u0004 כלומר, מידת העבירות הראויה להם לקבלת העונש. ש\u0003אמר רב המנונא: אין הקדוש ברוך הוא נפרע מן האדם עד שתתמלא סאתו,\u0004 \u0003שנאמר: \"במלאת ספקו יצר לו\"\u0004 (איוב כ, כב), כלומר, כשתתמלא מידתו דיה (\"ספקו\") בעבירות — אז יצר לו!","\u0003אמר ריש לקיש, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וינסו אותי זה עשר פעמים\"\u0004 (במדבר יד, כב), והמלה \"זה\", המיותרת לכאורה, באה להדגיש: \u0003על זה,\u0004 כלומר, על הוצאת דיבת הארץ, \u0003נתחתם גזר דין.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אלעזר בן פרטא: בוא וראה כמה גדול כח של לשון הרע, מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003מ\u0004העונש שבא על חטא \u0003מרגלים; ומה המוציא שם רע על עצים ואבנים\u0004 של ארץ ישראל \u0003כך\u0004 עונשו, \u0003המוציא שם רע על חבירו על אחת כמה\u0004 \u0003וכמה!\u0004","ושואלים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 שזה הוא הטעם? \u0003דלמא\u0004 \u0005[שמא]\u0006 נענשו כך \u0003משום\u0004 העוון שהוזכר בדברי \u0003ר' חנינא בר פפא,\u0004 ש\u0003אמר ר' חנינא בר פפא: דבר גדול,\u0004 חמור במיוחד, \u0003דברו מרגלים באותה שעה,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"לא נוכל לעלות אל העם \u0003כי חזק הוא ממנו\"\u0004 (במדבר יג, לא), \u0003אל תיקרי\u0004 (תקרא) \u0003\"כי חזק הוא ממנו\"\u0004 במשמעות: חזק מאיתנו, \u0003אלא: ממנו,\u0004 ורמזו לקדוש ברוך הוא, \u0003כביכול, בעל הבית אין יכול להוציא כליו משם,\u0004 אינו יכול לשלוט בארץ זו. ואולי נענשו בחומרה על דברי הכפירה שדיברו!","\u0003אלא אמר רבה אמר ריש לקיש, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וימותו האנשים מוצאי דבת הארץ רעה\"\u0004 (שם יד, לז), משמע כי \u0003על דבת הארץ שהוציאו\u0004 נענשו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' יהודה, עשר נסיונות ניסו אבותינו להקדוש ברוך הוא: שנים בים\u0004 (בים סוף), \u0003ושנים במים, שנים במן, שנים בשליו, אחת בעגל, ואחת במדבר פארן.\u0004","ומפרטים: \u0003שנים בים\u0004 — פעם \u0003אחת בירידה ו\u0004פעם \u0003אחת בעלייה. בירידה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 קודם שנקרע להם הים: \u0003\"המבלי אין קברים במצרים\u0004 לקחתנו למות במדבר\" (שמות יד, יא).","\u0003בעלייה\u0004 — \u0003כ\u0004מו שאמר \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: ישראל שבאותו הדור מקטני אמנה היו,\u0004 ולא האמינו שהם נגאלים, \u0003כ\u0004דברי \u0003רבה בר מרי,\u0004 ש\u0003אמר רבה בר מרי, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וימרו על ים בים סוף ויושיעם למען שמו\"\u0004 (תהלים קו, ז—ח)? \u0003מלמד שהיו ישראל ממרים באותה שעה,\u0004 ולא האמינו במה שאמר להם ה' \"לא תוסיפו לראותם עוד\" (שמות יד, יג), \u0003ו\u0004היו \u0003אומרים: כשם שאנו עולים מצד זה כך מצרים עולים מצד אחר.\u0004","\u0003אמר לו הקדוש ברוך הוא לשר\u0004 (מלאך, ממונה) \u0003של ים: פלוט אותם\u0004 את המצרים המתים \u0003ליבשה,\u0004 כדי שיראו ישראל ויאמינו. \u0003אמר\u0004 שר הים \u0003לפניו: רבונו של עולם, כלום יש עבד שנותן לו רבו מתנה\u0004 (את המתים האלו) \u0003וחוזר ונוטלה הימנו? אמר לו: אני נותן לך\u0004 תמורת המצרים פי \u0003אחד ומחצה שבהם,\u0004 שכנגד שש מאות רכב של מצרים יקבל שר הים תשע מאות רכב של סיסרא (שופטים ד, יג).","\u0003אמר לפניו: רבונו של עולם, כלום יש עבד שתובע את רבו?\u0004 וממי אתבע את חובי? \u0003אמר ללו\u0004 הקדוש ברוך הוא: \u0003נחל קישון יהיה ערב,\u0004 ותוכל לתבוע אותו. \u0003מיד פלטן\u0004 ים סוף \u0003ליבשה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וירא ישראל את מצרים מת על\u0004 שפת הים\" (שמות יד, ל), ורק אז נאמר: \"ויאמינו בה' ובמשה עבדו\" (שם לא).","\u0003שנים,\u0004 שני נסיונות שניסו אבותינו את הקב\"ה \u0003במים\u0004 — אחד \u0003במרה ו\u0004אחד \u0003ברפידים.\u0004 אחד \u0003במרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבואו מרתה ולא יכלו לשתות\"\u0004 (שם טו, כג), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם: \u0003\"וילן העם על משה\"\u0004 (שם טו, כד).","אחד \u0003ברפידים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויחנו ברפידים ואין מים לשתות\"\u0004 (שם יז, א), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם: \u0003\"וירב העם עם משה\"\u0004 (שם יז, ב).","\u0003שנים במן:\u0004 פעם אחת \u0003דכתיב\u0004 \u0005[שנאמר]: בדברי משה אל העם:\u0006"],["\u0003אל תצאו\u0004 לשדה ללקוט מן בשבת, מפני שלא תמצאוהו (ראה שמות טז, כה), \u0003ו\u0004למרות זאת \u0003יצאו\u0004 (שם כז). וכן אמר להם: \u0003אל תותירו\u0004 מן המן עד בקר (שם יט), \u0003ויותירו\u0004 (שם כ).","מה ששנינו לגבי הנסיונות: \u0003שנים\u0004 בשליו, כוונתו — \u0003בשליו ראשון ובשליו שני.\u0004 ומפרטים: \u0003בשליו ראשון\u0004 — שנאמר: \"מי יתן מותנו ביד ה' בארץ מצרים \u0003בשבתנו על סיר הבשר\"\u0004 (שם טז, ג), ואז ניתן להם השליו (שם יג).","\u0003בשליו שני\u0004 — שנאמר: \u0003\"והאספסף אשר בקרבו\u0004 התאוו תאוה וישובו ויבכו גם בני ישראל ויאמרו מי יאכילנו בשר\" (במדבר יא, ד).","הנסיון \u0003בעגל\u0004 — \u0003כדאיתיה\u0004 \u0005[כמו שהוא]\u0006 כתוב בתורה (שמות פרק לב). הנסיון \u0003במדבר פארן\u0004 — חטא המרגלים \u0003כדאיתיה\u0004 \u0005[כמו שהוא]\u0006 בתורה (במדבר פרק יג).","ושבים לעסוק בחומרתו של דיבור רע. \u0003אמר ר' יוחנן משום ר' יוסי בן זימרא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מה יתן לך ומה יסיף לך לשון רמיה\"\u0004 (תהלים קכ, ג)? \u0003אמר לו הקדוש ברוך הוא ללשון: כל אבריו של אדם זקופים ואתה מוטל\u0004 (שוכב), \u0003כל אבריו של אדם\u0004 נמצאים \u0003מבחוץ ואתה מבפנים, ולא עוד, אלא שהקפתי לך שתי חומות, אחת של עצם\u0004 (שיניים), \u0003ואחת של בשר\u0004 (שפתיים), ואם שמירה זו לא הועילה, \u0003מה יתן לך ומה יסיף לך,\u0004 מה עוד יועיל למנוע \u0003לשון רמיה?\u0004","ועוד \u0003אמר ר' יוחנן משום ר' יוסי בן זימרא: כל המספר לשון הרע כאילו כפר בעיקר\u0004 (באדון העולם), \u0003שנאמר: \"אשר אמרו ללשננו נגביר שפתינו אתנו מי אדון לנו\"\u0004 (שם יב, ה).","\u0003ואמר ר' יוסי בן זימרא: כל המספר לשון הרע\u0004 — \u0003נגעים\u0004 (צרעת) \u0003באים עליו, שנאמר: \"מלשני בסתר רעהו אותו אצמית\"\u0004 (שם קא, ה), \u0003ו\u0004מניין ש\"אצמית\" הוא לשון נגעים? \u0003כתיב התם\u0004 \u0005[נאמר שם]:\u0006 \"והארץ לא תמכר \u0003לצמיתות\"\u0004 (ויקרא כה, כג), \u0003ומתרגמינן\u0004 \u0005[ומתרגמים אנו]:\u0006 \u0003לחלוטין,\u0004","\u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 לשון זו לגבי צרעת: \u0003אין בין מצורע מוסגר,\u0004 שלא נתברר אם יש בו נגע, \u0003למצורע מוחלט\u0004 לטומאה, \u0003אלא פריעה ופרימה,\u0004 שהמוחלט צריך לפרוע את ראשו ולפרום את בגדיו (ויקרא יג, מה).","וכן \u0003אמר ריש לקיש, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"זאת תהיה תורת המצורע\"\u0004 (שם יד, ב)? הרי זה נדרש: \u0003זאת תהיה תורתו של מוציא שם רע\u0004 (מצורע — מוציא רע), שנגעים באים עליו על שהוציא שם רע.","\u0003ואמר ריש לקיש מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אם ישך הנחש בלא לחש ואין יתרון לבעל הלשון\"\u0004 (קהלת י, יא)? מהו הקשר בין הדברים? \u0003לעתיד לבא מתקבצות כל החיות ובאות אצל נחש, ואומרות\u0004 לו: \u0003ארי דורס\u0004 בעלי חיים בכפותיו \u0003ואוכל\u0004 מה שדורס, \u0003זאב טורף\u0004 בפיו \u0003ואוכל\u0004 מה שטורף, \u0003אתה,\u0004 כשאתה מכיש והורג — \u0003מה הנאה יש לך,\u0004 שהרי אינך יכול לאכול את כל אלה שאתה מכיש? \u0003אומר להם: וכי מה יתרון\u0004 (רווח) יש \u0003לבעל הלשון,\u0004 שמספר לשון הרע?","\u0003ואמר ריש לקיש: כל המספר לשון הרע\u0004 \u0003מגדיל עו‍נות עד לשמים, שנאמר: \"שתו בשמים פיהם ולשונם תהלך בארץ\"\u0004 (תהלים עג, ט), כלומר, למרות שלשונו מהלכת בארץ — עוונו מגיע עד לשמים.","\u0003אמר רב חסדא אמר מר עוקבא: כל המספר לשון הרע ראוי לסוקלו באבן, כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \"מלשני בסתר רעהו \u0003אותו אצמית\"\u0004 (שם קא, ג), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"צמתו בבור חיי וידו אבן בי\"\u0004 (איכה ג, נג).","\u0003ואמר רב חסדא אמר מר עוקבא: כל המספר לשון הרע, אמר הקדוש ברוך הוא: אין אני והוא יכולין לדור\u0004 יחד \u0003בעולם, שנאמר: \"מלשני בסתר רעהו אותו אצמית גבה עינים ורחב לבב אתו לא אוכל\"\u0004 (תהלים קא, ג), \u0003אל תיקרי\u0004 \u0005[אל תקרא]\u0006 \u0003\"אותו לא אוכל\", אלא: \"אתו לא אוכל\",\u0004 כלומר, אין אני יכול להיות איתו במציאות אחת. \u0003ואיכא דמתני לה\u0004 \u0005[ויש ששונים דבר זה]\u0006 \u0003על גסי הרוח,\u0004 כלומר, על \"גבה עיניים\" שמוזכר באותו פסוק.","ועוד \u0003אמר רב חסדא אמר מר עוקבא: כל המספר לשון הרע, אומר הקדוש ברוך הוא לגיהנם: אני עליו מלמעלה ואתה עליו מלמטה נדוננו\u0004 כלומר, נעניש אותו, \u0003שנאמר: \"חצי גבור שנונים עם גחלי רתמים\"\u0004 (שם קכ, ד), \u0003אין חץ\u0004 שנאמר שם \u0003אלא לשון\u0004 הרע, \u0003שנאמר: \"חץ שחוט לשונם מרמה דבר\"\u0004 (ירמיהו ט, ז),","\u0003ואין גבור אלא הקדוש ברוך הוא, שנאמר: \"ה' כגבור יצא\"\u0004 (ישעיהו מב, יג), והוא מעניש את החוטא מדה כנגד מדה בחיציו השנונים, ו\u0003גחלי רתמים\u0004 שהן לוהטות לאורך זמן, \u0003היינו\u0004 אש ה\u0003גיהנם.\u0004","\u0003אמר ר' חמא בר' חנינא: מה תקנתו של\u0004 מי שהיה מ\u0003מספרי לשון הרע? אם תלמיד חכם הוא\u0004 — \u0003יעסוק בתורה, שנאמר: \"מרפא לשון עץ חיים\"\u0004 (משלי טו, ד), \u0003ואין לשון אלא לשון הרע, שנאמר: \"חץ שחוט לשונם\", ואין עץ\u0004 חיים \u0003אלא תורה, שנאמר: \"עץ חיים היא למחזיקים בה\"\u0004 (שם ג, יח). \u0003ואם עם הארץ הוא ישפיל דעתו, שנאמר\u0004 בהמשך הפסוק: \u0003\"וסלף בה שבר\u0004 ב\u0003רוח\"\u0004 כלומר, מי שסילף (עיוות וקלקל) בלשונו — תקנתו שברון הלב.","ר' אחא בר' חנינא אומר: מי ש\u0003סיפר\u0004 לשון הרע \u0003אין לו תקנה, שכבר כרתו דוד\u0004 (גרם לו עונש כרת) \u0003ברוח הקדש, שנאמר: \"יכרת ה' כל שפתי חלקות לשון מדברת גדלות\"\u0004 (תהלים יב, ד), \u0003אלא מה תקנתו\u0004 מתחילה \u0003שלא יבא לידי לשון הרע? אם תלמיד חכם הוא\u0004 — \u0003יעסוק בתורה, ואם עם הארץ הוא\u0004 — \u0003ישפיל דעתו, שנאמר: \"וסלף בה שבר\u0004 ב\u0003רוח\",\u0004 וכשהוא עניו ודעתו שפלה אינו דובר רעות על רעהו.","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל המספר לשון הרע מגדיל עו‍נות כנגד שלש עבירות\u0004 חמורות, \u0003עבודה זרה וגילוי עריות ושפיכות דמים,\u0004 ומנין? \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"לשון מדברת גדלות\"\u0004 שם יב, ד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003בעבודה זרה,\u0004 בחטא העגל: \u0003\"אנא חטא העם הזה חטאה גדלה\"\u0004 (שמות לב, לא), ו","\u0003בגילוי עריות כתיב\u0004 \u0005[נאמר]\u0006 בנסיון יוסף באשת פוטיפר: \u0003\"ואיך אעשה הרעה הגדלה הזאת\"\u0004 (בראשית לט, ט). ו\u0003בשפיכות דמים כתיב\u0004 \u0005[נאמר]\u0006 כשרצח קין את הבל: \u0003\"גדול עו‍ני מנשא\"\u0004 (שם ד, יג). ומכך שבכל אחת מהעברות הללו נאמר \"גדול\" או \"גדולה\", ואלו בלשון הרע נאמר \"גדולות\" משמע שהוא גדול כנגד שלושתם.","ושואלים: \u0003\"גדולות\"\u0004 הוא אמנם לשון רבים, אך מיעוט רבים שנים, ו\u0003אימא תרתי\u0004 \u0005[אמור\u0006 רק כנגד \u0005שתים\u0006 מאלה\u0005]!\u0006 ומשיבים: \u0003הי מינייהו מפקא\u0004 \u0005[איזו מהן אתה מוציא]?\u0006 ומכיוון שאין עדיפות לעבירה אחת על פני האחרת — שלושתן בכלל זה.","\u0003במערבא אמרי\u0004 \u0005[בארץ ישראל היו אומרים]:\u0006 \u0003לשון תליתאי\u0004 \u0005[שלישי],\u0006 כלומר, לשון הרע, \u0003קטיל תליתאי\u0004 \u0005[הורג שלושה],\u0006 \u0003הורג למספרו, ולמקבלו, ולאומרו,\u0004 כלומר, לזה שאומרים עליו.","\u0003אמר ר' חמא בר' חנינא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מות וחיים ביד לשון\"\u0004 (משלי יח, כא), \u0003וכי יש יד ללשון?\u0004 אלא \u0003לומר לך: מה יד ממיתה\u0004 — \u0003אף לשון ממיתה.\u0004 ויכול אתה לומר: \u0003אי\u0004 \u0005[אם כן]\u0006 אמור: \u0003מה יד אינה ממיתה אלא בסמוך לה,\u0004 עד היכן שידו של אדם מגיעה — \u0003אף לשון אינה ממיתה אלא בסמוך לה? תלמוד לומר: \"חץ שחוט לשונם\",\u0004 כחץ שיורים בקשת.","\u0003אי\u0004 \u0005[אם כן]\u0006 תאמר: \u0003מה חץ\u0004 מגיע \u0003עד ארבעים ו\u0004עד \u0003חמישים אמה, אף לשון\u0004 ממיתה \u0003עד ארבעים וחמשים אמה? תלמוד לומר: \"שתו בשמים פיהם ולשונם תהלך בארץ\",\u0004 עד קצה העולם.","ושואלים: \u0003וכי מאחר דכתיב\u0004 \u0005[שנאמר]\u0006 כבר \u0003\"שתו בשמים פיהם\",\u0004 שלשון הרע פוגעת למרחוק, \u0003\"חץ שחוט לשונם\" למה לי\u0004 לומר? ומשיבים: \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 \u0003דקטיל\u0004 \u0005[ש\u0006הלשון \u0005הורג]\u0006 \u0003כ\u0004שם ש\u0003חץ\u0004 הורג.","ושואלים: \u0003וכי מאחר דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"חץ שחוט לשונם\", \"מות וחיים ביד לשון\" למה לי\u0004 לומר? ומשיבים: דבר זה נצרך \u0003ל\u0004השמיע כמו שאמר \u0003רבא,\u0004 ש\u0003אמר רבא: דבעי\u0004 \u0005[\u0006מי \u0005שרוצה]\u0006 \u0003חיים\u0004 — \u0003בלישניה\u0004 \u0005[בלשונו],\u0006 כלומר, ישתמש בה לדיבורים טובים ודברי תורה, \u0003דבעי\u0004 \u0005[\u0006מי \u0005שרוצה]\u0006 \u0003מיתה\u0004 — ישתמש \u0003בלישניה\u0004 \u0005[בלשונו],\u0006 לדברי נבלה ולשון הרע.","ושואלים: \u0003היכי דמי לישנא בישא\u0004 \u0005[איך היא לשון הרע],\u0006 כלומר, עד היכן מגיע איסור לשון הרע? מה נכלל בו? \u0003רבא אמר: כגון\u0004 ש\u0003אמר \"איכא נורא בי פלניא\"\u0004 \u0005[יש אש בבית פלוני],\u0006 ורוצה לרמז בזה שתמיד מבשלים ואוכלים שם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי קא עביד\u0004 \u0005[מה הוא עושה\u0006 רע\u0005]?\u0006 \u0003גלויי מילתא בעלמא\u0004 \u0005[גילוי דברים בלבד]\u0006 \u0003הוא\u0004 מה שדיבר! \u0003אלא\u0004 מתי יש בכך איסור — \u0003דמפיק בלישנא בישא\u0004 \u0005[שמוציא\u0006 את דבריו \u0005בלשון הרע],\u0006 \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003היכא משתכח נורא אלא בי פלניא\u0004 \u0005[איפה מצויה אש אם לא בביתו של פלוני],\u0006 שמבשלים שם כל היום.","\u0003אמר רבה: כל מילתא דמיתאמרא באפי מרה\u0004 \u0005[כל דבר שנאמר בפני בעליו],\u0006 כלומר, בפני מי שנאמר עליו — \u0003לית בה משום לישנא בישא\u0004 \u0005[אין בו משום לשון הרע].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003כל שכן\u0004 שהוא חמור יותר, שהרי יש בזה גם \u0003חוצפא ו\u0004גם \u0003לישנא בישא\u0004 \u0005[לשון הרע]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה לאביי: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי סבירא לי\u0004 \u0005[סבור אני],\u0006 ש\u0003אמר ר' יוסי: מימי לא אמרתי דבר וחזרתי לאחורי\u0004 לראות מי שומע אותי, מפני שהייתי מוכן לומר את הדבר גם בפניו, ודבר זה אינו מוגדר כלשון הרע. \u0003אמר\u0004"],["\u0003רבה בר רב הונא: כל מילתא דמיתאמרא באפי תלתא לית בה משום לישנא בישא\u0004 \u0005[כל דבר שנאמר\u0006 מתחילה \u0005בפני שלושה\u0006 \u0005אין בו משום לשון הרע]\u0006 אם חוזרים ואומרים אותו. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 כי \u0003חברך חברא אית ליה\u0004 \u0005[חברך, חבר יש לו],\u0006 \u0003וחברא דחברך חברא אית ליה\u0004 \u0005[וחבר של חברך, חבר יש לו],\u0006 וכל אחד מהם מספר לחברו, וכשנאמר הדבר בפני שלושה יש להניח שסופו להתפרסם.","ועוד בעניינים של דיבורים טובים ורעים, מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מברך רעהו בקול גדול בבוקר השכם, קללה תחשב לו\"\u0004 (משלי כז, יד)? \u0003כגון דמיקלע לאושפיזא וטרחו קמיה שפיר\u0004 \u0005[ש\u0006אדם \u0005מזדמן אצל מי שמארח\u0006 אותו, \u0005וטורחים לפניו יפה],\u0006 \u0003למחר נפיק יתיב בשוקא ואמר\u0004 \u0005[\u0006הוא \u0005יוצא\u0006 ו\u0005יושב בשוק ואומר]:\u0006 \u0003רחמנא ניברכיה לפלניא דהכי טרח קמאי\u0004 \u0005[הקב\"ה יברך את פלוני שכך טרח לפני]!\u0006 \u0003ושמעין אינשי ואזלין ואנסין ליה\u0004 \u0005[ושומעים אנשים והולכים ומכריחים אותו]\u0006 לארח אותם, ומכלים את ממונו, ונמצא שעל ידי דבורי הברכה שלו הביא קללה למארחו.","ועוד בענין זה, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב דימי אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב ספרא: לעולם אל יספר אדם בטובתו של חבירו\u0004 בפני אחרים, \u0003שמתוך טובתו בא לידי רעתו.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ששמועה זו נאמרה באופן אחר: \u0003רב דימי אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב ספרא חלש\u0004 \u0005[חלה],\u0006 \u0003על\u0004 \u0005[נכנס]\u0006 \u0003רב ספרא לשיולי ביה\u0004 \u0005[לשאול בו]\u0006 בשלומו, \u0003אמר להו\u0004 \u0005[להם]\u0006 רב דימי לנוכחים שם: \u0003תיתי לי דקיימי כל דאמר רבנן\u0004 \u0005[תבוא לי\u0006 ברכה, תעמוד לי זכותי על \u0005שקיימתי כל מה שאמרו חכמים\u0006 לעשות\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ספרא לרב דימי: \u0003הא מי מקיימת\u0004 \u0005[\u0006דבר \u0005זה האם קיימת]\u0006 — \u0003לעולם אל יספר אדם בטובתו של חבירו, שמתוך טובתו בא לידי גנותו? אמר להו\u0004 \u0005[להם]\u0006 רב דימי לנוכחים: \u0003לא שמיעא לי\u0004 \u0005[לא שמעתי אותה]\u0006 את האמירה הזו, \u0003ואי הוה שמיעא לי קיימתה\u0004 \u0005[ואם הייתי שומע אותה הייתי מקיים אותה].\u0006","\u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן, על שבעה דברים נגעים\u0004 של צרעת \u0003באין: על לשון הרע, ועל שפיכות דמים, ועל שבועת שוא, ועל גילוי עריות, ועל גסות הרוח\u0004 (גאוה), \u0003ועל הגזל, ועל צרות העין.\u0004","ומפרטים: \u0003על לשון הרע\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מלשני בסתר רעהו אותו אצמית\"\u0004 (תהלים קא, ה), והתבאר בעמוד הקודם (טו,ב) ש\"אצמית\" מרמז לצרעת.","\u0003על שפיכות דמים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 ביואב על שהרג את אבנר: \u0003\"ואל יכרת מבית יואב זב ומצרע\" וגו'\u0004 (שמואל ב ג, כט).","\u0003ועל שבועת שוא\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר נעמן הואל קח ככרים\"\u0004 (מלכים ב ה, כג) ופירשו חכמים כי \"הואל\" היא שבועה, שנעמן השביע את גיחזי שאלישע שלחו לקבל ממנו מתנה, \u0003ו\u0004כשנודע הדבר לאלישע וקיללו, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וצרעת נעמן תדבק בך\u0004 ובזרעך לעולם\" (שם כז).","\u0003ועל גילוי עריות\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וינגע ה' את פרעה נגעים\u0004 גדולים ואת ביתו על דבר שרי אשת אברם\" (בראשית יב, יז), שרצה לשכב עם אשת איש.","\u0003ועל גסות הרוח\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בעוזיהו: \u0003\"ובחזקתו גבה לבו עד להשחית וימעול בה' אלהיו... והצרעת זרחה במצחו\"\u0004 (דברי הימים ב כו, ט—יט).","\u0003ועל הגזל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי נגעי הבתים: \u0003\"וצוה הכהן ופנו את הבית\u0004 בטרם יבא הכהן לראות את הנגע\" (ויקרא יד, לו), ו\u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]\u0006 בסיבת ביאת הנגע: \u0003הוא כונס\u0004 (אוסף) \u0003ממון שאינו שלו, יבא הכהן ויפזר ממונו.\u0004","\u0003ועל צרות העין\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בנגעי בתים: \u0003\"ובא אשר לו הבית\u0004 והגיד לכהן לאמר כנגע נראה לי בבית\" (שם יד, לה), \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: מי שמיוחד ביתו לו,\u0004 כלומר, מי שהוא צר עין, ואינו מהנה אנשים ממה שיש לו, סופו שנידון בנגעים.","ושואלים: \u0003איני\u0004 \u0005[כן הוא]\u0006 שלשון הרע אין לו כפרה, אלא נגעים באים עליו? \u0003והא\u0004 \u0005[והרי]\u0006 אמר ר' ענני בר ששון: למה נסמכה פרשת בגדי כהונה (שמות פרק כח) \u0003לפרשת קרבנות\u0004 (שם פרק כט)? \u0003לומר לך: מה קרבנות מכפרין\u0004 — \u0003אף בגדי כהונה מכפרין.\u0004 ומפרטים, כיצד: \u0003כתונת מכפרת על\u0004 עוון \u0003שפיכות דמים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 באחי יוסף, לאחר שביקשו להמיתו: \u0003\"ויטבלו את הכתנת בדם\"\u0004 (בראשית לז, לא). \u0003מכנסים מכפרים על גילוי עריות\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשה להם מכנסי בד לכסות בשר ערוה\"\u0004 (שמות כח, מב), רמז הוא שמכנסים מכסים ומכפרים על עוון ערווה.","\u0003מצנפת מכפרת על גסי הרוח,\u0004 וטעם הדבר — \u0003כ\u0004מו שאמר \u0003ר' חנינא,\u0004 ש\u0003אמר ר' חנינא: יבא דבר שבגובה,\u0004 כלומר, המצנפת, \u0003ויכפר על מעשה גובה,\u0004 גאוה. \u0003אבנט מכפרת על הרהור הלב\u0004 — \u0003אהיכא דאיתיה\u0004 \u0005[על מקום שהוא נמצא],\u0006 \u0003דכתיב \"והיה על לב אהרן\"\u0004 (שם ל), שהאבנט היה חגור, כנגד המרפקים, בגובה הלב.","\u0003חושן מכפר על\u0004 עיוות ועינוי \u0003הדינין, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשית חשן משפט\"\u0004 (שם טו), ומשפט הוא דין. \u0003אפוד מכפר על עבודה זרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ו \u0003אין אפוד ותרפים\"\u0004 (הושע ג, ד), ויש בכך רמז שכאשר אין אפוד — נענשים על עוון התרפים, פסלים של עבודה זרה. \u0003מעיל\u0004 של כהן גדול \u0003מכפר על לשון הרע\u0004 — ש\u0003אמר הקדוש ברוך הוא: יבא דבר שבקול,\u0004 המעיל שיש בו פעמונים, \u0003ויכפר על מעשה הקול\u0004 של לשון הרע.","\u0003ציץ\u0004 של הכהן הגדול \u0003מכפר על מעשה עזי פנים\u0004 (חוסר בושה) — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בציץ: \u0003\"והיה על מצח אהרן\"\u0004 (שמות כח, לח), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ומצח אשה זונה היה לך\u0004 מאנת הכלם\" (ירמיה ג, ג). הרי שהמעיל מכפר על לשון הרע, ומדוע נאמר כי נגעים באים על כך!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 — \u0003דאהנו מעשיו, הא\u0004 — \u0003דלא אהנו מעשיו\u0004 \u0005[זה\u0006 — במקרה \u0005שהועילו מעשיו, זה\u0006 — \u0005שלא הועילו מעשיו].\u0006 ומבארים: \u0003אי אהנו\u0004 \u0005[אם הועילו]\u0006 \u0003מעשיו\u0004 וגרמו לנזק או למריבה — \u0003אתו נגעים עליה\u0004 \u0005[באים נגעים עליו],\u0006 \u0003אי לא אהנו\u0004 \u0005[אם לא הועילו]\u0006 \u0003מעשיו\u0004 — \u0003מעיל מכפר.\u0004","וביחס למה שנאמר שבגדי כהונה מכפרים על כל אותן עבירות, שואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' סימון אמר ר' יהושע בן לוי: שני דברים לא מצינו\u0004 שתהיה \u0003להם בקרבנות\u0004 אפשרות \u0003כפרה,\u0004 אבל \u0003בדבר אחר מצינו להם כפרה,\u0004 והם: \u0003שפיכות דמים ולשון הרע, שפיכות דמים\u0004 מתכפרת \u0003בעגלה ערופה,\u0004 כמו שנאמר: \"ונכפר להם הדם\" (דברים כא, ח),","\u0003ולשון הרע\u0004 מתכפרת \u0003בקטרת, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 שאמר \u0003ר' חנינא: למדנו לקטרת שמכפרת, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויתן את הקטרת ויכפר על העם\"\u0004 (במדבר יז, יב), \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: על מה קטרת מכפרת\u0004 — \u0003על לשון הרע,\u0004 ומדוע? \u0003אמר הקדוש ברוך הוא: יבא דבר שבחשאי,\u0004 כלומר, הקטורת שהקטרתה נעשית בתוך ההיכל, ואין קול נשמע בעבודתה, \u0003ויכפר על מעשה חשאי,\u0004 כלומר, על לשון הרע, הנאמרת בסתר, מאחורי גבו של האדם.","ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003שפיכות דמים\u0004 על ענין \u0003שפיכות דמים,\u0004 שלדברי ר' יהושע בן לוי עגלה ערופה מכפרת עליה, ואילו לעיל נאמר שכתונת מכפרת, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003לשון הרע\u0004 על ענין \u0003לשון הרע,\u0004 שלפי תנא דבי ר' ישמעאל קטורת מכפרת עליה, ואילו לעיל נאמר שהמעיל מכפר עליה!","ומשיבים: מענין \u0003שפיכות דמים\u0004 על ענין \u0003שפיכות דמים לא קשיא\u0004 \u0005[לא קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שהכתונת מכפרת — \u0003דידיע מאן קטליה\u0004 \u0005[שידוע מי הרג אותו],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שעגלה ערופה מכפרת — \u0003דלא ידיע מאן קטליה\u0004 \u0005[כ\u0006\u0005שלא ידוע מי הרג אותו].\u0006","ושואלים: \u0003דידיע מאן קטליה בר קטלא\u0004 \u0005[\u0006כ\u0005שידוע מי הרג אותו\u0006 הרי \u0005בן מות]\u0006 \u0003הוא,\u0004 והריגת הרוצח היא הכפרה, ומדוע נאמר שהכתונת מכפרת? ומשיבים: מדובר פה שהרג אדם \u0003במזיד ולא אתרו ביה\u0004 \u0005[ולא התרו בו],\u0006 כך שאי אפשר לדון אותו למיתה.","וכן מענין \u0003לשון הרע\u0004 על ענין \u0003לשון הרע לא קשיא\u0004 \u0005[לא קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — כשדיבר לשון הרע \u0003בצינעא,\u0004 ואז הקטורת הנעשית בצינעא מכפרת,"],["\u0003הא\u0004 \u0005[זה]\u0006 — שדיבר \u0003בפרהסיא,\u0004 ואז מכפר עליו המעיל, שפעמוניו מצלצלים.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' שמואל בר נדב מר' חנינא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' שמואל בר נדב חתניה\u0004 \u0005[חתנו]\u0006 של \u0003ר' חנינא\u0004 שאל זאת \u0003מר' חנינא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ששאל זאת \u0003מר' יהושע בן לוי: מה נשתנה מצורע\u0004 משאר הטמאים, \u0003שאמרה תורה\u0004 בדינו: \u0003\"בדד ישב מחוץ למחנה מושבו\"\u0004 (ויקרא יג, מו)? והשיב לו: \u0003הוא הבדיל\u0004 בלשון הרע שלו \u0003בין איש לאשתו, בין איש לרעהו, לפיכך\u0004 בא עליו נגע הצרעת, ו\u0003אמרה תורה: \"בדד ישב\" וגו'.\u0004","\u0003אמר ר' יהודה בן לוי: מה נשתנה מצורע\u0004 משאר הטמאים, \u0003שאמרה תורה\u0004 בדינו ש\u0003יביא שתי ציפרים לטהרתו? אמר הקדוש ברוך הוא: הוא עושה מעשה פטיט\u0004 (פטפוט), שדיבר לשון הרע, \u0003לפיכך אמרה תורה: יביא\u0004 לטהרתו \u0003קרבן פטיט,\u0004 כלומר, ציפור, שכל הזמן מפטפטת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר בתורה: \u0003\"לא תשנא את אחיך בלבבך\"\u0004 (ויקרא יט, יז), ומדוע נאמר \"בלבבך\"? שאם היה כתוב רק \"לא תשנא את אחיך\", \u0003יכול\u0004 אתה לומר שכוונת המקרא היא ש\u0003לא יכנו,\u0004 ו\u0003לא יסטרנו, ולא יקל(ק)לנו—\u0004 מתוך שנאתו — \u0003תלמוד לומר: \"בלבבך\",\u0004 לומר שב\u0003שנאה שבלב הכתוב מדבר.\u0004","\u0003מנין לרואה בחבירו דבר מגונה שחייב\u0004 הרואה \u0003להוכיחו? שנאמר:\u0004 \"לא תשנא את אחיך בלבבך \u0003הוכח תוכיח\u0004 את עמיתך ולא תשא עליו חטא\" (שם), \u0003הוכיחו\u0004 על מה שעשה \u0003ולא קבל, מנין שיחזור ויוכיחנו? תלמוד לומר: \"תוכיח\", מכל מקום. יכול אפילו משתנים פניו,\u0004 כלומר, שמתבייש מאד מחמת התוכחה? \u0003תלמוד לומר\u0004 שם: \"ו \u0003לא תשא עליו חטא\",\u0004 כלומר, שלא יחטא המוכיח עצמו כשמוכיח את חבירו.","ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' טרפון: תמיהני אם יש בדור הזה\u0004 מי \u0003שמקבל תוכחה,\u0004 מדוע? \u0003אם אמר לו\u0004 המוכיח לחבירו: \u0003\"טול קיסם מבין עיניך\"\u0004 כלומר, חזור בך מחטא קטן שנמצא אצלך, \u0003אמר לו\u0004 החבר: \u0003\"טול\u0004 אתה \u0003קורה מבין עיניך\",\u0004 כלומר, תקן את עצמך, שאתה חוטא גדול יותר ממני. \u0003אמר ר' אלעזר בן עזריה: תמיהני אם יש בדור הזה\u0004 מי \u0003שיודע להוכיח\u0004 כראוי, בלא הלבנת פנים, ודבריו מתקבלים.","\u0003ואמר ר' יוחנן בן נורי: מעיד אני עלי שמים וארץ שהרבה פעמים לקה\u0004 (נענש) ר' \u0003עקיבא על ידי,\u0004 מדוע? \u0003שהייתי קובל\u0004 (מתלונן) \u0003עליו לפני רבן שמעון ברבי\u0004 (הגדול), רבן שמעון בן גמליאל, \u0003וכל שכן שהוספתי בו אהבה\u0004 כלפי, \u0003לקיים מה שנאמר: \"אל תוכח לץ פן ישנאך הוכח לחכם ויאהבך\"\u0004 (משלי ט, ח), שהחכם רוצה לתקן עצמו ואוהב כל מי שמסייע לו בכך.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון\u0004 את אביו: \u0003תוכחה\u0004 \u0003לשמה,\u0004 שנעשית לשם שמים, \u0003וענוה שלא לשמה, הי מינייהו עדיפא\u0004 \u0005[איזו מהם עדיפה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו: \u0003ולא מודית\u0004 \u0005[ואין אתה מודה]\u0006 ש\u0003ענוה לשמה עדיפא, דאמר מר—\u0004 \u0005[שאמר החכם]:\u0006 \u0003ענוה גדולה מ\u0004כל המידות הטובות \u0003כולם?\u0004 אם כן, גם כאשר אדם נוהג בענוה \u0003שלא לשמה נמי\u0004 \u0005[גם כן]\u0006 \u0003עדיפא,\u0004 ש\u0003אמר רב יהודה אמר רב: לעולם יעסוק אדם בתורה ובמצות אף על פי שלא לשמה, שמתוך שלא לשמה בא לשמה,\u0004 וכן לענין הענוה.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 \u0003תוכחה לשמה וענוה שלא לשמה?\u0004 ומביאים דוגמא לדבר: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב הונא וחייא בר רב הוו יתבי קמיה\u0004 \u0005[היו יושבים לפני]\u0006 \u0003שמואל, אמר ליה\u0004 \u0005[לו]\u0006 \u0003חייא בר רב\u0004 לשמואל: \u0003חזי מר, דקא מצער לי\u0004 \u0005[יראה אדוני, שמצער אותי\u0006 רב הונא\u0005]!\u0006 \u0003קביל עליה\u0004 \u0005[קיבל עליו]\u0006 רב הונא \u0003דתו לא מצער ליה\u0004 \u0005[שיותר לא יצער אותו].\u0006 \u0003בתר דנפיק\u0004 \u0005[אחרי שיצא]\u0006 חייא בר רב, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לשמואל: \u0003הכי והכי קא עביד\u0004 \u0005[כך וכך הוא עושה],\u0006 ומשום כך בדין ציערתיו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003אמאי לא אמרת ליה באנפיה\u0004 \u0005[מדוע לא אמרת לו\u0006 דבר זה \u0005בפניו],\u0006 כשישבתם שניכם לפני? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לשמואל: \u0003חס לי דליכסוף זרעיה דרב על ידאי\u0004 \u0005[אוי לי שיתבייש זרעו של רב על ידי]!\u0006 הרי תוכחה לשמה — שהוכיח רב הונא את חייא בר רב שלא בפני שמואל, וענוה שלא לשמה — כשנמנע מלהוכיחו בפני שמואל רק כדי שלא לביישו.","ומבררים: \u0003עד היכן תוכחה,\u0004 כלומר, עד היכן צריך המוכיח לחזור ולהוכיח? \u0003רב אמר: עד הכאה,\u0004 כלומר, עד שיכה המוכח את מי שמוכיחו, \u0003ושמואל אמר: עד קללה,\u0004 כלומר, עד שיקלל את המוכיח, \u0003ור' יוחנן אמר: עד נזיפה,\u0004 כלומר, עד שינזוף במוכיח. ואומרים: מחלוקתם היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו כבר בדבר, \u0003ר' אליעזר אומר: עד הכאה, ר' יהושע אומר: עד קללה, בן עזאי אומר: עד נזיפה.\u0004","\u0003אמר רב נחמן בר יצחק, ושלשתן מקרא אחד דרשו,\u0004 כשהוכיח יהונתן את שאול על יחסו לדוד: \u0003\"ויחר אף שאול ביהונתן ויאמר לו בן נעות המרדות—\u0004 הלוא ידעתי כי בוחר אתה לבן ישי לבושתך ולבושת ערות אמך\" (שמואל א כ, ל), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהמשך: \u0003\"ויטל שאול את החנית עליו להכותו\"\u0004 (שם לג).","\u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003עד הכאה\u0004 הראיה היא ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"להכותו\",\u0004 ומשם ואילך חדל יהונתן להוכיח, \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003עד קללה\u0004 — ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לבשתך ולבשת ערות אמך\"\u0004 (שם), \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003עד נזיפה\u0004 — ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויחר אף שאול\"\u0004 (שם).","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שרק עד \u0003נזיפה\u0004 צריך להוכיחו, \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 שם גם \u0003הכאה וקללה!\u0004 ואומרים: אין ללמוד משם, כי \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דאגב חביבותא יתירא דהוה ביה\u0004 \u0005[שמתוך חיבה יתירה שהיתה בו]\u0006 \u0003ליהונתן בדוד, מסר נפשיה טפי\u0004 \u0005[מסר את נפשו יותר\u0006 ממה שהיה מחוייב\u0005],\u0006 אבל סתם אדם אינו מחוייב להגיע לכך מצד מצות התוכחה.","\u0003עד היכן\u0004 יסבול אדם ו\u0003לא ישנה אדם באכסניא שלו,\u0004 לעבור למארח אחר? \u0003רב אמר: עד הכאה,\u0004 כלומר, שאם היכו המארחים את האורחים אזי יעברו למארחים אחרים, \u0003ושמואל אמר: עד שיפשלו לו כליו לאחוריו,\u0004 כלומר שהמארחים ארזו את כלי האורחים ושמו על צוואריהם וגרשום.","ואומרים: \u0003בהכאה דידיה\u0004 \u0005[שלו],\u0006 שהיכו את האורח עצמו — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שישנה באכסניא, וכן \u0003בהפשלת כליו לאחוריו\u0004 — \u0003כולי עלמא נמי לא פליגי\u0004 \u0005[הכל גם כן אינם חולקים]\u0006 שישנה, \u0003כי פליגי\u0004 \u0005[כאשר חלוקים הם]\u0006 הרי זה \u0003בהכאה דדביתהו\u0004 \u0005[של אשתו],\u0006 כלומר שהמארחים היכו את אשתו של האורח, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 שמואל, \u0005סבור]:\u0006 \u0003כיון דלדידיה לא מצער ליה מאי נפקא ליה מינה\u0004 \u0005[כיון שאותו עצמו אין מצערים מה יוצא לו מזה],\u0006 ולכן לא ישנה מאכסניא זו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב, \u0005סבור]:\u0006 לא ישתהה שם, שמא \u0003אתי לאיטרודי\u0004 \u0005[יבואו להתקוטט]\u0006 בגלל דבר זה.","ואומרים: \u0003וכל כך למה\u0004 לא ישנה מאכסניא? \u0003דאמר מר\u0004 \u0005[\u0006מפני \u0005שאמר החכם]:\u0006 \u0003אכסנאי\u0004 העוזב את מארחו \u0003פוגם ונפגם,\u0004 מפני שאומרים האנשים: כמה קשים מארח זה ואורח זה שלא יכלו לסבול זה את זה.","\u0003אמר רב יהודה אמר רב: מנין\u0004 למדים \u0003שלא ישנה אדם באכסניא שלו מן התורה? שנאמר\u0004 בחזרת אברהם ממצרים לארץ: \"וילך למסעיו מנגב ועד בית אל \u0003אל— המקום אשר היה שם אהלו בתחלה\"\u0004 (בראשית יג, ג).","\u0003ר' יוסי בר' חנינא אמר, מהכא\u0004 \u0005[מכאן]\u0006 מתחילת המקרא למדים זאת, שנאמר שם: \u0003\"וילך למסעיו\",\u0004 כלומר, באותם מקומות שבהם נסע לפני כן. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ביניהם]\u0006 שנחלקו מהיכן נלמד ענין זה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי \u0003אכסנאי\u0004 של \u0003אקראי—,\u0004 שלדעת ר' יוסי בר' חנינא שהזכיר \"מסעיו\", גם אורח אקראי צריך לחזור למארחו הקודם.","ועוד בענין דומה, \u0003אמר ר' יוחנן: מנין שלא ישנה אדם מאומנותו ומאומנות אבותיו? שנאמר: \"וישלח המלך שלמה ויקח את חירם מצר, בן אשה אלמנה הוא ממטה נפתלי ואביו איש צרי חרש נחושת\"\u0004 (מלכים א ז, יג—יד),","\u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003אימיה\u0004 \u0005[אימו]\u0006 של חירם היתה \u0003מבית דן,\u0004 שהרי נאמר לגביו \"בן אשה מן בנות דן (דברי הימים ב ב, יג), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בעושי המלאכה במשכן: \u0003\"ואתו אהליאב בן אחיסמך למטה דן\u0004 חרש\" (שמות לח, כג), משמע שחירם החזיק במקצוע חרשות הנחושת גם ממשפחת אביו משבט נפתלי וגם ממשפחת אמו משבט דן.","ושואלים: \u0003עד היכן תכלית\u0004 (קצה) \u0003יסורין?\u0004 כלומר, מה עדיין נכלל בגדר יסורים? \u0003אמר ר' אלעזר: כל שארגו לו בגד ללבוש ואין\u0004 הבגד \u0003מתקבל עליו,\u0004 כלומר, שאינו מתאים לו בדיוק. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא זעירא\u0004 \u0005[הקטן],\u0006 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003ר' שמואל בר נחמני,\u0004 הלוא \u0003גדולה מזו אמרו: אפילו נתכוונו למזוג\u0004 לו כוס יין \u0003ב\u0004מים \u0003חמין ומזגו לו\u0004 בטעות \u0003בצונן,\u0004 או שנתכוונו למזוג לו \u0003בצונן ומזגו לו בחמין\u0004 הרי זה נקרא יסורים, \u0003ואת אמרת כולי האי\u0004 \u0005[ואתה אומר כל זה],\u0006 שבגד שארגו לו אינו מתקבל עליו?","\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא אמר: אפילו נהפך לו חלוקו\u0004 כשלבשו, והוא צריך לחזור להופכו, הרי אלו יסורים. \u0003רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב חסדא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יצחק, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים שבברייתא שנה\u0006 זאת\u0005]:\u0006 עד היכן תכלית יסורין? \u0003אפילו הושיט ידו לכיס ליטול שלש\u0004 מטבעות \u0003ועלו בידו שתים\u0004 — הרי אלו יסורים.","ומוסיפים: ו\u0003דווקא\u0004 אם הושיט ידו לכיס ליטול \u0003שלש ועלו בידו שתים\u0004 אלו יסורים, שצריך להחזיר ידו לכיסו ולהוציא מטבע נוסף. \u0003אבל\u0004 אם הושיט ידו לכיס ליטול \u0003שתים ועלו בידו שלש\u0004 — \u0003לא,\u0004 שאין זה נקרא יסורים, \u0003דליכא טירחא למישדייהו\u0004 \u0005[\u0006מפני \u0005שאין\u0006 זו \u0005טירחה לזרוק\u0006 את המטבע היתרה\u0005].\u0006","ושואלים: \u0003וכל כך למה?\u0004 לשם מה צריך לדון מה עדיין נכלל בגדר יסורים? ומשיבים, \u0003דתניא דבי\u0004 \u0005[ששנויה\u0006 ברייתא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל שעברו עליו ארבעים יום בלא יסורין קיבל עולמו,\u0004 כלומר, זכה לקבל את שכרו כבר בעולם הזה. \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל אומרים]:\u0006 מי שעברו עליו ארבעים יום בלא יסורים"],["\u0003פורענות מזדמנת לו,\u0004 ואם יבואו עליו אפילו יסורים מועטים, ניצל מפורענות. ושבים לענין תוכחה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: אלמלא\u0004 (אילו) היה \u0003בא הקדוש ברוך הוא עם אברהם יצחק ויעקב בדין, אין יכולין לעמוד מפני תוכחה, שנאמר: \"ועתה התיצבו ואשפטה אתכם לפני ה' את כל צדקות ה' אשר עשה אתכם ואת אבותיכם\"\u0004 (שמואל א יב, ז), משמע שגם עם האבות עשה ה' צדקה, ולא כפי מה שראוי להם בדין. נאמר: \u0003\"זה דור דרשיו מבקשי פניך יעקב סלה\"\u0004 (תהלים כד, ו), ומפסוק זה עולה כי הדור ומנהיגיו (\"דורשיו\") אחד הם, ובמשמעות דבר זה \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003ורבנן\u0004 \u0005[וחכמים\u0006 שבדורו\u0005],\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מצבו של ה\u0003דור\u0004 הוא \u0003לפי פרנס\u0004 (מנהיג) הדור, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 להיפך: \u0003פרנס לפי דורו.\u0004","","ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה],\u0006 לאיזה ענין נאמר הדבר? \u0003אילימא למעליותא\u0004 \u0005[אם תאמר לטובה],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם\u0006 זה \u0005סבור]:\u0006 \u0003אי מעלי דרא מעלי פרנס\u0004 \u0005[אם מעולה הדור מעולה\u0006 גם \u0005הפרנס],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה \u0005סבור]:\u0006 \u0003אי מעלי פרנס מעלי דרא\u0004 \u0005[אם מעולה הפרנס מעולה\u0006 גם \u0005הדור]\u0006 — לא ניתן לומר זאת, \u0003הא איכא\u0004 \u0005[\u0006\u0005הרי יש]\u0006 את \u0003צדקיה\u0004 מלך יהודה, \u0003דהוה מעלי ודריה לא הוה מעלי\u0004 \u0005[שהיה מעולה ודורו לא היה מעולה],\u0006 \u0003והא\u0004 \u0005[ו\u0006מצד אחר, \u0005הרי]\u0006 \u0003יהויקים, דלא הוה מעלי ודריה הוה מעלי\u0004 \u0005[שלא היה מעולה ודורו היה מעולה]!\u0006 שכך \u0003אמר ר' יוחנן משום ר' שמעון בן יוחי, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"בראשית ממלכות יהויקים\u0004 בן יאשיהו \u0003מלך יהודה\"\u0004 (ירמיהו כו, א), וכיוצא בזה מה שנאמר: \"בראשית ממלכת צדקיה מלך יהודה\" (שם כח, א)? כלומר, מדוע הוזכרה אצל אותם מלכים המילה \"בראשית\", שלא נזכרה במקום אחר במקרא חוץ מבבריאת העולם?","","\u0003ביקש הקדוש ברוך הוא להחזיר את העולם לתוהו ובהו\u0004 כמו בראשית בריאת העולם (בראשית א, א—ב) \u0003בשביל\u0004 (בגלל) \u0003יהויקים,\u0004 שעשה הרע בעיני ה', \u0003כיון שנסתכל בדורו,\u0004 שהיה הדור צדיק, \u0003נתיישבה דעתו.\u0004 ומצד אחר, \u0003ביקש הקדוש ברוך הוא להחזיר את העולם לתוהו ובהו מפני דורו של צדקיהו, כיון שנסתכל בצדקיהו,\u0004 שהיה צדיק, \u0003נתיישבה דעתו,\u0004 ונמצא שהדור אינו בהכרח כמו הפרנס, וכן הפרנס אינו בהכרח כמו הדור!","\u0003אלא לענין תוקפא וניחותא קאמרינן\u0004 \u0005[תקיפות ונוחות אנו אומרים],\u0006 שלדעה אחת אם הפרנס תקיף — גם הדור תקיף, ואם הפרנס נוח לבריות בהתנהגותו — גם דורו כן, נוחים זה לזה, ולדעה השניה אם הדור תקיף גם הפרנס תקיף, ואם האנשים נוחים זה לזה — גם הפרנס נח לבריות.","","\u0003השג יד\u0004 שנאמר בתורה בדיני ערכין, שאם אין ידו משגת נותן כפי שיעריכנו הכהן (ויקרא כז, ח) — נאמר \u0003בנודר, והשנים,\u0004 הערך הקצוב בתורה לפי מספר השנים — מדבר \u0003ב\u0004שנותיו של ה\u0003נידר\u0004 (הנערך), \u0003ו\u0004השינוי בערך בין זכר לנקבה שנאמר בדיני \u0003הערכין\u0004 נידון \u0003בנערך, והערך\u0004 השונה לפי גיל הנערך, נקבע \u0003בזמן\u0004 שנדר את \u0003הערך.\u0004 ומפרטים: \u0003השג יד בנודר, כיצד? עני שהעריך את העשיר\u0004 — \u0003נותן ערך עני,\u0004 לפי מה שהכהן מעריך שידו משגת, ויוצא בכך ידי חובתו, \u0003ו\u0004אלו \u0003עשיר שהעריך את העני\u0004 — \u0003נותן ערך עשיר,\u0004 את מלוא הסכום הקצוב לו בתורה.","","\u0003אבל בקרבנות אינו כן,\u0004 כיצד? \u0003הרי שאמר: \"קרבנו של מצורע זה עלי\",\u0004 שנדר לספק למצורע את הקרבנות שהוא זקוק להם לטהרתו, אם \u0003היה\u0004 ה\u0003מצורע עני\u0004 — הרי הנודר \u0003מביא קרבן עני,\u0004 כבש אחד ועשרון סלת, ושני תורים או שני בני יונה (שם יד, כא—כב), ואם היה המצורע \u0003עשיר\u0004 — \u0003מביא\u0004 הנודר \u0003קרבן עשיר,\u0004 שני כבשים, כבשה ושלשה עשרונים סולת (שם י).","\u0003רבי אומר, אומר אני:\u0004 אין זה הבדל מהותי, אלא \u0003אף בערכין כן, וכי מפני מה עני שהעריך את העשיר נותן ערך עני\u0004 ולא ערך עשיר — מפני \u0003שאין העשיר\u0004 עצמו \u0003חייב כלום,\u0004 והחוב נוצר רק על ידי העני שנדר לתת את ערכו של העשיר. \u0003אבל\u0004 במקרה הדומה לחיוב בקרבנות מצורע, וכגון \u0003עשיר שאמר\u0004 מתחילה: \u0003\"ערכי עלי\", ושמע עני ואמר: \"מה שאמר זה עלי\u0004 לשלם\" — הרי שהעני \u0003נותן ערך עשיר.\u0004","שנינו במשנה: השג יד בנודר. ושואלים: והרי דין \u0003השג יד במעריך הוא\u0004 שנאמר בתורה, במי שמקבל על עצמו לתת להקדש את ערכו הקצוב בתורה של פלוני (לפי גילו ומינו), ולא בדיני נודר, שהוא האומר: \"דמיו של פלוני עלי\", וצריך לתת כפי דמיו כאילו היה נמכר כעבד בשוק! ומשיבים: המשנה משתמשת בלשון התורה בדין ערכין, \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \"על פי \u0003אשר תשיג יד הנודר יעריכנו הכהן\"\u0004 (ויקרא כז, ח).","ועל מה ששנינו במשנה: ו\u0003השנים בנידר,\u0004 שואלים: והרי השנים \u0003בנערך הוא\u0004 שנאמרו, שהסכום קצוב לפי גילו של הנערך, אבל הנידר הרי נדון לפי ערכו בשוק! ומשיבים: \u0003איידי דאמר\u0004 \u0005[מתוך שאמר]\u0006 מתחילה \u0003\"השג יד בנודר\",\u0004 למרות שמדובר בנערך — \u0003אמר נמי\u0004 \u0005[גם כן]\u0006 לשון \"ו \u0003השנים בנידר\".\u0004 שנינו במשנה: \u0003השג יד בנודר, כיצד? עני שהעריך את העשיר נותן ערך עני.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומשיבים: \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \"על פי \u0003אשר תשיג יד הנדר\"\u0004 — \u0003בנודר תלה רחמנא\u0004 \u0005[תלתה התורה]\u0006 את הדבר.","","שנינו במשנה: \u0003אבל בקרבנות אינו כן, הרי שאמר: \"קרבנו של מצורע זה עלי\", היה מצורע עני\u0004 — \u0003מביא\u0004 הנודר \u0003קרבן עני.\u0004 ותמהים: \u0003ואף על גב דמדירו\u0004 \u0005[ואף על פי שהאיש שנודר עבורו\u0006 את הקרבנות\u0005]\u0006 היה \u0003עשיר?\u0004 והרי \u0003\"ואם דל הוא\u0004 ואין ידו משגת ולקח כבש\" וכו' (ויקרא יד, כא) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 בדין קרבן המצורע, \u0003ולא דל הוא\u0004 זה שלוקח (מביא) את הקרבנות! \u0003אמר ר' יצחק:\u0004 משנתנו מדברת \u0003כשהיה\u0004 גם \u0003מדירו\u0004 של המצורע \u0003עני.\u0004 ושואלים: ומניין למשנה דין זה? \u0003ודלמא עליה דידיה חס רחמנא\u0004 \u0005[ושמא עליו עצמו,\u0006 על המצורע, \u0005חסה התורה]\u0006 שיביא קרבן פשוט יותר, אבל על \u0003מדירו לא\u0004 חסה התורה, ואפילו הוא עני, \u0003דהכתיב\u0004 \u0005[שהרי נאמר]:\u0006 \"ואם דל \u0003הוא\",\u0004 הוא ולא אחר!","","\u0003אמר רב אדא בר אהבה:\u0004 מה שנאמר מיד בהמשך: \u0003\"ואין ידו משגת\"\u0004 — הרי זה בא \u0003לרבות\u0004 גם \u0003את הנודר\u0004 לספק את קרבנות חבירו, שאם גם הוא עני הריהו מביא קרבן עני.","ומקשים: לפי דבריך, \u0003אבל\u0004 אם \u0003מדירו\u0004 של המצורע העני היה \u0003עשיר, הכי נמי דמייתי\u0004 \u0005[כך גם כן\u0006 סבורה המשנה \u0005שמביא]\u0006 \u0003בעשירות?\u0004 \u0003אם כן, מאי\u0004 \u0005[מהו]\u0006 ששנינו במשנה שדווקא בערכין הולכים אחר השג ידו של הנודר, \u0003אבל בקרבנות אינו כן?\u0004 והלא גם בקרבנות, אם הנודר עני — מביא קרבן עני, ואם הוא עשיר — מביא קרבן עשיר!",""],["ומשיבים, שני אופנים של נודר קרבנות למצורע נאמרו במשנתנו: \u0003חדא\u0004 \u0005[האחד]\u0006 \u0003מצורע עני ומדירו עני,\u0004 שהוא מביא קרבן עני, בדומה לערכין, \u0003וחדא\u0004 \u0005[ו\u0006האופן ה\u0005אחד],\u0006 עליו נאמר \"אבל בקרבנות אינו כן\", ובא התנא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מצורע עשיר ומדירו עני,\u0004 שמביא הנודר העני קרבנות של מצורע עשיר.","ואף שפשוט הדבר לכאורה, שכן קיבל עליו העני לספק את הקרבנות שהעשיר נתחייב בהם, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואיתרבו\u0004 \u0005[והתרבו]\u0006 מן הכתוב עני שקיבל על עצמו לספק קרבן מצורע עני, ללמד שמביא קרבן עני, אם כן יש לומר כי \u0003איתרבו\u0004 \u0005[התרבו]\u0006 בכל אופן, וגם במקרה שקיבל על עצמו לספק קרבן מצורע עשיר יביא קרבן עני, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא שאין אומרים כן.","וכן שנינו בברייתא: \u0003לפי שמצינו בערכין, עני שהעריך את העשיר נותן ערך עני, יכול אף זה כן,\u0004 כלומר, אף עני שנדר לספק קרבנותיו של מצורע עשיר, יספק קרבנות עני? \u0003תלמוד לומר\u0004 לגבי קרבנות מצורע: \"ו \u0003אם דל הוא\"\u0004 (שם יד, כא) להדגיש: דווקא אם המצורע עני הדין כן, אבל אם המצורע עשיר — צריך הנודר להביא קרבנות עשיר.","ושואלים, \u0003ול\u0004דעת \u0003רבי\u0004 ש\u0003אמר\u0004 במשנתנו: \u0003אומר אני אף בערכין כן,\u0004 שעשיר שאמר: \"ערכי עלי\", ושמע העני ואמר: \"מה שאמר זה עלי\" — נותן ערך עשיר, \u0003אלמא אמר\u0004 \u0005[מכאן\u0006 שרבי \u0005אומר]:\u0006 \u0003בתר חיובא דגברא אזלינן\u0004 \u0005[אחר חיובו\u0006 המקורי \u0005של האיש\u0006 שנודרים עבורו \u0005אנו הולכים]\u0006 גם בערכין, \u0003והא לא צריכא קרא למעוטי\u0004 \u0005[ו\u0006לפי זה, \u0005הרי לא צריך מקרא למעט]\u0006 שגם עני שנדר לספק קרבנותיו של מצורע עשיר יביא בעשירות, אם כן מה שנאמר: \"ואם דל \u0003הוא\" למעוטי מאי\u0004 \u0005[למעט את מה]\u0006 הוא בא?","ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מצורע עני ומדירו עשיר,\u0004 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל ואמר רבי: בתר חיובא דגברא אזלינן\u0004 \u0005[אחר חיובו\u0006 \u0005של האיש\u0006 שנודרים עבורו \u0005אנו הולכים],\u0006 ומכיוון שהמצורע הוא עני יביא מדירו קרבן עני, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 המיעוט שיתן מדירו קרבנות עשיר.","\u0003היה עני\u0004 כשנדר נדר ערכין, \u0003והעשיר\u0004 אחר כך, או \u0003עשיר\u0004 כשהעריך, \u0003והעני\u0004 אחר כך — \u0003נותן ערך עשיר,\u0004 כלומר, את מלוא הערך. \u0003ר' יהודה אומר:\u0004 לא רק כשהיה עשיר בשעת הנדר או בשעת הנתינה, אלא אפילו היה \u0003עני\u0004 כשנדר \u0003והעשיר וחזר והעני\u0004 — גם הוא \u0003נותן ערך עשיר.\u0004","\u0003אבל בקרבנות\u0004 של מצורע, שיש בהם הבדל בין עני לעשיר, \u0003אינו כן,\u0004 שאם היה המצורע עני והעשיר, או להיפך, בכל מקרה הוא נידון אחר שעת הבאת הקרבנות. \u0003אפילו\u0004 ידוע ש\u0003מת אביו והניח לו ריבוא\u0004 (עשרת אלפים דינר), \u0003או\u0004 שידוע ש\u0003ספינתו בים ובאה לו\u0004 בתוכה סחורה \u0003ברבואות\u0004 — \u0003אין להקדש בה כלום,\u0004 ונידון לפי מה שבידו כעת.","ומביאים מקור לדין המשנה. מה ששנינו: נדר כשהוא \u0003עני והעשיר\u0004 נותן ערך עשיר, נלמד ממה שנאמר: \u0003\"אשר תשיג יד הנדר\u0004 יעריכנו הכהן\" (ויקרא כז, ח), ומכיוון שכעת ידו משגת יתן כעשיר. ומה ששנינו: נדר כשהוא \u0003עשיר והעני\u0004 נותן ערך עשיר — ממה שנאמר בתחילת הפסוק שם: \"והעריך אותו הכהן \u0003על פי אשר תשיג\",\u0004 ו\"על פי\" מלמד שנידון לפי השעה שהוציא בפיו את הנדר.","ועוד שנינו, \u0003ר' יהודה אומר: אפילו\u0004 נדר כשהוא \u0003עני והעשיר וחזר והעני\u0004 — נותן ערך עשיר. ומבארים, \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה? אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואם מך הוא מערכך\"\u0004 (שם), והמילה \"הוא\" מלמדת: \u0003עד שיהא במכותו\u0004 (בעניותו) \u0003מתחלתו ועד סופו.\u0004","ושואלים: \u0003אלא מעתה,\u0004 מה שנאמר בקרבנות מצורע \u0003\"ואם דל הוא\"\u0004 (ויקרא יד, כא), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 נפרש לשיטת ר' יהודה: \u0003עד שיהא בדלותו מתחלתו ועד סופו,\u0004 משעה שנתחייב בקרבנותיו ועד שמביאם, אבל אם היה עשיר, למרות שהוא עכשיו עני — לא יביא קרבנות עני!","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר, כך הוא גם כן]\u0006 — \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מצורע שהביא קרבנותיו,\u0004 היה \u0003עני והעשיר,\u0004 או \u0003עשיר והעני\u0004 — \u0003הכל הולך אחר חטאת,\u0004 כלומר, לפי מצבו בזמן הבאת קרבן חטאת. שאם הביא חטאתו מן הבהמה — יביא גם עולתו מן הבהמה, למרות שהעני בינתיים. ואם הביא חטאתו מן העוף, כעני — יביא גם עולתו מן העוף, למרות שהעשיר בינתיים, אלו \u0003דברי ר' שמעון.\u0004","\u0003ר' יהודה אומר: הכל הולך אחר\u0004 מצבו בזמן הבאת ה\u0003אשם,\u0004 ואם היה עני באותה שעה יביא חטאת ועולה מן העוף, למרות שנעשה עשיר. \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: הכל הולך אחר\u0004 מצבו בזמן הבאת ה\u0003צפרים\u0004 לטהרתו, שבעה ימים קודם לכן. ומבואר שכל התנאים, ובכללם רבי יהודה, אינם מצריכים שיהא עני מתחילה ועד סוף!","ומשיבים: \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]:\u0006 \u0003אמר רב יהודה אמר רב, ושלשתן מקרא אחד דרשו,\u0004 כלומר גזירת הכתוב היא, שנאמר לגבי מצורע עני: \"זאת תורת אשר בו נגע צרעת \u0003אשר לא תשיג ידו בטהרתו\"\u0004 (שם יד, לב), \u0003ר' שמעון סבר\u0004 \u0005[סבור]:\u0006 דינו של מי שלא השיגה ידו תלוי ב\u0003דבר המכפר\u0004 ומטהר מן החטא, \u0003מאי ניהו\u0004 \u0005[מה הוא]\u0006 — \u0003חטאת,\u0004 ולכן שעת הבאת חטאת קובעת.","\u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 ממה שנאמר \"אשר לא תשיג ידו בטהרתו\" יש ללמוד כי עיקר דינו נקבע ב\u0003דבר ה\u0004מטהר ו\u0003מכשיר\u0004 אותו להיכנס למקדש ולאכול מן הקדשים, \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003אשם,\u0004 שלאחר שהוזה עליו מדם האשם הוכשר לכך. ואילו \u0003ר' אליעזר בן יעקב סבר\u0004 \u0005[סבור]\u0006 שהכוונה היא לדבר \u0003הגורם לו טהרה, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003ציפרים,\u0004 שלאחר שנטהר על ידן באופן חלקי הריהו ראוי להביא קרבנותיו למקדש ולהשלים טהרתו.","ושואלים: \u0003ואלא\u0004 המיעוט \"ואם דל \u0003הוא\",\u0004 אם אין למדים ממנו שצריך שיהא דל מתחילתו ועד סופו, \u0003למה לי?\u0004 ומשיבים: \u0003לרבי כדאית ליה\u0004 \u0005[כמו שיש לו,\u0006 לשיטתו\u0005]\u0006 בתחילת עמוד זה — למעט מצורע עני ומדירו עשיר, ללמד שיביא קרבן עשיר, \u0003ולרבנן כדאית להו\u0004 \u0005[כמו שיש להם],\u0006 למעט מצורע עשיר ומדירו עני, שמביא קרבן עשיר.","וחוזרים ושואלים: \u0003אלא מעתה,\u0004 שר' יהודה למד מ\"ואם מך הוא\" שיהא במכותו מתחילה ועד סוף, מה שנאמר בדיני עדות: \u0003\"והוא עד\u0004 או ראה או ידע אם לא יגיד ונשא עוונו\" (ויקרא ה, א), גם שם יש לדרוש כן: \u0003עד שיהא\u0004 העד \u0003כשר מתחלתו ועד סופו,\u0004 ואם אינו כזה עדותו פסולה!","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך הוא גם כן]\u0006 — \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היה\u0004 העד \u0003יודע לו בעדות עד שלא נעשה חתנו, ו\u0004אחר כך \u0003נעשה חתנו,\u0004 ופסול להעיד לו, או שהיה מתחילה \u0003פקח\u0004 (שומע) \u0003ונתחרש,\u0004 או שהיה \u0003פתוח\u0004 בעיניו \u0003ונסתמא\u0004 (נהיה עיור), או היה \u0003שפוי\u0004 בדעתו \u0003ונשתטה\u0004 — \u0003הרי זה פסול\u0004 לעדות. \u0003אבל היה\u0004 העד \u0003יודע לו עדות עד שלא נעשה חתנו, ונעשה\u0004 אחר כך \u0003חתנו,\u0004"],["\u0003ואחר כך מתה בתו,\u0004 ולפיכך עתה אינם קרובים, או היה העד \u0003פקח\u0004 בשעה שראה \u0003ונתחרש וחזר ונתפקח,\u0004 או היה \u0003פתוח ונסתמא ואחר כך נתפתח,\u0004 או היה \u0003שפוי ונשתטה וחזר ונשתפה\u0004 — הרי העד \u0003כשר. זה הכלל, כל שתחילתו וסופו בכשרות\u0004 — \u0003כשר,\u0004 ומדוע אין אנו לומדים מהמילה \"הוא\" שצריך שיהיה העד כשר מתחילתו עד סופו?","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \"והוא עד \u0003או ראה... אם לא יגיד\"\u0004 (ויקרא ה, א), ללמד כי \u0003בראייה והגדה תלא רחמנא מילתא\u0004 \u0005[תלה הכתוב\u0006 את \u0005הדבר],\u0006 \u0003והא איכא\u0004 \u0005[והרי ישנו],\u0006 שבזמן הראיה ובזמן ההגדה הוא כשר. ושואלים: \u0003ואלא\u0004 המיעוט \u0003\"והוא\u0004 עד\" \u0003למה לי?\u0004","ומשיבים: \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003ראה סיאה\u0004 (סיעה, חבורה) \u0003של בני אדם עומדין ועידיו\u0004 היו \u0003ביניהן, ואמר \"משביעני עליכם אם יודעים אתם לי עדות שתבואו ותעידוני\",\u0004 ונשבעו לשקר שאינם יודעים לו עדות, \u0003יכול יהו חייבין\u0004 בקרבן שבועת העדות? \u0003תלמוד לומר: \"והוא עד\"\u0004 (שם), להדגיש שאין חייב קרבן אלא מי שנתייחד כעד, \u0003והרי לא ייחד עידיו,\u0004 שהרי השביע את כולם.","\u0003יכול אפילו אמר\u0004 לאותה חבורה: \"משביע אני \u0003כל מי\u0004 שיודע לי עדות שיבוא ויעידני\", שגם אז יהיו עדיו פטורים? \u0003תלמוד לומר: \"והוא עד\", והרי ייחד עידיו,\u0004 שהשביע רק את היודעים.","שנינו במשנה: \u0003אבל בקרבנות אינו כן,\u0004 שאם היה מצורע עני, אפילו מת אביו והניח לו ריבוא — אין להקדש בהם כלום. ושואלים: אם \u0003אביו מת והניח לו ריבוא,\u0004 אם כן \u0003עשיר הוא! אמר ר' אבהו, אימא\u0004 \u0005[אמור]:\u0006 אביו מת (עומד למות) ו\u0003מניח לו ריבוא,\u0004 אבל עדיין לא מת.","ואומרים: אם כן \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שאין להקדש כלום, שהרי בינתיים הוא עני! ומשיבים: מדובר \u0003כשהיה אביו גוסס.\u0004 והוצרך התנא לומר כן, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003רוב גוססין למיתה,\u0004 ונחשיבנו כמת וכאילו ירש כבר, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שכל עוד לא מת אביו ממש, נחשב הבן עני.","ועוד שואלים: מה ששנינו \u0003ספינתו בים ובאה לו בריבואות,\u0004 מדוע אין להקדש בהם כלום? הלוא \u0003עשיר הוא! אמר רב חסדא: כשהיתה\u0004 ספינתו \u0003מוחכרת\u0004 או \u0003ומושכרת ביד אחרים,\u0004 והסחורה שבתוכה שלהם היא, ואין לו אלא דמי החכירה או השכירות. ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 דמי \u0003שכירות\u0004 מספינה זו! ומשיבים: \u0003שכירות אינה משתלמת אלא לבסוף,\u0004 ובינתיים עני הוא.","ואומרים: \u0003ותיפוק ליה\u0004 \u0005[ושתצא לו]\u0006 שהוא עשיר \u0003משום\u0004 ה\u0003ספינה,\u0004 ששייכת לו! ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כדעת \u0005מי היא]?\u0006 כדעת \u0003ר' אליעזר היא,\u0004 הסבור כי בהגדרת עשיר לגבי החוב להקדש, אין לוקחים בחשבון את רכושו המשמש לפרנסה. \u0003דתנן\u0004 \u0005[ש\u0006כך \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 כאשר ממשכנים את נכסיו של מקדיש לטובת ההקדש, הרי \u0003אם היה איכר,\u0004 עובד אדמה — \u0003נותן לו צמדו,\u0004 צמד הבקר המשמש לחרישה, \u0003ו\u0004אם היה \u0003חמר\u0004 (מוביל סחורה בחמורו) — \u0003נותן לו חמורו.\u0004","מה ששנינו בתחילת פרק זה: \u0003השנים בנידר, כיצד? ילד\u0004 (צעיר) \u0003שהעריך זקן\u0004 — \u0003נותן ערך זקן, וזקן שהעריך את הילד\u0004 — \u0003נותן ערך ילד.\u0004 ומה ששנינו: \u0003הערכין בנערך, כיצד? איש שהעריך האשה\u0004 — \u0003נותן ערך אשה,\u0004 למרות שערכה הקצוב הוא פחות מערך איש, \u0003ואשה שהעריכה איש\u0004 — \u0003נותנת ערך איש.\u0004","ומה ששנינו: \u0003והערך בזמן הערך, כיצד?\u0004 אם \u0003העריכו\u0004 כשהיה הנערך \u0003פחות מבן חמש,\u0004 שערכו חמישה שקלים, \u0003ו\u0004לפני שנתן להקדש \u0003נעשה\u0004 הנערך \u0003יתר על בן חמש,\u0004 שערכו עשרים שקלים, או שהיה הנערך \u0003פחות מבן עשרים\u0004 בשעת הנדר, \u0003ו\u0004לפני שנתן להקדש \u0003נעשה\u0004 הנערך \u0003יתר על בן עשרים\u0004 שערכו חמישים שקלים — \u0003נותן\u0004 המעריך להקדש לפי מה שהיה שווה הנערך \u0003בזמן הערך.\u0004","ביחס למה ששנינו במשנתנו: והערך בזמן הערך, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003אתה הקשית\u0004 (היקשת, השווית) את נדרי הקדש \u0003דמים\u0004 (נדר הקדש רגיל, כגון שנודר דמיו של אדם) \u0003ל\u0004נדרי ערכין, לענין \u0003מרגלית לקלים\u0004 (לעניים), שאם נדר דמי מרגלית, שבמקום אחר נותנים עליה הרבה, ואילו במקומו, בין האנשים הקלים (הפשוטים) היא שווה מעט, מחשיבים את שווייה לפי מקומו, ולא לפי דמיה במקום אחר, כשם שנוהגים בחייבי ערכין, שהוא נידון כעני לפי שווייה במקומו, \u0003ו\u0004כן \u0003לידון בכבודו,\u0004 שהנודר דמיו של איבר שהנשמה תלויה בו, כגון ראשו, נותן דמי אותו אדם, כשם שהמעריך איבר כזה נותן ערך של אדם שלם,","\u0003יכול נקיש\u0004 מן הצד השני \u0003ערכין לדמים\u0004 לענין \u0003שיתן\u0004 את ערכו של האדם \u0003כשעת נתינה,\u0004 כפי שהוא בנדרי דמים? \u0003תלמוד לומר: \"כערכך כן יקום\"\u0004 (ראה ויקרא כז, יז), ללמדנו שהמעריך \u0003אינו נותן אלא\u0004 לפי מה שהיה שווה הנערך \u0003בזמן הערך.\u0004","בתורה נאמרו ערכים שונים למי שהוא מבן חודש עד חמש שנים, למי שהוא מבן חמש ועד עשרים, ולמבן עשרים ועד ששים. ועל כן נאמר כי תינוק כשהוא ב\u0003יום\u0004 ה\u0003שלשים\u0004 להיוולדו נחשב \u0003כלמטה הימנה,\u0004 כפחות מבן חודש, ומכיון שאין ערך בתורה לפחות מבן חודש הריהו פטור. וכן \u0003שנת\u0004 ה\u0003חמש\u0004 עצמה \u0003ושנת עשרים\u0004 דינם \u0003כלמטה מהם. שנאמר\u0004 בהמשך הפרשה: \u0003\"ואם מבן ששים שנה ומעלה\"\u0004 (ויקרא כז, ז), \u0003הרי אנו למדים בכולן משנת ששים\u0004 שנאמר בה \"ומעלה\", \u0003מה שנת ששים\u0004 עצמה היא \u0003כלמטה הימנה,\u0004 ואין משתנה ערכו אלא לאחר שנת הששים, \u0003אף שנת חמש ושנת עשרים כלמטה הימנה.\u0004","ויש להקשות: \u0003הן?\u0004 וכי יכול אתה ללמוד מכאן? וכי \u0003אם עשה שנת ששים\u0004 עצמה \u0003כלמטה ממנה להחמיר,\u0004 לשלם יותר להקדש, שהרי ערכו של מי שהוא צעיר מבן ששים גבוה יותר, \u0003נעשה שנת חמש ושנת עשרים כלמטה ממנו להקל?\u0004 שהרי ערכם של הקטנים מחמש ומעשרים פחות מערכם של הגדולים מהם!","\u0003תלמוד לומר: \"שנה\" \"שנה\"\u0004 שנאמרה בכל אחד מהם \u0003לגזירה שוה, מה שנה האמורה בשנת ששים\u0004 נחשבת \u0003כלמטה\u0004 ממנה, \u0003אף שנה האמורה משנת חמש ושנת עשרים כלמטה ממנו, בין להקל ובין להחמיר. ר' אליעזר אומר\u0004 יותר מכך: יש להמתין \u0003עד שיהו יתירות על השנים\u0004 האמורות בתורה \u0003חדש ויום אחד,\u0004 ולדוגמה, רק ילד שהוא בן חמש שנים וחודש ויום אחד (כלומר, לאחר חודש) נערך בעשרים שקלים, ופחות מכך נערך בחמישה שקלים.","ומעירים: גזירה שווה שנזכרה במשנה הריהי \u0003מופנה,\u0004 שהמילה \"שנה\" בכל אחד מן הכתובים היא מיותרת, ופנויה לגזירה שווה זו, כאילו נאמר דין זה במפורש בתורה. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא מופנה\u0004 — \u0003איכא למיפרך כדפרכינן\u0004 \u0005[יש לפרוך\u0006 אותה \u0005כפי שהקשינו\u0006 במשנה\u0005],\u0006 שאם אנו דנים את שנת חמש ושנת עשרים כלמטה מהן נמצאנו מקילים. ומשיבים: אמנם מופנה הוא, שכן \u0003\"שנה\" \"שנה\" יתירי כתיבי\u0004 \u0005[יתירים כתובים\u0006 שם\u0005].\u0006","ושואלים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003רבי\u0004 היא \u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003רבי\u0004 — לא הוצרכנו ללמוד מגזירה שווה זו, שכן \u0003האמר\u0004 \u0005[הרי אמר]\u0006 שכל מקום שנאמר \"ו \u0003עד\"\u0004 — הרי זה כולל הכל, \u0003\"ועד\" בכלל.\u0004 ואף כאן, הואיל ונאמר: \"ועד בן חמש שנים\", \"ועד בן עשרים שנה\" — גם שנת חמש ושנת עשרים בכלל זה. ומנין שכך היא שיטתו?","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \"כי כל אוכל חמץ ונכרתה הנפש ההיא מישראל \u0003מיום הראשן ועד יום השבעי\"\u0004 (שמות יב, טו), \u0003יכול\u0004 מיום ה\u0003ראשון\u0004 והלאה, \u0003ולא\u0004 יום \u0003ראשון\u0004 עצמו \u0003בכלל\u0004 זה, וכן עד יום ה\u0003שביעי ולא\u0004 יום \u0003שביעי\u0004 עצמו \u0003בכלל\u0004 זה,"],["\u0003כענין שנאמר\u0004 לגבי מצורע: \"וכסתה הצרעת את כל עור הנגע \u0003מראשו ועד רגליו\u0004 לכל מראה עיני הכהן... כלו הפך לבן טהור הוא\" (ויקרא יג, יב), וידוע לנו (כמבואר להלן) כי \"מ \u0003ראשו\"\u0004 — \u0003ולא ראשו\u0004 עצמו \u0003בכלל\u0004 זה, וכן \"ועד \u0003רגליו\"\u0004 — \u0003ולא רגליו\u0004 עצמם \u0003בכלל\u0004 זה, ושמא גם באיסור חמץ כך?","\u0003תלמוד לומר: \"עד יום האחד ועשרים לחדש בערב\"\u0004 (שמות יב, יח), כלומר, עד סוף היום השביעי, הרי שיום זה בכלל, והוא הדין ליום הראשון שנזכר יחד עמו בפסוק. \u0003רבי אומר: אינו צריך\u0004 ללמוד זאת משם, אלא כשהתורה אומרת \"מיום ה\u0003ראשון\"\u0004 כוונתה — \u0003ו\u0004\"יום ה\u0003ראשון\"\u0004 עצמו \u0003בכלל,\u0004 וכן \"יום ה\u0003שביעי\"\u0004 — \u0003ו\u0004יום ה\u0003שביעי בכלל.\u0004 ואם כן, לשיטת רבי לא הוצרכנו לגזירה שווה ששנינו במשנתנו, ללמד ש\"עד בן עשרים שנה\" כולל את שנת העשרים עצמה!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא שיטת \u0003רבי,\u0004 הוצרכנו לגזירה שווה זו, מפני שלשיטתו \u0003שקולי משקלי קראי\u0004 \u0005[שקולים הם\u0006 \u0005המקראות],\u0006 איזו מסקנה יש להסיק מהם. שכן \u0003מכדי כתיב\u0004 \u0005[הואיל ונאמר]:\u0006 \u0003\"מבן חדש ועד בן חמש שנים\u0004 והיה ערכך הזכר חמשה שקלים\" (ויקרא כז, ו), ואתה מניח כי שנת החמש עצמה בכלל זה, אם כן מה שנאמר \u0003תו\u0004 \u0005[עוד]:\u0006 \"ואם \u0003מבן חמש\u0004 שנים \u0003ועד בן עשרים\u0004 שנה והיה ערכך הזכר עשרים שקלים\" (שם ה) \u0003למה לי?\u0004 כלומר, משמע מכאן להיפך, שמי שהוא בשנת החמש נכלל בקבוצה הבוגרת יותר! \u0003הילכך אישתקלו להו\u0004 \u0005[על כן נעשו\u0006 שני הלימודים \u0005שקולים]\u0006 ולא ניתן ללמוד מהם, ויש צורך ללמוד מן הכתוב \"ואם מבן ששים שנה ומעלה\" (שם ז) ששנת חמש ושנת עשרים נחשבות כלמטה מהן.","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 לעיל בענין המצורע: \u0003\"ראשו\"\u0004 — \u0003ולא ראשו בכלל,\u0004 \u0003\"רגליו\"\u0004 — \u0003ולא רגליו בכלל.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דברים אלה? ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 מסברה: \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003סימנים\u0004 של צרעת שב\u0003גופו\u0004 \u0003מסימנים\u0004 שב\u0003ראשו,\u0004 וכגון צבע השיער המטמא, שבגוף הוא לבן, ובראש — צהוב. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 מהמקרא, שנאמר שם: \"מראשו ועד רגליו \u0003לכל מראה עיני הכהן\",\u0004 ואין הכהן יכול לראות את הנגע שבראשו מפני השיער, ולא את הנגעים שבין אצבעות רגליו.","נאמר במשנה, \u0003ר' אליעזר אומר:\u0004 שנת החמש ושנת העשרים ושנת הששים נידונות לענין ערכין כלמטה מהן, \u0003עד שיהו יתירות על השנים חודש ויום אחד.\u0004 ובטעם הדבר, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: נאמר כאן\u0004 בערכין \u0003\"למעלה\"\u0004 (\"ומעלה\", ויקרא כז, ז), \u0003ונאמר להלן\u0004 במנין הלויים במדבר: \"מבן \u0003חדש ומעלה\u0004 תפקדם\" (במדבר ג, טו), \u0003מה להלן\u0004 מדובר במי שהוא \u0003מבן חודש ויום אחד,\u0004 \u0003אף כאן\u0004 בערכין, כשנאמר \"מבן חמש\", \"מבן עשרים\", \"מבן ששים\", הכוונה היא: \u0003מבן חודש ויום אחד.\u0004","ושואלים: \u0003ואימא כי התם\u0004 \u0005[ואמור\u0006 שיהיה \u0005כמו שם],\u0006 \u0003מה התם חד יומא\u0004 \u0005[מה שם יום אחד]\u0006 לאחר התקופה שמדובר עליה (מבן חודש) — \u0003אף כאן חד יומא\u0004 \u0005[יום אחד]\u0006 בלבד הוא שנכנס בשנה הבאה! ומשיבים: \u0003אם כן\u0004 אתה אומר, \u0003גזירה שוה\u0004 זו \u0003מאי אהני\u0004 \u0005[מה הועילה]?\u0006 והרי גם בלעדיה היינו יודעים שהכוונה היא למחרת היום בו נשלמת השנה!","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שנה האמורה בקדשים\u0004 (קרבנות) כגון: \"כבשים בני שנה\" (במדבר כח, ג), \u0003שנה האמורה בבתי ערי חומה,\u0004 שהמוכר ביתו יכול לגואלו רק בתוך שנה (ויקרא כה, כט), \u0003שתי שנים ש\u0004נאמרו \u0003בשדה אחוזה\u0004 (נחלת אבות), שהמוכרה אינו יכול לגאול אותה לפני שתי שנים (שם טו), \u0003ושש שנים שבעבד עברי\u0004 (שמות כא, ב), \u0003וכן\u0004 השנים \u0003שבבן ושבבת\u0004 (כפי שיבואר בהמשך) כולן מחושבות \u0003מעת לעת\u0004 (מיום ליום) עד לאותו תאריך ואותה שעה בשנה הבאה, ולא עד סוף אותה שנה למנין העולם.","ושואלים: \u0003שנה האמורה בקדשים, מנלן\u0004 \u0005[מנין לנו]\u0006 שהיא מעת לעת? \u0003אמר רב אחא בר יעקב, אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"כבש בן שנתו\"\u0004 (ויקרא יב, ו), ולא \"בן שנה\", לדייק: \u0003שנתו שלו\u0004 (של הכבש) \u0003ולא\u0004 שנה \u0003של מנין עולם.\u0004","\u0003שנה האמורה בבתי ערי חומה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"והיתה גאולתו \u0003עד תם שנת ממכרו\"\u0004 (שם כה, כט), שנה מזמן \u0003ממכרו שלו,\u0004 כלומר, מיום שנמכר, \u0003ולא שנה למנין עולם.\u0004","\u0003שתי שנים שבשדה אחוזה\u0004 הן מעת לעת — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במספר שני תבואת ימכר לך\"\u0004 (שם טו), ולא \"במספר שנים\", ומכאן אתה למד שמספר השנים לחוד (ומיעוט שנים — שתיים) וכמות התבואות לחוד, וכך \u0003פעמים שאדם\u0004 שקונה שדה \u0003אוכל\u0004 ממנה \u0003שלש תבואות ב\u0004משך \u0003שתי שנים,\u0004 ודבר זה ייתכן רק אם קנאה מלאה תבואה בסוף השנה, וקצרה, ועמדה ברשותו עוד כשנתיים, והספיק לקצור תבואה פעמיים נוספות קודם שחזר הבעלים וקנאה ממנו. אבל אם מונים שנתיים למנין העולם — נשלמת השנה הראשונה בתשרי הקרוב, ועד תשרי השני אין אלא תבואה אחת נוספת.","\u0003שש\u0004 שנים \u0003שבעבד עברי\u0004 מעת לעת — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שש שנים יעבד ובשביעית\u0004 יצא לחפשי חינם\" (שמות כא, ב), וו' החיבור של \"ובשביעית\" מחבר אותה ל\"שש שנים יעבוד\", ללמדנו שמנין שש שנים הוא מעת לעת, וכך יוצא ש\u0003זימנין\u0004 \u0005[פעמים]\u0006 ש\u0003ב\u0004שנה ה\u0003שביעית\u0004 לשנות מנין העולם \u0003נמי יעבוד\u0004 \u0005[גם כן הוא עובד].\u0006","שנינו בברייתא: \u0003ושבבן ושבבת כולן מעת לעת.\u0004 ושואלים: \u0003למאי הילכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמר הדבר? \u0003אמר רב גידל אמר רב: לערכין,\u0004 כלומר, שמנין השנים לגיל הערכין נחשב מעת לעת לפי תאריך הלידה של הנערך או הנערכת, ולא למנין שנות העולם. \u0003רב יוסף אמר: ל\u0004ענין ההלכות של \u0003פרקין\u0004 \u0005[פרק]\u0006 של \u0003\"יוצא דופן\",\u0004 הפרק החמישי של מסכת נדה, ששנינו בו הלכות הנוגעות לגילים שונים של בן ובת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מי פלגיתו\u0004 \u0005[האם חלוקים אתם]\u0006 אתה ורב גידל לענין הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא, אנא אמרי חדא\u0004 \u0005[אני אמרתי\u0006 דבר \u0005אחד],\u0006 \u0003והוא אמר חדא\u0004 \u0005[\u0006דבר \u0005אחד].\u0006 ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר לומר],\u0006 \u0003דאי סלקא דעתך פליגי\u0004 \u0005[שאם עולה על דעתך\u0006 שהם \u0005חלוקים],\u0006 האם \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהכוונה היא \u0003לערכין לא אמר\u0004 \u0005[אינו אומר]\u0006 שמונים מעת לעת \u0003ל\u0004ענין ההלכות של פרק \u0003\"יוצא דופן\"? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב\u0004 כשלימד פרק \"יוצא דופן\": \u0003הילכתא בכולה פירקא\u0004 \u0005[הלכה בכל הפרק שלנו],\u0006 שהשנים המנויות בו מחושבות \u0003מעת לעת.\u0004","ושואלים: \u0003ואלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שכוונת הברייתא \u0003לערכין, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 שהכוונה היא \u0003ל\u0004הלכות שבפרק \u0003\"יוצא דופן\"?\u0004 ומשיבים: מפני שלדעתו יש לפרש את \"שבבן ושבבת\" \u0003דומיא דהנך\u0004 \u0005[בדומה לאלה\u0006 האחרים\u0005]\u0006 שמוזכרים לבברייתא, שנה של קדשים, בתי ערי חומה וכו', \u0003מה הנך דכתיבא\u0004 \u0005[מה אלה\u0006 מתייחסים לשנה \u0005שכתובה\u0006 בתורה\u0005],\u0006 \u0003אף הנך\u0004 \u0005[אלה]\u0006 \"ושבבן ושבבת\" לענין הלכה \u0003דכתיבא\u0004 \u0005[שכתובה]\u0006 בתורה, והיא שנה הכתובה בערכין. אבל ההלכות שבפרק \"יוצא דופן\" אינן כתובות בתורה.","\u0003ואידך\u0004 \u0005[והאחר\u0006 רב יוסף\u0005]\u0006 מה הוא סבור? \u0003אי סלקא דעתך דכתיבא\u0004 \u0005[אם עולה על דעתך\u0006 שהכוונה בברייתא היא לשנה של ערכין \u0005שכתובה\u0006 בתורה\u0005],\u0006 \u0003האי\u0004 \u0005[\u0006לשון \u0005זו]\u0006 \u0003\"שבבן ושבבת\"\u0004 שהזכירה הברייתא אינה מתאימה, אלא"],["לשון \u0003\"שבזכר ושבנקבה\" מיבעי ליה\u0004 \u0005[צריך היה\u0006 לומר\u0005],\u0006 שהרי זו לשון התורה בענין ערכין, ואילו פרק \"יוצא דופן\" משתמש בלשון \"בן\" ו\"בת\".","אגב שהוזכרה ההבחנה בין זכר לנקבה בדיני ערכין, שואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 דין ה\u0003נקבה דכי מיזקנא קיימא אתילתא\u0004 \u0005[שכאשר היא מזדקנת עומדת על שליש\u0006 מערכה הקודם\u0005],\u0006 שעד גיל ששים ערכה שלושים שקלים ומעל גיל ששים ערכה עשרה שקלים, \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003זכר דלא קאי אתילתא\u0004 \u0005[שאינו עומד על שליש\u0006 מערכו הקודם\u0005],\u0006 אלא על פחות מכך, שעד גיל ששים ערכו חמישים שקלים ומעל גיל ששים ערכו חמישה עשר שקלים? \u0003אמר חזקיה, אמרי אינשי\u0004 \u0005[אומרים האנשים],\u0006 פתגם ידוע הוא: \u0003סבא בביתא פאחא בביתא\u0004 \u0005[זקן בבית שבר בבית],\u0006 שאינו אלא למשא, \u0003סבתא בביתא סימא בביתא\u0004 \u0005[סבתא בבית אוצר בבית],\u0006 מפני שעוזרת במלאכות הבית.","","\u0003האומר: \"משקלי עלי\"\u0004 — \u0003נותן משקלו\u0004 להקדש, \u0003אם כסף כסף, ואם זהב זהב. מעשה באמה של ירמטיא שאמרה: \"משקל בתי עלי\", ועלתה לירושלים ושקלה,\u0004 נתנה האם את \u0003משקלה\u0004 ב\u0003זהב.\u0004","האומר: \u0003\"משקל ידי עלי\",\u0004 כיצד אומדים את משקל ידו? \u0003ר' יהודה אומר: ממלא חבית מים, ומכניסה\u0004 את ידו לחבית \u0003עד מרפיקו, ו*\u0004 כנגד נפח המים שיצאו \u0003שוקל\u0004 חתיכות \u0003מבשר חמור ועצמות וגידים ונותן לתוכה\u0004 של החבית \u0003עד שתתמלא,\u0004 וכמשקל אותן חתיכות יתן להקדש. \u0003אמר ר' יוסי: וכי היאך אפשר לכוין\u0004 שתהא כמות \u0003בשר\u0004 החמור \u0003כנגד\u0004 כמות ה\u0003בשר\u0004 שבידו, \u0003ועצמות\u0004 החמור \u0003כנגד\u0004 ה\u0003עצמות\u0004 שבידו? \u0003אלא שמין\u0004 (אומדים) \u0003את היד כמה היא ראויה לשקול.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מה ששנינו במשנה: ונותן משקלו, \u0003אם כסף כסף אם זהב זהב? אמר רב יהודה:\u0004 אם \u0003פירש\u0004 שהוא נודר משקלו ב\u0003כסף\u0004 — נותן \u0003כסף,\u0004 אם \u0003פירש זהב\u0004 — נותן \u0003זהב.\u0004 ותמהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא\u0003!\u0004 ואומרים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003פירש\u0004 ממה יתן, צריך לתת כסף או זהב, \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003לא פירש\u0004 — \u0003פטר נפשיה בכל דהו\u0004 \u0005[פוטר את עצמו בכל שהוא],\u0006 בכל דבר שדרך אנשים לשקול, \u0003כ\u0004דברי \u0003רחבה,\u0004 ש\u0003אמר רחבה: באתרא דתקלי כופרא\u0004 \u0005[במקום ששוקלים\u0006 המוכרים \u0005זפת],\u0006 \u0003פטר נפשיה אפילו בכופרא\u0004 \u0005[פוטר עצמו\u0006 הנודר \u0005אפילו בזפת\u0006 במשקלו\u0005].\u0006 ותמהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקום \u0003דאיכא דתקל ואיכא דכייל\u0004 \u0005[שיש\u0006 מוכר \u0005ששוקל\u0006 אותו \u0005ויש שמודד\u0006 בנפח\u0005],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דכולהו לא תקלי\u0004 \u0005[שלא כולם שוקלים],\u0006 \u0003לא\u0004 יפטור עצמו בנתינת זפת כמשקלו, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שכיון שיש שם מוכרים ששוקלים זפת — יוצא בכך ידי נדרו.","","\u0003אמר רב פפא: באתרא דתקלי שמכי\u0004 \u0005[במקום ששוקלים בצלים],\u0006 \u0003פטר נפשיה אפילו בשמכי\u0004 \u0005[פוטר עצמו\u0006 הנודר \u0005אפילו בבצלים]\u0006 במשקלו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו אלא במקום \u0003דבתר דשקלי שדו תרי תלתא\u0004 \u0005[שלאחר ששוקלים זורקים\u0006 לכלי הקונה \u0005שנים שלושה\u0006 בצלים נוספים\u0005],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003בטיל\u0004 \u0005[בטלה]\u0006 \u0003תורת\u0004 מכירה ב\u0003משקל,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שעדיין נחשב הדבר למכירה במשקל.","שנינו במשנה: \u0003מעשה באמה של ירמטיא\u0004 שאמרה \"משקל בתי עלי\", ועלתה לירושלים ושקלה, ונתנה משקלה זהב. ומתחילה אמרה המשנה (כפי שנתבאר לעיל) כי דווקא מי שפירש בנדרו זהב צריך לתת זהב, אבל מי שנדר בסתם — יוצא ידי חובתו בכל שהוא. ועל כך תמהים: וכי מביאה המשנה \u0003מעשה לסתור\u0004 את דבריה הקודמים?!","ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003ואם אדם חשוב הוא, אף על גב דלא פריש\u0004 [אף על פי שלא פירש] ממה יתן — \u0003לפי כבודו אמרינן\u0004 \u0005[אנו אומרים]\u0006 שצריך לתת, \u0003ומעשה באמה של ירמטיא\u0004 שהיתה עשירה ביותר, \u0003שאמרה \"משקל בתי עלי\", ועלתה לירושלים ושקלוה ונתנה משקלה זהב.\u0004","\u0003אמר רב יהודה: האומר \"קומתי עלי\"\u0004 — \u0003נותן שרביט\u0004 (מוט) עבה \u0003שאינו נכפף,\u0004 בגובה קומתו, אם אמר: \u0003\"מלא קומתי עלי\"\u0004 — \u0003נותן\u0004 \u0003שרביט\u0004 דק \u0003הנכפף,\u0004 ודיו. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא, כי בין שאמר: \u0003\"קומתי עלי\"\u0004 ובין שאמר: \u0003\"מלא קומתי עלי\"\u0004 — \u0003נותן\u0004 תמיד \u0003שרביט שאינו נכפף!\u0004","ומשיבים: \u0003הוא\u0004 (רב יהודה) ש\u0003אמר כ\u0004שיטת \u0003ר' עקיבא דדייק לישנא יתירא\u0004 \u0005[שמדייק בלשון יתירה],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אדם שמוכר בית, אינו כולל במכירה \u0003לא את הבור\u0004 שבתוכו \u0003ולא את הדות\u0004 (כעין בור שדפנותיו בנויות מאבנים), \u0003אף על פי שכתב\u0004 בשטר מכירת הבית שמוכר גם \u0003עומקה ורומה\u0004 (עומק ורום). \u0003ו\u0004אולם \u0003צריך\u0004 המוכר \u0003ליקח\u0004 (לקנות) \u0003לו\u0004 \u0003דרך\u0004 מן הקונה כדי להגיע אליהם, \u0003דברי ר' עקיבא.\u0004 \u0003וחכמים אומרים: אינו צריך,\u0004 שלדעתם, כשם ששייר את הבור והדות לעצמו — כך שייר גם דרך אליהם. \u0003ומודה ר' עקיבא, בזמן שאמר לו\u0004 במפורש שהוא מוכר לו את הבית \u0003חוץ מאלו,\u0004 מהבור והדות — \u0003שאין צריך ליקח לו דרך. אלמא\u0004 \u0005[מכאן]\u0006 שר' עקיבא סבור כי \u0003כיון\u0004 ש\u0003לא צריך\u0004 לומר דבר, \u0003ו\u0004בכל זאת \u0003קאמר\u0004 \u0005[הוא אומר]\u0006 — \u0003לטפויי מילתא קאתי\u0004 \u0005[להוסיף דבר\u0006 לטובתו \u0005הוא בא],\u0006 שכוונתו להותיר לעצמו גם את הדרך. \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לענין הנדר, \u0003כיון\u0004 שדי שיאמר: \"קומתי\" ו\u0003לא צריך\u0004 לומר \"מלוא קומתי\", \u0003וקאמר\u0004 \u0005[והוא אומר]\u0006 זאת — \u0003לטפויי מילתא קאתי\u0004 \u0005[להוסיף דבר\u0006 לטובתו \u0005הוא בא],\u0006 וכוונתו שיתן שרביט נכפף, ולא שרביט רגיל כקומתו.","","בעקבות הלכה זו בענין \"קומתי\", \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: אם אמר \"\u0003עומדי\u0004 עלי\", \u0003מהו,\u0004 מה התכוון לתת?"],["\u0003\"רוחבו\u0004 של פלוני עלי\", \u0003מהו? \"ישיבתו\", מהו? \"עוביו\", מהו? \"היקיפו\", מהו?\u0004 מה התכוון לתת בכל אחד מאלה? שאלות אלה לא נפתרו ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה מחלוקת בענין האומר: \u0003\"משקל ידי עלי\",\u0004 כיצד אומדים את משקל היד. ומחלוקת זו מובאת בהרחבה בברייתא, שכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האומר \u0003\"משקל ידי\u0004 או \u0003משקל רגלי עלי\", ר' יהודה אומר: מביא חבית וממלא מים, ומכניס ביד עד האציל\u0004 (המרפק), \u0003וברגל עד הארכובה\u0004 (הברך),","\u0003ושוקל בשר חמור גידים ועצמות\u0004 בכמות היחסית שיש בידו של אדם, \u0003ונותן לתוכה עד שתתמלא\u0004 בשנית. \u0003ואף על פי שאין ראיה לדבר\u0004 שבשר חמור שוקל כבשר אדם — \u0003זכר לדבר, שנאמר: \"אשר בשר חמורים בשרם\"\u0004 (יחזקאל כג, כ).","\u0003אמר לו ר' יוסי: היאך אפשר לכוין\u0004 בדיוק כמות של \u0003בשר\u0004 החמור \u0003כנגד בשר\u0004 שביד, ו\u0003גידים\u0004 של חמור \u0003כנגד\u0004 ה\u0003גידים\u0004 שביד, ו\u0003עצמות\u0004 החמור \u0003כנגד\u0004 ה\u0003עצמות\u0004 שביד? \u0003אמר לו ר' יהודה: אומדין\u0004 (משערים) דברים אלו. \u0003אמר לו ר' יוסי: עד שאומדין\u0004 באופן זה, \u0003ימודו\u0004 (יאמדו) ישירות \u0003את\u0004 משקל \u0003היד.\u0004 עד כאן הדיון שבברייתא. ומוסיפים: \u0003ור' יהודה\u0004 מה הוא עונה לכך? הוא סבור כי \u0003כמה\u0004 ש\u0003אפשר\u0004 לדייק \u0003עבדינן\u0004 \u0005[עושים אנו].\u0006","נאמר בברייתא שכשאמר \"משקל ידי ורגלי עלי\", \u0003ביד\u0004 מודדים \u0003עד האציל\u0004 (המרפק), ומכאן עולה כי זו היא הגדרת \"יד\". \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003קידוש ידים ורגלים במקדש\u0004 (שציותה עליו התורה: \"ורחצו אהרן ובניו ממנו את ידיהם ואת רגליהם\", שמות ל, יט) — \u0003עד הפרק,\u0004 מקום חיבור הכף והזרוע!","ומשיבים: \u0003דאורייתא\u0004 \u0005[\u0006בלשון \u0005של תורה]\u0006 משמעות \"יד\" היא \u0003עד הפרק,\u0004 אבל \u0003בנדרים\u0004 (\"משקל ידי עלי\") — \u0003הלך אחר לשון בני אדם,\u0004 ושם המשמעות היא עד האציל. ושואלים: \u0003ודאורייתא\u0004 \u0005[ו\u0006בלשון \u0005של תורה]\u0006 משמעות \"יד\" \u0003עד הפרק\u0004 בלבד? \u0003והא גבי\u0004 \u0005[והרי אצל]\u0006 \u0003תפילין\u0004 אין אומרים כן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"והיה לך לאות על \u0003ידך\"\u0004 (שם יג, ט), \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה: \"ידך\"\u0004 — \u0003זו קיבורית\u0004 (הבשר התפוח שבין המרפק לכתף)!","אלא: \u0003דאורייתא\u0004 \u0005[\u0006בלשון \u0005של תורה]\u0006 \u0003קיבורית כולה\u0004 נכללת גם היא בשם \"יד\", \u0003בנדרים הלך אחר לשון בני אדם,\u0004 ובלשונם \"יד\" היא עד המרפק, \u0003וקידוש ידים ורגלים במקדש — הילכתא גמירי לה\u0004 \u0005[הלכה\u0006 למשה מסיני \u0005לומדים אותה]\u0006 שמצוה לקדש עד הפרק בלבד.","ועוד שנינו בברייתא כי \u0003ברגל,\u0004 כשאומר \"משקל רגלי עלי\" — מודדים \u0003עד הארכובה\u0004 (הברך), \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: מה שנאמר בתורה בחובת עליה לרגל \"שלש \u0003רגלים\u0004 תחג לי בשנה\" (שם כג, יד), ולא \"שלש פעמים\", בא ללמדנו — \u0003פרט לבעלי קבין,\u0004 כלומר, מי שנקטעה כף רגלו ונותן את הגדם בתוך קב (תותב), שהוא פטור מלעלות לרגל, מפני שאין לו רגל. והלא לפי הברייתא, מי שלא נקטעה רגלו עד הברך עדיין יש לו רגל!","ומשיבים: אף שמן התורה \"רגל\" היא כף הרגל עד הקרסול, \u0003בנדרים\u0004 (\"משקל רגלי עלי\") \u0003הלך אחר לשון בני אדם,\u0004 והם קוראים \"רגל\" עד הברך. ושואלים: \u0003ודאורייתא\u0004 \u0005[ו\u0006בלשון \u0005של תורה]\u0006 \"רגל\" משמעה \u0003פרט לבעלי קבין\u0004 ולא עד הברך?","\u0003והא גבי\u0004 \u0005[והרי אצל]\u0006 \u0003חליצה\u0004 אין אומרים כן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ונגשה יבמתו... וחלצה נעלו מעל \u0003רגלו\"\u0004 (דברים כה, ט), \u0003ותנא\u0004 \u0005[ושנה\u0006 החכם בברייתא\u0005]:\u0006 יבם גידם, אם \u0003חלצה\u0004 נעלו \u0003מן הארכובה\u0004 (הברך) \u0003ולמטה\u0004 — \u0003חליצתה כשרה!\u0004","ומשיבים: \"רגל\" שבתורה היא אמנם רק עד הקרסול, ואולם \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 לענין חליצה, \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"מעל רגלו\"\u0004 (ולא \"מרגלו\"), ולשון זו מכשירה גם מה שלמעלה מ\"רגלו\". ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם חלצה \u0003למעלה מהארכובה\u0004 (מהברך) \u0003נמי\u0004 \u0005[גם כן]\u0006 תהא חליצתה כשרה! ומשיבים: נאמר \u0003\"מעל\",\u0004 כלומר, מה שמעל כף הרגל, \u0003ולא מעל\u0004 של \u0003מעל\u0004.","\u0003אמר רב פפא, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003האי איסתוירא\u0004 \u0005[\u0006עצם \u0005הקרסול]\u0006 \u0003עד ארעא נחית\u0004 \u0005[עד הארץ\u0006 הוא \u0005יורד],\u0006 ואינו מופסק לעצמו מכף הרגל, \u0003דאי סלקא דעתך מיפסק פסיק\u0004 \u0005[שאם עולה על דעתך שהוא מופסק]\u0006 מכף הרגל, \u0003הוה ליה איסתוירא\u0004 \u0005[נמצא הקרסול]\u0006 \u0003מעל\u0004 הרגל, \u0003ושקא\u0004 \u0005[והשוק],\u0006 החלק שמעל הקרסול, היא \u0003מעל\u0004 של \u0003מעל,\u0004 ולא היו מכשירים חליצה משם. \u0003רב אשי אמר: אפילו תימא מיפסק פסיק\u0004 \u0005[\u0006אפילו \u0005תאמר\u0006 שהקרסול \u0005נפרד]\u0006 מכף הרגל לא היו קוראים לו \"מעל הרגל\", מפני ש\u0003כל דבהדי כרעא ככרעא דמי\u0004 \u0005[כל שסמוך ל\u0006כף ה\u0005רגל כ\u0006כף \u0005רגל\u0006 הוא \u0005נחשב].\u0006","האומר: \u0003\"דמי ידי עלי\"\u0004 — \u0003שמין\u0004 (אומדים) \u0003אותו כמה הוא שוה ביד ובלא יד\u0004, ויתן את ההפרש. \u0003זה חומר בנדרים מבערכין,\u0004 שאילו אמר: \"ערך ידי עלי\" — פטור.","ושואלים: \u0003היכי שיימינן ליה\u0004 \u0005[כיצד אומדים אותו]?\u0006 \u0003אמר רבא: אומדין אותו אומד של\u0004 תשלומי \u0003נזקין,\u0004 כפי ששמים אדם שנקטעה ידו, כמה היה שווה מתחילה כעבד, וכמה עכשיו, והמזיק משלם את ההפרש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומים\u0006 הדברים\u0005]?\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בנזיקין\u0005]\u0006 כיון שנקטעה ידו \u0003גברא זילא\u0004 \u0005[אדם מזולזל]\u0006 \u0003הוא,\u0004 והשומה של הנזק גדולה יותר מאשר חוסר האפשרות לעבוד ביד זו. \u0003הכא גברא שביח\u0004 \u0005[כאן,\u0006 שאמר \"דמי ידי עלי\", \u0005אדם משובח]\u0006 \u0003הוא,\u0004 ואם נאמוד אותו אומד של נזיקין נמצא חייב להקדש יותר ממה שנדר!","אלא \u0003אמר אביי: אומדין כמה אדם רוצה ליתן בעבד העושה מלאכה\u0004 רק \u0003בידו אחת ל\u0004בין עבד ה\u0003עושה בשתי ידיו.\u0004 ושואלים: ב\u0003ידו אחת מאי ניהו\u0004 \u0005[מה היא]\u0006 מציאות זו, \u0003ואידך פסיקא\u0004 \u0005[והאחרת חתוכה]?\u0006 \u0003היינו הך\u0004 \u0005[הרי זה אותו דבר]\u0006 כמו שאמר רבא! \u0003אלא\u0004 אומדים כמה אדם רוצה ליתן בעבד ש\u0003ידו מוכתבת לרבו ראשון,\u0004 כלומר, שנכתב בשטר מכירתו שביד זו יעשה מלאכה רק לרבו הקודם.","ודנים בשאלות עקרוניות הנוגעות לאומדן של מי שנדר דמיו להקדש, ושנינו במשנה (סנהדרין ב,א) כי אומדן זה נעשה על פי עשרה אנשים ואחד מהם כהן. וכך \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: אמדוהו אומד של נזקין,\u0004 כגון שחבל בו חבירו ואמדוהו כמה הוא שווה כעת, \u0003ואמר: \"דמי עלי\", מהו\u0004 דינו? \u0003מי אמר: הא אמדוהו חדא זימנא\u0004 \u0005[האם נאמר: הרי\u0006 כבר \u0005אמדנו אותו פעם אחת],\u0006 ויתן סכום זה, \u0003או דילמא שאני אומדנא דבי עשרה מאומדנא דבי תלתא\u0004 \u0005[שמא שונה אומדן של עשרה\u0006 שנעשה להקדשות, \u0005מאומדן של שלושה,\u0006 שנעשה לצורך נזקים\u0005]?\u0006","\u0003אם תמצא לומר: שאני אומדנא דבי עשרה מאומדנא דבי תלתא\u0004 \u0005[שונה אומדן של עשרה מאומדן של שלושה],\u0006 וצריך לחזור ולאמוד אותו בעשרה, אם \u0003אמר: \"דמי עלי\" ואמדוהו,\u0004 \u0003וחזר ואמר\u0004 בשנית: \u0003\"דמי עלי\", מהו?\u0004 האם נאמר כי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי\u0004 כבר \u0003אמדוהו בי עשרה\u0004 \u0005[עשרה אנשים],\u0006 ואינו צריך אומדן נוסף. \u0003או\u0004 יש לחשוש \u0003דילמא שבח ביני וביני\u0004 \u0005[שמא השביח\u0006 ועלה ערכו \u0005בינתיים]?\u0006","ואם תאמר שצריך לחזור ולאמוד אותו, \u0003אמר: \"דמי עלי\" ולא אמדוהו, וחזר ואמר:\u0004 \u0003\"דמי עלי\", מהו\u0004 דינו? \u0003הכא\u0004 \u0005[כאן],\u0006 האם נאמר כי \u0003ודאי\u0004"],["\u0003בחד זימנא אמדינן ליה\u0004 \u0005[בפעם אחת אנו אומדים אותו],\u0006 ויתן פעמיים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003בזה אחר זה נדר\u0004 — \u0003תרי זימני אמדינן ליה\u0004 \u0005[שתי פעמים אנו אומדים אותו]?\u0006","\u0003ואם תמצא לומר: כיון\u0004 שבמקרה ש\u0003בזה אחר זה נדר תרי זימני אמדינן ליה\u0004 \u0005[שתי פעמים אנו אומדים אותו],\u0006 אם \u0003אמר: \"שני דמי עלי\",\u0004 ונמצא שהתחייב בשני דמיו \u0003בבת אחת, מהו? הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי\u0004 מכיוון ש\u0003בבת אחת נדר,\u0004 לכן גם \u0003בבת אחת אמדינן ליה\u0004 \u0005[אומדים אנו אותו],\u0006 וישלם פי שנים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דקאמר\u0004 \u0005[שאומר]\u0006 \u0003\"שני\u0004 דמי עלי\" — \u0003כ\u0004שני נדרים \u0003זה אחר זה דמי\u0004 \u0005[נחשב],\u0006 וצריך לאומדו שתי פעמים?","\u0003אם תימצי לומר: כיון דקאמר\u0004 \u0005[שאומר]\u0006 \u0003\"שני\u0004 דמי עלי\" \u0003כזה אחר זה דמי\u0004 \u0005[נחשב],\u0006 אם \u0003אמדוהו מאליו,\u0004 עשרה אנשים, שלא לשם תשלום להקדש, \u0003מהו? מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003הא אמיד מאליו וקאי\u0004 \u0005[הריהו\u0006 כבר \u0005אמוד מאליו ועומד\u0006 לפנינו\u0005],\u0006 \u0003או דלמא בעינן\u0004 \u0005[שמא צריכים אנו]\u0006 \u0003כוונה לאומדנא\u0004 \u0005[לאומדן\u0006 לשם הקדש\u0005]?\u0006","ומציעים: \u0003פשוט מהא חדא\u0004 \u0005[פתור מזו\u0006 ששנינו שאלה \u0005אחת],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 להלן: האומר \u0003\"דמי עלי\" ומת\u0004 — \u0003לא יתנו יורשין,\u0004 מפני \u0003שאין דמים\u0004 (שווי) \u0003למתים,\u0004 ואין אנו יודעים כמה היה שווה מתחילה כדי לשומו כשעת נדרו.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כי אם \u0003אמדוהו מאליו הוי אומדנא\u0004 \u0005[הרי זה אומדן],\u0006 מדוע לא נחייב את היורשים? \u0003הא אמיד וקאי\u0004 \u0005[הרי\u0006 הוא \u0005אמוד ועומד],\u0006 שהרי \u0003מי איכא גברא דלא שוי ארבעה זוזי\u0004 \u0005[האם יש אדם שלא שווה ארבעה זוזים]?\u0006 ומכאן שצריך כוונה לאומדן של הקדש, ולא די באומדן מאליו!","ודוחים: אין להוכיח מכאן, שהרי זה ש\u0003אמדוהו מאליו\u0004 הרי \u0003נחית לאומדנא\u0004 \u0005[ירד לאומדן],\u0006 שאמדוהו בפועל, אבל האומר \u0003\"דמי עלי\"\u0004 ומת לפני שאמדוהו — \u0003לא נחית לאומדנא\u0004 \u0005[לא ירד\u0006 כלל \u0005לאומדן],\u0006 ולכן אין ללמוד משם.","\u0003חומר בערכין מבנדרים\u0004 (נדרי דמים), \u0003כיצד? האומר: \"ערכי עלי\" ומת\u0004 — \u0003יתנו היורשים,\u0004 אבל אם אמר: \u0003\"דמי עלי\" ומת\u0004 — \u0003לא יתנו היורשים,\u0004 מפני \u0003שאין דמים\u0004 (שווי) \u0003למתים.\u0004 ועוד בדיני ערכין.","האומר: \u0003\"ערך ידי\u0004 עלי\", \u0003ו\u0004כן האומר: \u0003\"ערך רגלי עלי\"\u0004 — \u0003לא אמר כלום,\u0004 שהרי יש ערך בתורה רק לאדם שלם. אבל האומר: \u0003\"ערך ראשי\u0004 עלי\", \u0003ו\u0004כן האומר: \u0003\"ערך כבידי עלי\"\u0004 — הרי זה \u0003נותן ערך כולו. זה הכלל:\u0004 הנודר ערך של \u0003דבר שהנשמה תלויה בו,\u0004 שבלעדיו ימות האדם — \u0003נותן ערך כולו.\u0004","האומר: \u0003\"חצי ערכי עלי\"\u0004 — \u0003נותן חצי ערכו,\u0004 האומר: \u0003\"ערך חציי עלי\"\u0004 — \u0003נותן ערך כולו,\u0004 שהרי העריך דבר שהנשמה תלויה בו. האומר \u0003\"חצי דמי עלי\"\u0004 — \u0003נותן חצי דמיו,\u0004 האומר \u0003\"דמי חציי עלי\"\u0004 — \u0003נותן דמי כולו. זה הכלל:\u0004 הנודר דמיו של \u0003דבר שהנשמה תלויה בו\u0004 — \u0003נותן דמי כולו.\u0004","\u0003האומר: \"ערכו של פלוני עלי\",\u0004 אפילו \u0003מת הנודר ו\u0004מת \u0003הנודר\u0004 — \u0003יתנו היורשין.\u0004 אבל האומר: \u0003\"דמיו של פלוני עלי\", ומת הנידר\u0004 — \u0003יתנו היורשין, מת הנידר\u0004 — \u0003לא יתנו היורשין, שאין דמים למתים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003חומר בנדרים מבערכין, שהנדרים חלין על בהמה חיה ועוף,\u0004 כגון שאמר: \"דמי בהמה זו עלי\", ואין נדונים בהם העניים \u0003בהשג יד,\u0004 ליפטר במה שמשיגה ידו באותה שעה. \u0003מה שאין כן בערכין,\u0004 שאין ערך קצוב בתורה אלא לאנשים, ונידונים בהשג יד.","\u0003חומר בערכין מבנדרים, כיצד? אמר: \"ערכי עלי\" ומת\u0004 — \u0003יתנו יורשין,\u0004 אבל אמר: \u0003\"דמי עלי\" ומת\u0004 — \u0003לא יתנו יורשין, שאין דמים למתים.\u0004","שנינו בברייתא: \u0003אמר \"ערכי עלי\" ומת\u0004 — \u0003יתנו יורשין.\u0004 ושואלים: \u0003שמע מינה\u0004 \u0005[\u0006האם \u0005תלמד מכאן]\u0006 ש\u0003מלוה\u0004 (חוב) \u0003על פה גובה מן היורשין?\u0004 שהרי לא נכתב שטר חוב להקדש על הערך! ודוחים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 הדין מסתם מילוה על פה, מפני ש\u0003מלוה\u0004 ש\u0003כתובה בתורה היא,\u0004 שכיון שאמר: \"ערכי עלי\" — כבר כתוב בתורה כמה עליו לתת, לפי גילו ומינו.","ושואלים, אם כך, האם \u0003שמע מינה\u0004 \u0005[תלמד מכאן]\u0006 ש\u0003מלוה הכתובה בתורה ככתובה בשטר דמיא\u0004 \u0005[נחשבת]?\u0006 ודוחים באופן אחר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשעמד בדין,\u0004 וחייבוהו לתת את ערכו קודם שמת, ופסק דין נחשב ככתוב בשטר, ולכן יתנו היורשים.","ואומרים: אם כן, \u0003דכוותה\u0004 \u0005[כיוצא בה]\u0006 \u0003גבי \"דמי עלי\",\u0004 שמוזכר בהמשך, מדובר גם כן כ\u0003שעמד בדין,\u0004 אם כן, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא יתנו יורשין?\u0004 ומשיבים: אם אמר \u0003\"דמי עלי\",\u0004 גם אם עמד בדין וחייבוהו לשלם — עדיין הוא \u0003מחוסר\u0004 \u0003אומדנא\u0004 \u0005[אומדן],\u0006 כמה עליו לשלם, אבל אמר: \u0003\"ערכי עלי\"\u0004 ועמד בדין — \u0003לא מחוסר ולא כלום,\u0004 שהרי ערכו כבר קצוב בתורה.","שנינו במשנה: מי שנדר \u0003\"ערך ידי\u0004 עלי\" או \"ערך \u0003רגלי עלי\"\u0004 — לא אמר כלום. \u0003אמר רב גידל אמר רב: ו\u0004למרות זאת \u0003נותן דמיה\u0004 של היד או הרגל.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"לא אמר כלום\" קתני\u0004 \u0005[הוא שונה]!\u0006 ומשיבים: \u0003לא אמר כלום ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ונותן דמיה ל\u0004דעת \u0003ר' מאיר,\u0004 הסבור שאין אדם מוציא דבריו לבטלה, וכוונתו היתה לתת דמים.","ושואלים: \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה\u0004 רב גידל \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003אמר רב גידל אמר רב: האומר \"ערך כלי זה עלי\",\u0004 למרות שאין ערך לכלי — \u0003נותן דמיו,\u0004 לדעת ר' מאיר!","ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 ש\u0003אדם יודע שאין ערך לכלי ו\u0004לכן \u0003גמר\u0004 בליבו \u0003ואמר לשם דמים, אבל הכא\u0004 \u0005[כאן]\u0006 יש להניח כי \u0003מיטעא קטעי\u0004 \u0005[טועה הוא],\u0006 \u0003דסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]\u0006 \u0003כי היכי דאיכא\u0004 \u0005[כמו שיש]\u0006 \u0003\"ערך ראשי\" ו\"ערך כבידי\",\u0004 המחייבו, כפי ששנינו במשנה — \u0003איכא נמי\u0004 \u0005[יש גם כן]\u0006 \u0003ערך ידי וערך רגלי,\u0004 ועל דעת כן נדר, ופטור. \u0003אבל דמי לא קאמר\u0004 \u0005[אבל\u0006 לתת \u0005דמים לא אמר\u0006 בליבו\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב גידל שגם כאן אין לחשוש לטעות, אלא כוונתו לתת דמים.","שנינו במשנה: \u0003\"ערך ראשי\" ו\"ערך כבידי\"\u0004 — \u0003נותן ערך כולו.\u0004 ואומרים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \"בערכך \u0003נפשת\"\u0004 (ויקרא כז, ב) \u0003קאמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ולמדים משם שהמעריך דבר שהנפש תלויה בו נותן את כל הערך.","שנינו במשנה: \u0003זה הכלל דבר שהנשמה תלויה בו\u0004 נותן ערך כולו. ואומרים: \"זה הכלל\" נאמר כאן כדי \u0003לאתויי\u0004 \u0005[להביא]\u0006 מי שהעריך את רגלו \u0003מן הארכובה\u0004 (הברך) \u0003ולמעלה,\u0004 שהואיל ואם נקטעה במקום זה אינו יכול לחיות, הרי זה דבר שהנשמה תלויה בו.","שנינו במשנה: אמר \u0003\"חצי ערכי עלי\"\u0004 — \u0003נותן\u0004 חצי ערכו. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 האומר \u0003\"חצי ערכי עלי\"\u0004 — \u0003נותן חצי ערכו. ר' יוסי בר' יהודה אומר: לוקה ונותן ערך שלם.\u0004","ותוהים: \u0003לוקה? אמאי\u0004 \u0005[מדוע]?\u0006 והרי לא חטא! \u0003אמר רב פפא: לוקה ב\u0004כך שנותן \u0003ערך שלם,\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003גזירה\u0004 באומר \"\u0003חצי ערכי\u0004 עלי\" \u0003אטו\u0004 \u0005[משום]\u0006 האומר ש\u0003ערך חציו\u0004 עליו, שהיא לשון דומה, \u0003ו\u0004הרי \u0003ערך חציו הוי\u0004 \u0005[הוא]\u0006 \u0003דבר שהנשמה תלויה בו,\u0004 וצריך לתת ערך כולו.","עוד שנינו במשנה: אמר \u0003\"חצי דמי עלי\"\u0004 — \u0003נותן\u0004 חצי דמיו, \u0003\"דמי חציי עלי\"\u0004 — \u0003נותן דמי כולו,\u0004 שנדר דמי דבר שהנשמה תלויה בו. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 והלא דין זה נלמד מן הכתוב \"נפשות\" האמור בנדרי ערכין, ולא בנדרי דמים!","ומשיבים: \"איש כי יפליא \u0003נדר בערכך נפשת\"\u0004 (שם) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ובכך הוקשו נדרי דמים לערכין לדין זה.","ועוד שנינו במשנה: \u0003זה הכלל,\u0004 הנודר דמי \u0003דבר שהנשמה תלויה בו\u0004 — נותן דמי כולו. ואומרים: לשון \"זה הכלל\" \u0003לאתויי\u0004 \u0005[להביא]\u0006 שהנודר דמי הרגל \u0003מן הארכובה ולמעלה,\u0004 שיתן דמי כולו, כפי שהסברנו לענין ערכין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003המעריך חצי ערך כלי,\u0004 שאמר: \"חצי ערך כלי זה עלי\" — \u0003ר' מאיר אומר: נותן\u0004 חצי \u0003דמיו\u0004 של הכלי, \u0003וחכמים אומרים: לא אמר כלום.\u0004 מסופר, \u0003רבא חלש\u0004 \u0005[חלה],\u0006 \u0003עול לגביה\u0004 \u0005[נכנסו אצלו]\u0006 לבקרו \u0003אביי ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003ויתבי וקאמרי\u0004 \u0005[והיו יושבים ואומרים]:\u0006 \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר לשיטת\u0005]\u0006 \u0003ר' מאיר, קסבר\u0004 \u0005[\u0006ש\u0005הוא סבור]:\u0006 \u0003אין אדם מוציא דבריו לבטלה,\u0004 ולכן \u0003לא שנא\u0004 \u0005[לא שונה]\u0006 דין המעריך \u0003כולו\u0004 (כל הכלי), \u0003ולא שנא\u0004 \u0005[ולא שונה]\u0006 דין המעריך \u0003חציו,\u0004 ובכל מקרה התכוון לתת את דמיו.","\u0003אלא רבנן מאי קסברי\u0004 \u0005[חכמים מה הם סבורים]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 סבורים הם ש\u0003אדם מוציא דבריו לבטלה\u0004 — \u0003אפילו\u0004 אם נדר ערך \u0003כולו נמי\u0004 \u0005[גם כן]\u0006 יהיה פטור, ולאו דווקא במקרה שנחלקו בו, של המעריך חצי כלי, \u0003ואי\u0004 \u0005[ואם]\u0006 סבורים הם כר' מאיר ש\u0003אין אדם מוציא דבריו לבטלה\u0004 — \u0003אפילו\u0004 נדר ערך \u0003חציו נמי\u0004 \u0005[גם כן]\u0006 יתחייב לתת חצי דמיו!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא ואביי: רבנן דהכא\u0004 \u0005[חכמים של כאן,\u0006 של ברייתא זו\u0005]\u0006 \u0003כר' מאיר סברי לה\u0004 \u0005[סבורים הם],\u0006 \u0003וסברי לה\u0004 \u0005[וסבורים הם]\u0006 גם \u0003כ\u0004שיטת \u0003ר' שמעון.\u0004 ומפרטים: \u0003סברי לה\u0004 \u0005[סבורים הם]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר,\u0004 ש\u0003אמר: אין אדם מוציא דבריו לבטלה,\u0004 ולכן אם היה נודר ערך כל הכלי כוונתו היתה לדמיו, ויתן דמי כולו,","\u0003וסברי לה\u0004 \u0005[ו\u0006אולם \u0005סבורים הם]\u0006 גם \u0003כר' שמעון,\u0004 ש\u0003אמר\u0004 כי האומר: \"הרי עלי מנחה מן השעורים\" (ואין מתנדבים מנחה של שעורים) — פטור מלהביא מנחה של חיטים, מפני \u0003שלא התנדב כדרך המתנדבים;\u0004 ואף לענייננו, כוליה אורחיה לאיתנדובי \u0005[כולו,\u0006 כלי שלם, \u0005דרכו\u0006 של אדם \u0005להתנדב],\u0006 ולכן מתחייב בדמיו, \u0003פלגיה לאו אורחיה לאיתנדובי\u0004 \u0005[חציו\u0006 של כלי \u0005אין דרכו\u0006 של אדם \u0005להתנדב],\u0006 ולכן פטור לגמרי.","שנינו במשנה: \u0003האומר \"ערכו של פלוני עלי\", ומת הנודר\u0004 והנידר — יתנו היורשין. ושואלים: \u0003מאי ניהו\u0004 \u0005[מה הוא,\u0006 באיזה מקרה מדובר\u0005]\u0006 — \u0003שעמד בדין,\u0004 כפי שהעמדנו את תחילת המשנה, שהאומר \"ערכי עלי ומת\" — יתנו היורשים, מפני שההעמדה בדין מטילה שעבוד על נכסיו.","ואולם אם כן, \u0003היינו הך\u0004 \u0005[הרי הוא אותו דבר],\u0006 ולמה הוצרך התנא לחזור על דבריו? ומשיבים: \u0003סיפא איצטריך ליה\u0004 \u0005[סופה\u0006 של ההלכה הזו \u0005הוצרך לו],\u0006 ששנינו כי האומר: \u0003\"דמיו של פלוני עליו\u0004 (עלי)\"\u0003ומת הנודר\u0004 — \u0003יתנו היורשים.\u0004"],["\u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 למרות שהנודר עמד בדין וחייבוהו, מכל מקום \u0003כיון\u0004 ש\u0003לא אמדוהו\u0004 את הנידר — \u0003לא אישתעבוד נכסי\u0004 \u0005[לא השתעבדו הנכסים לנדר],\u0006 ואין היורשים חייבים לשלם, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 כי \u0003כיון\u0004 ש\u0003עמד\u0004 הנודר \u0003בדין אישתעבודי אישתעבוד נכסי\u0004 \u0005[השתעבדו\u0006 כבר \u0005הנכסים]\u0006 בחייו, \u0003ואומדנא גלויי מילתא בעלמא הוא\u0004 \u0005[והאומדן\u0006 של הנידר \u0005גילוי דברים בלבד הוא],\u0006 והוא יכול להיעשות אחר מותו.","האומר: \u0003\"שור זה עולה\", ו\u0004כן האומר: \u0003\"בית זה קרבן\", ומת השור,\u0004 או \u0003נפל הבית\u0004 — \u0003פטור מלשלם.\u0004 אבל האומר: \u0003\"שור זה עלי עולה\", ו\u0004כן האומר \u0003\"בית זה עלי קרבן\",\u0004 אם \u0003מת השור\u0004 או \u0003נפל הבית\u0004 — \u0003חייב לשלם\u0004 את דמיו.","על הדין השני במשנה \"שור זה עלי עולה\" וכו' — חייב לשלם, \u0003אמר ר' חייא בר רב: לא שנו\u0004 שחייב לשלם \u0003אלא\u0004 כש\u0003אמר: \"דמי שור זה עלי עולה\",\u0004 שנתחייב לשלם את מחירו, \u0003אבל\u0004 אם \u0003אמר:\u0004 \u0003\"שור זה עלי עולה\", כיון\u0004 ש\u0003אמר:\u0004 \"שור \u0003זה\" ומת\u0004 השור — \u0003אינו חייב באחריותו,\u0004 שהרי לא התחייב אלא לשור זה. ומה שאמר \"עלי\" לא היתה כוונתו לקבל על עצמו אחריות, אלא \u0003עלי להביאו\u0004 ולהקריבו \u0003קאמר\u0004 \u0005[הוא אומר],\u0006 ואם אינו יכול להקריבו פטור לגמרי.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: אמר \u0003\"שור זה עולה\"\u0004 — \u0003השור\u0004 שייך ל\u0003הקדש ומועלין בו,\u0004 וכן אם \u0003מת או נגנב\u0004 השור — \u0003אינו חייב באחריותו.\u0004 אבל אמר: \u0003\"שור זה עלי עולה\"\u0004 — אמנם \u0003השור הקדש ומועלין בו,\u0004 ואולם הואיל ואמר \"עלי\", אם \u0003מת או נגנב\u0004 — \u0003חייב באחריותו.\u0004 ודין זה נאמר בברייתא למרות שלא אמר \"דמי\"!","ודוחים: \u0003מי אלימא ממתניתין\u0004 \u0005[האם חזקה\u0006 הברייתא \u0005יותר ממשנתנו]\u0006 \u0003דאוקימנא דקאמר\u0004 \u0005[שהעמדנו אותה שהוא אומר]\u0006 \u0003\"דמי\"? הכא נמי דקאמר\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005שאומר]\u0006 \u0003\"דמי\u0004 שור זה עלי עולה\".","ומקשים: \u0003והא מדסיפא דקאמר\u0004 \u0005[והרי ממה שבסוף\u0006 ברייתא זו מדובר \u0005שאומר]\u0006 \u0003\"דמי\",\u0004 משמע שב\u0003רישא דלא קאמר\u0004 \u0005[\u0006שב\u0005תחילה\u0006 מדובר \u0005שלא אומר]\u0006 \u0003\"דמי\"! דקתני סיפא\u0004 \u0005[ש\u0006כך \u0005הוא שונה\u0006 ב\u0005סופה]\u0006 של הברייתא: אמר \u0003\"דמי שור\u0004 זה עלי \u0003עולה\"\u0004 — \u0003השור חולין ואין מועלין בו, מת או נגנב\u0004 — \u0003אינו חייב באחריותו, אבל\u0004 אם מכרו וקיבל דמים — \u0003חייב באחריות דמיו,\u0004 מפני שעל דמיו התחייב!","ומשיבים: \u0003רישא וסיפא דקאמר\u0004 \u0005[בתחילה ובסוף\u0006 של הברייתא מדובר כ\u0005שאומר]\u0006 \u0003\"דמי\",\u0004 ואולם מדובר באופנים שונים: \u0003רישא דאמר\u0004 \u0005[בתחילת\u0006 הברייתא מדובר כ\u0005שאומר]:\u0006 \u0003\"יקדיש\u0004 (יקדש) \u0003השור\u0004 עלי \u0003לדמיו\",\u0004 וניסוח זה משמעו שגם השור עצמו קדוש, וגם יהיה אחראי על דמיו. \u0003וסיפא דקאמר\u0004 \u0005[ובסוף\u0006 הברייתא מדובר כ\u0005שהוא אומר]\u0006 \"שור זה \u0003לכשיבאו דמיו\u0004 (אחר המכירה) \u0003יקדשו\u0004 לעולה\".","ומקשים: כיצד להעמיד את סוף הברייתא באופן זה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין אדם מקדיש דבר שלא בא לעולם,\u0004 ואיך יקדשו מעות המכירה שטרם קיבל! \u0003אמר רב יהודה אמר רב: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: אדם מקדיש דבר שלא בא לעולם.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 דבר זה בלשון אחרת, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רמי בר חמא לרב חסדא: כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 ברייתא זו, \u0003כ\u0004דעת \u0003ר' מאיר,\u0004 ש\u0003אמר: אדם מקדיש דבר שלא בא לעולם? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואלא כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]?\u0006 ודאי שהיא כר' מאיר!","\u0003ואיכא דמתני לה אהא\u0004 \u0005[ויש ששונים\u0006 סוגיה \u0005זו על זו],\u0006 ששנינו: \u0003המשכיר בית לחברו ונתנגע\u0004 הבית בצרעת, \u0003אף על פי שחלטו כהן,\u0004 שקבע שהוא טמא, וצריך לנתוץ את הבית — כל זמן שהבית קיים \u0003אומר לו\u0004 בעל הבית: \u0003\"הרי שלך לפניך\",\u0004 ואולם אם \u0003נתצו\u0004 הכהן כפי הדין — \u0003חייב\u0004 בעל הבית \u0003להעמיד לו\u0004 (לשוכר) \u0003בית\u0004 חדש,"],["\u0003הקדישו הדר בו\u0004 (השוכר) — \u0003מעלה שכר\u0004 דירה \u0003להקדש.\u0004 ותמהים: \u0003הקדישו הדר בו?! היכי מצי מקדיש לה\u0004 \u0005[איך יכול\u0006 השוכר \u0005להקדיש אותו]?\u0006 והרי \u0003\"איש כי יקדיש ביתו קדש\"\u0004 (ויקרא כז, יד) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ולמדים משם: \u0003מה ביתו\u0004 הוא \u0003ברשותו\u0004 (שלו), \u0003אף כל\u0004 מה שמקדיש צריך שיהיה \u0003ברשותו,\u0004 ומכיוון שהבית אינו של השוכר אינו יכול להקדישו! ומשיבים: אין כוונת התנא למקרה שהשוכר הקדישו, אלא \u0003הכי קאמר\u0004 \u0005[כך אומר\u0006 התנא\u0005]:\u0006 אם \u0003הקדישו\u0004 ה\u0003משכיר\u0004 — השוכר \u0003הדר בו מעלה שכר להקדש.\u0004","ושואלים: אם \u0003הקדישו\u0004 ה\u0003משכיר, היכי דייר ביה\u0004 \u0005[איך\u0006 השוכר ממשיך \u0005לדור בו]?\u0006 והרי \u0003ב\u0004איסור \u0003מעילה\u0004 מן ההקדש \u0003קאי\u0004 \u0005[הוא עומד],\u0006 שהוא דר בבית של הקדש! \u0003ותו\u0004 \u0005[ועוד],\u0006 האם \u0003מעלה שכר להקדש?\u0004 והלא \u0003כיון דמעל ביה\u0004 \u0005[שמועל בו]\u0006 \u0003נפיק ליה\u0004 \u0005[יוצא לו]\u0006 ה\u0003שכר\u0004 מיד \u0003לחולין!\u0004","ומשיבים, מדובר כש\u0003אמר\u0004 המשכיר: \u0003לכשיבא שכרו\u0004 של בית זה לידי \u0003יקדש.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין אדם מקדיש דבר שלא בא לעולם,\u0004 וכיצד הוא מקדיש את המעות שיבואו לידו בעתיד!","\u0003אמר רב יהודה אמר רב: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: אדם מקדיש דבר שלא בא לעולם. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי, ואמרי לה\u0004 \u0005[ויש שאומרים]\u0006 שאמר זאת \u0003רב מרי בר חמא לרב חסדא: כמאן\u0004 \u0005[כמי]\u0006 אתה מפרש דבר זה? \u0003כר' מאיר,\u0004 ש\u0003אמר: אדם מקדיש דבר שלא בא לעולם? אמר ליה\u0004 \u0005[לו]\u0006 הנשאל: \u0003ואלא כמאן\u0004 \u0005[כמי]?\u0006 ודאי כשיטתו.","\u0003חייבי ערכין\u0004 — \u0003ממשכנין אותן,\u0004 כלומר, נוטלים מהם את חפציהם לצורך פרעון החוב להקדש, \u0003חייבי חטאות ואשמות\u0004 — \u0003אין ממשכנין אותן,\u0004 שכיון שהם באים לכפרה אין אדם משתהה בהבאתם. אבל \u0003חייבי עולות ושלמים,\u0004 מי שנדרו קרבנות אלו — \u0003ממשכנין אותן,\u0004 מפני שאינם חובה, ואנשים משתהים בהבאתם.","ו\u0003אף על פי שאין מתכפר לו עד שיתרצה\u0004 להקריב, \u0003שנאמר:\u0004 \"יקריב אותו \u0003לרצנו\"\u0004 (ויקרא א, ג), בכל זאת \u0003כופין אותו עד שיאמר: \"רוצה אני\". וכן אתה אומר בגיטי נשים,\u0004 כל מי שחייבוהו חכמים לגרש את אשתו, אף על פי שצריך את רצונו — \u0003כופין אותו עד שיאמר \"רוצה אני\".\u0004","\u0003אמר רב פפא: פעמים ש\u0004גם \u0003חייבי חטאות ממשכנין אותן,\u0004 ופעמים שגם \u0003חייבי עולות אין ממשכנין אותן.\u0004","\u0003חייבי חטאות ממשכנין אותן\u0004 — בחטאת נזיר, ש\u0003כיון דאמר מר\u0004 \u0005[שאמר החכם\u0006 במשנה\u0005]\u0006 ש\u0003אם גילח\u0004 הנזיר \u0003על אחד משלשתן,\u0004 אם נשחט אחד משלושה הקרבנות שהוא צריך להביא (חטאת, עולה, ושלמים) — \u0003יצא\u0004 ידי מצות תגלחתו, \u0003ואם נזרק עליו\u0004 (עבורו) \u0003אחד מן הדמים\u0004 של הקרבנות — \u0003הותר הנזיר לשתות יין וליטמא למתים,\u0004 אם כן יש לחשוש שנזיר שהקריב כבר עולה או שלמים \u0003פשע\u0004 \u0005[יתרשל]\u0006 \u0003בה\u0004 בחטאת, \u0003ולא מייתי\u0004 \u0005[ולא יביא\u0006 אותה\u0005],\u0006 ולכן במקרה זה ממשכנים אותו על חטאתו.","\u0003חייבי עולות\u0004 פעמים ש\u0003אין ממשכנין אותן\u0004 — \u0003בעולת יולדת,\u0004 מפני שהקרבת העולה מעכבת את הקרבת החטאת, שהיא מתירה את היולדת לאכול בקדשים, ואין חשש שתשתהה בעולה זו.","ומקשים: \u0003מאי ניהו\u0004 \u0005[מה הוא\u0006 הענין\u0005],\u0006 מפני מה אתה סבור שעולת היולדת מעכבת את הקרבת החטאת, \u0003דאקדמיה קרא\u0004 \u0005[\u0006מפני \u0005שהקדים אותו המקרא],\u0006 שנאמר: \"ובמלאת ימי טהרה לבן או לבת תביא כבש בן שנתו לעולה ובן יונה או תור לחטאת\" (ויקרא יב, ו)? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא:\u0004 רק \u0003למקראה\u0004 תחילה \u0003הקדימה הכתוב\u0004 ולא להקרבתה, ואם כך יש חשש שתקריב תחילה את החטאת ותהא מותרת בקדשים, ועלולה להשהות את עולתה!","\u0003אלא\u0004 מדובר \u0003בעולת מצורע, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל בנו של ר' יהודה בן ברוקה אומר: כשם שחטאתו ואשמו עיכבתו\u0004 למצורע מלהיטהר לגמרי, \u0003כך עולתו עיכבתו,\u0004 ולכן אין צריך למשכן אותו עליה, מפני שאינו משתהה בהבאתה.","שנינו במשנה: \u0003ואף על פי שאין מתכפר לו עד שיתרצה,\u0004 שנאמר: \"לרצונו\", כופין אותו עד שיאמר: \"רוצה אני\". וכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בתורה ביחס לקרבן עולה: \u0003\"יקריב אותו\"\u0004 (ויקרא א, ג) — \u0003מלמד שכופין אותו\u0004 לכך, \u0003יכול\u0004 שיביא את הקרבן \u0003בעל כרחו? תלמוד לומר: \"לרצנו\", הא\u0004 \u0005[\u0006ו\u0005הרי]\u0006 \u0003כיצד\u0004 אפשר לקיים יחדיו כפייה ורצון — \u0003כופין אותו עד שיאמר \"רוצה אני\".\u0004","ובענין זה \u0003אמר שמואל: עולה צריכה דעת\u0004 (רצון והסכמה) של המתכפר, \u0003שנאמר: \"לרצנו\".\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בדבריו? הלא \u0003תנינא\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אף על פי שאין מתכפר לו עד שיתרצה, שנאמר: \"לרצנו\"!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 זו שאמר שמואל אלא במקרה \u0003דפריש ליה חבריה\u0004 \u0005[שהפריש לו חבירו\u0006 עולה עבורו\u0005],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי בעינן\u0004 \u0005[כאשר אנו צריכים]\u0006 את \u0003דעת\u0004 המתכפר — הרי זה כשהקרבן הוא \u0003מדידיה\u0004 \u0005[משלו],\u0006 וכגון שבית הדין ממשכנים נכסיו לשם כך, \u0003אבל\u0004 כשהקרבן \u0003מדחבריה\u0004 \u0005[משל חבירו]\u0006 — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם כשהפריש חבירו קרבן עבורו — צריך את דעת המתכפר, ומדוע? \u0003זימנין דלא ניחא ליה דליכפר במידי דלא דידיה\u0004 \u0005[פעמים שלא נוח לו שיתכפר בדבר שאינו שלו],\u0006 ולפיכך אינו מתכפר.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: האומר \u0003\"חטאתו ואשמו של פלוני עלי\",\u0004"],["אם נעשה הדבר \u0003לדעת\u0004 החייב — \u0003יצא\u0004 החייב ידי חובתו, ואם נעשה \u0003שלא לדעת\u0004 החייב — \u0003לא יצא\u0004 ידי חובתו, ואילו האומר:","\u0003\"עולתו ושלמיו\u0004 \u0003של פלוני עלי\"\u0004 — \u0003בין לדעת בין שלא לדעת יצא,\u0004 בניגוד לדברי שמואל שאמר שעולה צריכה דעת!","ומשיבים, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך שמואל: כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 שיצא ידי חובת עולתו בלא דעת — מדובר \u0003בשעת כפרה\u0004 (הקרבה), ומטעם \u0003דאירצי\u0004 \u0005[ש\u0006כבר \u0005התרצה]\u0006 \u0003בשעת\u0004 ה\u0003הפרשה\u0004 של הקרבן, \u0003כי קאמינא אנא\u0004 \u0005[כאשר אומר אני]\u0006 שדעת החייב מעכבת, מדובר \u0003בשעת הפרשה.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה\u0006 דעת שמואל\u0005]\u0006 על דעת \u0003עולא,\u0004 ש\u0003אמר עולא: לא חילקו בין חטאת\u0004 (ואשם) \u0003ל\u0004בין \u0003עולה\u0004 (ושלמים), \u0003אלא שחטאת צריכה דעת\u0004 החייב \u0003בשעת הפרשה\u0004 על ידי אחרים, \u0003ועולה אין צריכה דעת בשעת הפרשה, אבל בשעת כפרה\u0004 — \u0003אידי ואידי\u0004 \u0005[זה וזה],\u0006 בין חטאת ובין עולה, אם הקריב \u0003לדעת\u0004 החייב — \u0003יצא\u0004 החייב ידי חובתו, \u0003שלא לדעת\u0004 — \u0003לא יצא.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שמואל ועל עולא ממה ששנינו בברייתא: האומר \u0003\"חטאתו ואשמו עולתו ושלמיו של פלוני עלי\",\u0004 אם היה הדבר \u0003לדעת\u0004 החייב — \u0003יצא\u0004 החייב ידי חובתו, ואם \u0003שלא לדעת\u0004 — \u0003לא יצא.\u0004 לשמואל קשה — שהרי הוא סבור שעולה אינה צריכה דעת בשעת כפרה, ולעולא קשה — שהרי הוא סבור שעולה אינה צריכה דעת בשעת הפרשה!","ומשיבים: \u0003שמואל מוקי לה\u0004 \u0005[מעמיד אותה],\u0006 את הברייתא שמצריכה דעת, \u0003בשעת הפרשה,\u0004 ואילו \u0003עולא מוקי לה\u0004 \u0005[מעמיד אותה]\u0006 \u0003בשעת כפרה. אמר רב פפא\u0004 בסיכום הדעות שהובאו בסוגיה זו: \u0003מתנייתא אהדדי לא קשיין\u0004 \u0005[הברייתות זו על זו אינן קשות],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 מדברת \u0003בשעת כפרה, הא\u0004 \u0005[זו]\u0006 — \u0003בשעת הפרשה,\u0004","\u0003ואמוראי נמי לא קשיא\u0004 \u0005[ועל דברי האמוראים גם כן לא קשה\u0006 מהברייתות\u0005]:\u0006 \u0003שמואל מוקי קמייתא\u0004 \u0005[מעמיד את\u0006 הברייתא \u0005הראשונה],\u0006 שאינה מצריכה דעת לעולה ושלמים — \u0003בשעת כפרה,\u0004 ואילו \u0003בתרייתא\u0004 \u0005[האחרונה],\u0006 המצריכה דעת גם בהם — \u0003בשעת הפרשה,\u0004 ואילו \u0003עולא מוקי איפכא\u0004 \u0005[מעמיד\u0006 את הברייתות \u0005להיפך],\u0006 את הראשונה שאינה מצריכה דעת לעולה ושלמים — בשעת הפרשה, ואילו את האחרונה, המצריכה דעת גם בהם — בשעת כפרה. אבל \u0003אמוראי\u0004 \u0005[\u0006ה\u0005אמוראים],\u0006 שמואל ועולא עצמם, \u0003ודאי פליגי\u0004 \u0005[חלוקים]\u0006 זה על זה. ותמהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שכך הם הדברים, ומדוע הוצרך לאומרם?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003בשעת הפרשה דקאמר\u0004 \u0005[שאומר]\u0006 \u0003שמואל\u0004 — שצריך את דעת החייב לא רק בשעת כפרה, אלא \u0003אף בשעת הפרשה. ואף על גב דהך קמייתא תיובתיה\u0004 \u0005[ואף על פי שזו,\u0006 הברייתא \u0005הראשונה קשה לו],\u0006 שהרי נאמר בה שעולה ושלמים אינם צריכים דעת, אינו חש לכך, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב פפא כי הברייתות אינן קשות לשמואל ולא לעולא, ומכאן אתה למד שלדעת שמואל, עולה ושלמים צריכים דעת רק בשעת הפרשה ולא בשעת כפרה.","שנינו במשנה: \u0003וכן\u0004 אתה אומר \u0003בגיטי נשים\u0004 כי מי שחייבוהו חכמים לגרש את אשתו, הרי אף שהגט צריך להינתן מרצונו — \u0003כופין\u0004 אותו עד שיאמר \"רוצה אני\". ובענין זה מביאים מה ש\u0003אמר רב ששת: האי מאן דמסר מודעא אגיטא\u0004 \u0005[מי שמוסר מודעה על הגט],\u0006 שמודיע מראש שהגט שיתן לאשתו נעשה מתוך כפיה, ולא ברצונו — \u0003מודעיה מודעא\u0004 \u0005[מודעתו מודעה],\u0006 כלומר, בעלת תוקף, ומתוך כך בטל הגט. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא!","ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו אלא במקרה \u0003דעשאוה ואירצי\u0004 \u0005[שכפוהו ו\u0006אחר כך \u0005התרצה],\u0006 ונתן את הגט, בלא לחזור בו בפירוש מן המודעה שמסר; \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שעל ידי נתינת הגט \u0003בטולי בטליה\u0004 \u0005[ביטל\u0006 את המודעה\u0005],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב ששת, שהמודעה עומדת בעינה, והגט בטל. ש\u0003אם כן,\u0004 שנתבטלה המודעה — \u0003ליתני\u0004 \u0005[שישנה\u0006 במשנתנו\u0005]:\u0006 כופין אותו \u0003עד שיתן\u0004 מרצונו, \u0003מאי\u0004 \u0005[מהו]\u0006 שנאמר: \u0003עד שיאמר\u0004 \"רוצה אני\" — \u0003עד דמבטל ליה למודעיה\u0004 \u0005[עד שיבטל את המודעה שלו\u0006 בפירוש\u0005].\u0006","","","\u0003שום היתומים,\u0004 כלומר, כאשר בית הדין עושה שומא (אומדן) של נכסי יתומים קטנים שירשו מאביהם, ומציע אותם למכירה על מנת לפרוע חוב אביהם — מכריזים על הדבר \u0003שלשים יום\u0004 על מנת לקבל את המחיר הטוב ביותר עבורם, \u0003ושום ההקדש,\u0004 כשמוכרים נכסי הקדש — \u0003ששים יום, ומכריזין\u0004 זאת \u0003בבקר ובערב.\u0004","שואלים: \u0003מאי שנא\u0004 \u0005[מה שונה],\u0006 מדוע מכריזים \u0003בבקר ובערב? אמר רב יהודה אמר רב: בשעת הוצאת פועלים\u0004 לעבודתם בשדה, \u0003ובשעת הכנסת פועלים\u0004 בחזרה לעיר. ומסבירים: \u0003בשעת הוצאת פועלים\u0004 — \u0003דאיכא דניחא למיזבן\u0004 \u0005[ש\u0006אם \u0005יש\u0006 אדם \u0005שנוח\u0006 לו, שרוצה \u0005לקנות],\u0006 \u0003אמר להו\u0004 \u0005[אומר להם]\u0006 \u0003לפועלים:\u0004 \u0003איזילו סיירו לה ניהלי\u0004 \u0005[לכו\u0006 לשדה ו\u0005בדקו אותה בשבילי],\u0006 ומכריזים גם \u0003בשעת הכנסת פועלים\u0004 — \u0003דנידכר דאמר להו\u0004 \u0005[\u0006כדי \u0005שייזכר שאמר להם],\u0006 \u0003ניזיל נישיילינהו\u0004 \u0005[\u0006ו\u0005ילך\u0006 ו\u0005ישאל אותם]\u0006 מה דעתם על השדה.","ומביאים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003שום היתומים שלשים יום, ושום ההקדש ששים יום. ומכריזין בבקר ובערב, בשעת הוצאת פועלים ובשעת הכנסת פועלים.\u0004","וכך \u0003אומר\u0004 המכריז: \u0003שדה פלוני\u0004 המזוהה \u0003בסימניה ובמצריה\u0004 (גבולותיה) \u0003כך היא יפה,\u0004 מניבה כך וכך תבואה בשנה, \u0003וכך היא שומא\u0004 בכסף, \u0003כל הרוצה ליקח\u0004 (לקנות) \u0003יבא ויקח,\u0004 ומכריז שהיא נמכרת \u0003על מנת ליתן\u0004 את התמורה \u0003לאשה בכתובתה,\u0004 או על מנת ליתן \u0003לבעל חוב בחובו.\u0004","ושואלים: \u0003למה לי למימר\u0004 \u0005[לומר]\u0006 \u0003\"על מנת ליתן לאשה כתובתה ולבעל חוב חובו\"?\u0004 ומשיבים: \u0003דאיכא דניחא ליה\u0004 \u0005[שיש\u0006 קונה \u0005שנוח לו]\u0006 \u0003בבעל חוב, דמיקל בזוזי\u0004 \u0005[שהוא מקל ב\u0006נטילת \u0005הזוזים],\u0006 ונוטל אף פגומים, \u0003ואיכא דניחא ליה\u0004 \u0005[ויש שנוח לו]\u0006 \u0003באשה, דשקלה על יד על יד\u0004 \u0005[שמוכנה לקבל\u0006 את דמי המכירה \u0005מעט מעט,\u0006 בתשלומים\u0005].\u0006"],["בענין ששנינו במשנתנו: שום היתומים שלושים יום, ושום ההקדש שישים יום, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 מחלוקת בברייתא: \u0003שום היתומים,\u0004 הצעת נכסי יתומים למכירה לפי הערכת בית הדין — נעשה במשך \u0003שלשים יום, ושום ההקדש,\u0004 הנעשה לצורך מכירת נכסי הקדש — \u0003ששים יום, דברי ר' מאיר. ר' יהודה אומר: שום היתומים ששים יום, ושום ההקדש תשעים יום. וחכמים אומרים: אחד זה ואחד זה ששים יום. אמר רב חסדא אמר אבימי, הלכה: שום היתומים ששים יום.\u0004","מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003ר' חייא בר אבין וקאמר להא שמעתא\u0004 \u0005[ואומר את ההלכה הזו]\u0006 של רב חסדא בשם אבימי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לר' חייא בר אבין: ששים קאמרת\u0004 \u0005[אומר אתה],\u0006 \u0003או שלשים קאמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ששים.\u0004 שאל אותו רב נחמן: של \u0003יתומים או\u0004 של \u0003הקדש? אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: של \u0003יתומים.\u0004","שאל אותו רב נחמן: האם פוסק אתה \u0003כר' מאיר או כר' יהודה? אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003כר' מאיר.\u0004 הקשה עליו רב נחמן: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' מאיר שלשים\u0004 יום \u0003קאמר\u0004 \u0005[הוא אומר],\u0006 ולא שישים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב חסדא, מאבימי קולפי טאבי בלעי עלה דהא שמעתא\u0004 \u0005[\u0006\u0005אלות הרבה קיבלתי על השמועה הזו],\u0006 כלומר, הקפיד עלי וגער בי, כאשר אמר לי ששום היתומים שישים יום, וכדעת ר' מאיר, והקשיתי עליו מן הברייתא, וכך הסביר לי: \u0003בא להכריז\u0004 ימים \u0003רצופים\u0004 — צריך להכריז במשך \u0003שלשים\u0004 יום, ואם מכריז רק","\u0003בשני ובחמישי,\u0004 שהם ימי השוק, ובית הדין יושב בהם, ואנשי הכפרים נכנסים לעיר — צריך להכריז במשך תקופה של \u0003ששים\u0004 יום. \u0003ואף על גב דכי חשיב להו מר ליומי הכרזה לא הוו אלא תמניסר יומי\u0004 \u0005[ואף על פי שכאשר יחשב אדוני את ימי ההכרזה\u0006 עצמם \u0005לא יהיו אלא שמונה עשר ימים],\u0006 \u0003כיון דמשכא מילתא שמעי אינשי\u0004 \u0005[שנמשך הדבר\u0006 שישים יום \u0005שומעים האנשים].\u0006","בענין שום היתומים ששנינו במשנתנו, \u0003אמר רב יהודה אמר רב אסי: אין\u0004 בית הדין \u0003נזקקין לנכסי יתומים\u0004 קטנים, לדון בתביעה על חוב של אביהם, ולמכור מנכסיו, \u0003אלא אם כן היתה\u0004 על החוב \u0003רבית\u0004 ש\u0003אוכלת בהן,\u0004 וכל זמן שאין החוב נפרע הריהו הולך וגדל, אבל בכל מקרה אחר — ממתינים עד שיגדלו. \u0003ור' יוחנן אומר:\u0004 נזקקים לנכסי היתומים \u0003או ל\u0004צורך גביית \u0003שטר שיש בו רבית, או\u0004 כדי \u0003ל\u0004שלם \u0003כתובת אשה\u0004 לאשת אביהם, וטעם הדבר, \u0003משום\u0004 שכל עוד לא גבתה כתובתה חייבים היתומים בתשלום \u0003מזוני\u0004 \u0005[מזונות]\u0006 מנכסי הירושה, וכדאי להם שתגבה מיד את כתובתה.","ושואלים: \u0003ורב אסי מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 גם \u0003ל\u0004צורך \u0003כתובת אשה?\u0004 ומשיבים: \u0003דהא תקינו ליה רבנן\u0004 \u0005[שהרי תיקנו לו חכמים]\u0006 לבעל, שכנגד המזונות שהיא מקבלת מן היתומים — תיתן להם את מה שהיא מרוויחה מ\u0003מעשה ידיה,\u0004 ונמצא שלא יפסידו מעיכוב התשלום. ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוחנן\u0005],\u0006 מה הוא משיב על כך? ומשיבים: \u0003זימנין דלא ספקה\u0004 \u0005[פעמים שאינה מספקת]\u0006 במעשה ידיה את סכום המזונות שהיא מקבלת מהם, וכדאי להם שתגבה כתובתה מיד.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שום היתומים שלשים יום, ושום ההקדש ששים יום, ומכריזין בבקר ובערב.\u0004 ויש לשאול: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]\u0006 ששום היתומים שלושים יום? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בבעל חוב גוי, מי ציית\u0004 \u0005[האם\u0006 הוא \u0005מציית]\u0006 לבית דין של ישראל להמתין שלושים יום? \u0003אלא פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שמדובר \u0003בבעל חוב ישראל,\u0004 ואולם \u0003אי דקאכיל ריביתא מי שבקינן ליה\u0004 \u0005[אם\u0006 מדובר \u0005שהוא אוכל,\u0006 לוקח \u0005ריבית, האם אנו,\u0006 בית הדין של ישראל, \u0005מניחים לו]\u0006 ליטול ריבית? \u0003ואלא\u0004 צריך לומר שמדובר בבעל חוב \u0003דלא קאכיל ריביתא\u0004 \u0005[שאינו אוכל ריבית],\u0006 \u0003וקתני\u0004 \u0005[ושונה]\u0006 התנא ש\u0003נזקקין\u0004 לנכסי היתומים במקרה כזה, שלא כדברי רב אסי ור' יוחנן!","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן\u0004 אין מכאן קושיה, מפני שהוא \u0003מוקי לה\u0004 \u0005[מעמיד אותה]\u0006 את משנתנו, \u0003בכתובת אשה,\u0004 ומשום מזונותיה, ולא בבעל חוב. \u0003אלא ל\u0004שיטת \u0003רב אסי,\u0004 הסבור שאין נזקקים לצורך כתובת אשה, \u0003קשיא\u0004 \u0005[קשה],\u0006 במה יעמיד את משנתנו? ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003רב אסי: ול\u0004שיטת \u0003ר' יוחנן מי ניחא\u0004 \u0005[האם נוחה\u0006 משנתנו\u0005],\u0006 המצריכה שלושים ימי הכרזה קודם המכירה? \u0003מי שבקינן מזוני דודאי קא מפסדא\u0004 \u0005[האם אנו מניחים\u0006 את ה\u0005מזונות שוודאי היא מפסידה,\u0006 נוטלת\u0005]\u0006 מנכסי הירושה במשך זמן זה, \u0003ונקטינן הכרזה דלא ידעינן אי מרווחינן אי לא מרווחינן\u0004 \u0005[ומחזיקים,\u0006 מעדיפים במקומה \u0005הכרזה, שאין אנו יודעים אם אנו מרויחים\u0006 על ידה \u0005או אין אנו מרויחים]?\u0006 שמא לא יהיה אדם שיקנה במחיר שהציע בית הדין!","ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 כאן מדובר \u0003ב\u0004אלמנה ה\u0003תובעת כתובתה בבית דין,\u0004 ו\u0003כ\u0004דברי \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל,\u0004 ש\u0003אמר רב יהודה אמר שמואל:\u0004 אלמנה \u0003התובעת כתובתה בבית דין,\u0004 מאותה שעה כבר \u0003אין לה מזונות\u0004 מנכסי בעלה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאין לה מזונות מנכסי היתומים, מעתה \u0003איזדקוקי לא מיזדקקינן לה\u0004 \u0005[שוב לא נזדקק לה]\u0006 להגבות את כתובתה מנכסיהם עד שיגדלו, שהרי אינם מפסידים מעיכוב הגבייה! ודוחים: אין הדבר כך, \u0003אלא כיון דאיזדקקינן לה מעיקרא\u0004 \u0005[שמזדקקים לה מתחילה]\u0006 לדון בתביעתה לכתובה, \u0003מיזדקקין\u0004 \u0005[נזקקים]\u0006 \u0003לה\u0004 גם \u0003לבסוף\u0004 לגבותה מהם, למרות שעכשיו כבר אין ליתומים הפסד אם לא תגבה.","וחוזרים לשאול: \u0003מכל מקום, לרב אסי,\u0004 הסבור כי אין נזקקים לנכסי יתומים לצורך גביית כתובה, אלא לשם גביית חוב שיש עליו ריבית, \u0003קשיא\u0004 \u0005[קשה],\u0006 במה יעמיד את משנתנו? אם בבעל חוב גוי — אינו מציית להמתין שלושים יום, ואם בישראל — הרי אינו יכול ליטול ריבית! ומשיבים: \u0003לעולם\u0004 מדובר במשנתנו \u0003בבעל חוב גוי, שקיבל עליו לדון בדיני ישראל,\u0004 ולפיכך הוא מסכים להמתין שלושים יום.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שקיבל עליו לדון בדיני ישראל, \u0003רבית נמי לא לישקול\u0004 \u0005[גם כן לא יקח]!\u0006 ומשיבים: מדובר \u0003שקיבל עליו לזו,\u0004 להמתין שלושים יום, \u0003ולא קיבל עליו לזו,\u0004 שלא ליטול ריבית.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה נוספת ממה ששנינו: \u0003אין נפרעין מנכסי יתומים אלא מן הזיבורית\u0004 (הקרקע הגרועה) שבנכסי אביהם. ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בבעל חוב גוי\u0004 — \u0003מי צאית\u0004 \u0005[האם הוא מציית]\u0006 לקבל דוקא מהזיבורית? \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, שמדובר \u0003בבעל חוב ישראל.\u0004 ואולם \u0003אי אכיל ריביתא\u0004 \u0005[אם הוא אוכל,\u0006 לוקח \u0005ריבית]\u0006 \u0003מי שבקינן ליה\u0004 \u0005[האם אנו מניחים אותו]\u0006 לגבותה? \u0003אלא\u0004 מדובר בבעל חוב \u0003דלא אכיל ריביתא\u0004 \u0005[שאינו אוכל ריבית],\u0006 \u0003וקתני\u0004 \u0005[והוא שונה]\u0006 ש\u0003נזקקין\u0004 לגבות מהנכסים במקרה כזה, שלא כדברי רב אסי ור' יוחנן!","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לר' יוחנן\u0004 אין להקשות, שכן הוא \u0003מוקי לה\u0004 \u0005[מעמיד אותה]\u0006 \u0003בכתובת אשה. אלא לרב אסי,\u0004 הסבור שאין נזקקים לנכסי יתומים לצורך גביית כתובה, \u0003קשיא\u0004 \u0005[קשה],\u0006 במה יעמיד אותה משנה? ומשיבים, \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]\u0006 \u0003רב אסי: ול\u0004שיטת \u0003ר' יוחנן מי ניחא\u0004 \u0005[האם נוחה\u0006 המשנה\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר בגביית \u0003כתובה, מאי איריא מיתמי\u0004 \u0005[מה שייך,\u0006 מדוע מדובר דוקא בגבייה \u0005מיתומים]?\u0006 \u0003אפילו מיניה דידיה\u0004 \u0005[ממנו עצמו],\u0006 כשגירש אשתו, \u0003נמי\u0004 \u0005[גם כן]\u0006 גובים את חוב הכתובה \u0003בזיבורית!\u0004","ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 מפני שאותה המשנה כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: כתובת אשה\u0004 גובים ממנו \u0003בבינונית, ו\u0004דוקא \u0003מיתמי\u0004 \u0005[מן היתומים]\u0006 גובים \u0003בזיבורית.\u0004","וחוזרים לשאול: \u0003מכל מקום, לרב אסי קשיא\u0004 \u0005[קשה],\u0006 במה יעמיד את המשנה? ומשיבים: \u0003לעולם\u0004 מדובר \u0003בבעל חוב גוי, שקיבל עליו לדון בדיני ישראל,\u0004 ולפיכך מסכים לגבות את חובו מן הזיבורית. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003רבית נמי לא נישקול\u0004 \u0005[גם כן לא יקח]!\u0006 ומשיבים: מדובר \u0003שקיבל\u0004 עליו \u0003לזו,\u0004 לגבות מזבורית, \u0003ולא קיבל עליו לזו,\u0004 שלא ליטול ריבית, ולפיכך נזקקים לנכסי היתומים, כדי שלא תגדל הריבית.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה ממה ששנינו בברייתא: שום היתומים שלושים יום וכו' \u0003על מנת ליתן לאשה כתובתה ולבעל חוב חובו.\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 לגבי מה ששנינו כי מוכרים את נכסיהם על מנת ליתן ל\u0003בעל חוב\u0004 חובו — אין בכך קושי, \u0003בין מר ובין מר כדשנין\u0004 \u0005[בין\u0006 לשיטת \u0005חכם זה ובין\u0006 לשיטת \u0005חכם זה, כמו שתירצנו],\u0006 שמדובר בגוי נוטל ריבית שמסכים להמתין.","\u0003אלא\u0004 מה ששנינו: על מנת ליתן לאשה \u0003כתובתה, בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' יוחנן,\u0004 האומר שנזקקים לנכסי יתומים לצורך גביית כתובה, \u0003ניחא\u0004 \u0005[נוחה\u0006 הברייתא\u0005],\u0006 \u0003אלא ל\u0004שיטת \u0003רב אסי,\u0004 האומר שאין נזקקים לנכסי יתומים לשם גביית כתובה, \u0003קשיא\u0004 \u0005[קשה\u0006 הברייתא\u0005]!\u0006","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשחייב מודה,\u0004 כלומר, כשאבי היתומים הודה קודם מותו שלא פרע את חוב הכתובה. ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן,\u0006 לתירוץ זה\u0005],\u0006 אין צורך להעמיד את שאר המקורות שהקשינו מהם במקרה של בעל חוב גוי, אלא \u0003כולהו נמי\u0004 \u0005[כולם גם כן]\u0006 עוסקים בבעל חוב ישראל, ומדובר \u0003כשחייב מודה\u0004 בשעת מותו שלא פרע, ולכן גובים מנכסי יתומים.","ובפסיקת הלכה למעשה בענין זה מסופר, \u0003מרימר אגבי\u0004 \u0005[הגבה]\u0006 את חוב \u0003כתובתה\u0004 של אשה \u0003גרושה מנכסי דיתמי\u0004 \u0005[מנכסים של יתומים\u0006 קטנים\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לאמימר, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב אסי: אין נזקקין לנכסי יתומין אלא אם כן היתה רבית אוכלת בהן,\u0004 ו\u0003ר' יוחנן אומר: או ל\u0004מקרה זה של \u0003שטר שיש בו רבית, או לכתובת אשה משום מזוני\u0004 \u0005[מזונות\u0006 האלמנה\u0005]!\u0006","\u0003ואפילו ר' יוחנן לא קאמר\u0004 \u0005[אומר]\u0006 שגובים כתובה \u0003אלא באלמנה,\u0004 משום \u0003דקמפסדא מזוני\u0004 \u0005[שהיא מפסידה,\u0006 נוטלת \u0005מזונות]\u0006 מנכסיהם עד שיגדלו ותיטול כתובתה, \u0003אבל גרושה\u0004, שאינה ניזונת מנכסיהם, \u0003לא\u0004 מגבים כתובתה מנכסי יתומים קטנים!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר לרבינא: אין זה קשה, \u0003הא אנן\u0004 \u0005[הרי אנו]\u0006 את ההלכה הזו של \u0003ר' יוחנן,\u0004 שגובים כתובה מנכסי יתומים קטנים, לא מטעם מזונות שהיא נוטלת מנכסי היתומים אנו שונים בשמו, אלא \u0003משום חינא מתנינן לה\u0004 \u0005[משום נשיאת חן אנו שונים אותה],\u0006 כדי שתוכל האשה להינשא שוב, וטעם זה נוגע בין לאלמנה ובין לגרושה.","ועוד בעניינים אלו, \u0003אמר רב נחמן: מרישא לא הוה מיזדקיקנא לנכסי יתמי\u0004 \u0005[מתחילה לא הייתי מזדקק ל\u0006גבות חוב רגיל מ\u0005נכסי יתומים],\u0006 \u0003כיון דשמענא להא\u0004 \u0005[ששמעתי את זו]\u0006 שאמר \u0003רב הונא חברין משמיה\u0004 \u0005[חברנו משמו]\u0006 של \u0003רב\u0004 בענין זה: \u0003יתמי דאכלי דלא דידהו ליזלו בתר שיבקייהו\u0004 \u0005[יתומים שאוכלים,\u0006 נהנים מנכסים \u0005שאינם שלהם, שילכו אחר מורישם\u0006 למיתה\u0005]\u0006 — \u0003מכאן ואילך מיזדקקנא\u0004 \u0005[מכאן והלאה אני מזדקק]\u0006 לגבות מנכסיהם.","ושואלים: \u0003מעיקרא מאי טעמא\u0004 \u0005[מתחילה מה טעם]\u0006 \u0003לא\u0004 היה גובה? מדוע אין נזקקים לנכסי יתומים? \u0003אמר רב פפא:\u0004 משום ש\u0003פריעת בעל חוב\u0004 היא \u0003מצוה\u0004 בלבד, \u0003ויתמי לא בני מיעבד מצוה נינהו\u0004 \u0005[ויתומים\u0006 קטנים \u0005אינם בני עשיית מצוה].\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: אימר\u0004 \u0005[אמור],\u0006 כלומר יש לחשוש שמא \u0003צררי אתפסיה\u0004 \u0005[צרורות\u0006 כסף \u0005התפיסו,\u0006 נתן לבעל חובו\u0005]\u0006 כמשכון סמוך למיתתו, ואין אנו יודעים על כך. ולכן ממתינים עד שיגדלו היתומים ויהיה ביכולתם לברר היטב את מה שהיה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל לדין \u0005ביניהם]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 \u0003ב\u0004מקרה \u0003שחייב מודה\u0004 לפני מותו שהוא עדיין חייב לו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 במקרה ש\u0003שמתוה\u0004 \u0005[נידו אותו\u0006 בית הדין את אביהם, כדי שישלם\u0005]\u0006 \u0003ומת בשמתיה\u0004 \u0005[בנידויו],\u0006 שאין לחשוש שכבר פרע לו את חובו. שאם מטעם שאין היתומים הקטנים מצווים על פריעת החוב — אין גובים, ואם מטעם החשש שמא התפיסו צרורות — גובים, שהרי ודאי שלא נתן לו.","\u0003שלחו מתם\u0004 \u0005[משם]\u0006 מארץ ישראל, שגובים מנכסי יתומים קטנים דוקא במקרה \u0003דשמתוה ומית בשמתיה\u0004 \u0005[שנידו אותו\u0006 את אביהם כדי שישלם \u0005ומת בנידויו].\u0006 \u0003ו\u0004כן \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כ\u0004דעת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 שבכל מקרה שאין חשש שהאב פרע, או התפיסו צרורות — גובים מנכסי היתומים."],["ובענין המחלוקת מדוע אין נזקקים לנכסי יתומים, מביאים ראיה, שכך \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שום היתומים,\u0004 כשמוכרים נכסי יתומים — \u0003שלשים יום, ושום ההקדש ששים יום, ומכריזין בבקר ובערב.\u0004 ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 במשנה זו, שנזקקים לנכסי היתומים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בבעל חוב גוי,\u0004 שאינו מוכן להמתין עד שיגדלו, \u0003מי צאית\u0004 \u0005[האם\u0006 הוא \u0005מציית]\u0006 לבית דין של ישראל להמתין שיכריזו שלושים יום? \u0003אלא פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שמדובר \u0003בבעל חוב ישראל.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 שאין נזקקים לנכסי יתומים מחשש צרורות שהניח אביהם לבעל החוב — \u0003מוקי לה\u0004 \u0005[מעמיד הוא אותה]\u0006 את משנתנו \u0003ב\u0004מקרה \u0003שחייב\u0004 (אבי היתומים) \u0003מודה\u0004 בשעת מיתתו שלא פרע, ולכן אין צורך להמתין שיגדלו. \u0003אלא ל\u0004שיטת \u0003רב פפא,\u0004 שאמר כי הטעם הוא מפני שיתומים קטנים אינם מצווים בפריעת בעל חוב, \u0003קשיא\u0004 \u0005[קשה],\u0006 במה יעמיד את משנתנו?","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]\u0006 \u0003רב פפא, אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 מדובר במכירה לצורך פריעת חוב \u0003כתובה,\u0004 ודוקא שם תיקנו חכמים \u0003משום חינא\u0004 \u0005[חן],\u0006 כדי שיהא לאשה רכוש שתינשא בו. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 מדובר \u0003בבעל חוב גוי שקיבל עליו לדון בדיני ישראל,\u0004 ולפיכך הוא מסכים להמתין שלושים יום של ההכרזה.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003קיבל עליו, לינטר להו עד דגדלי\u0004 \u0005[שיחכה להם עד שיגדלו],\u0006 כנהוג בגביית חוב! ומשיבים: \u0003שקיבל עליו לזו,\u0004 להמתין שלושים יום, \u0003ולא קיבל עליו לזו,\u0004 להמתין עד שיגדלו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו בברייתא: כשמכריזים על נכסי יתומים, מודיעים כי הם נמכרים \u0003על מנת ליתן לאשה כתובתה\u0004 או \u0003לבעל חוב חובו.\u0004 ויש לברר: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בבעל חוב גוי,\u0004 שאינו מוכן להמתין עד שיגדלו — \u0003מי ציית\u0004 \u0005[האם\u0006 הוא \u0005מציית]\u0006 לבית דין של ישראל להמתין שיכריזו שלושים יום? \u0003אלא פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 שמדובר \u0003בבעל חוב ישראל.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 הסבור כי אין נזקקים לנכסי יתומים מחשש צרורות — הריהו \u0003מוקי לה\u0004 \u0005[מעמיד אותה]\u0006 \u0003בשחייב מודה\u0004 בשעת מיתתו שלא פרע את חובו. \u0003אלא ל\u0004דעת \u0003רב פפא,\u0004 הסבור כי טעם הדבר הוא משום שיתומים קטנים אינם מצווים על פריעת החוב, \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 שגובים לאשה את ה\u0003כתובה\u0004 — \u0003משום חינא\u0004 \u0005[חן],\u0006 \u0003אלא\u0004 ל\u0003בעל חוב קשיא\u0004 \u0005[קשה],\u0006 מדוע מגבים לו?","ומשיבים: \u0003לעולם\u0004 מדובר \u0003בבעל חוב גוי, וכגון שקיבל עליו לדון בדיני ישראל,\u0004 ולפיכך הוא מסכים להמתין שלושים יום של ההכרזה. ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003קיבל עליו, לינטר להו עד דגדלי\u0004 \u0005[שיחכה להם עד שיגדלו]!\u0006 ומשיבים: \u0003שקיבל עליו לזו,\u0004 להמתין שלושים יום, \u0003ולא קיבל עליו לזו,\u0004 להמתין עד שיגדלו.","\u0003רבא אמר:\u0004 אין גובים מנכסי יתומים קטנים \u0003משום\u0004 חשש ל\u0003שובר,\u0004 שמא החייב כבר פרע את חובו וכתב לו בעל חובו שובר (מסמך המאשר את הפרעון), ואין היתומים הקטנים יודעים עליו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא: ומי חיישינן\u0004 \u0005[והאם חוששים אנו]\u0006 \u0003לשובר? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנפרעת\u0004 את כתובתה מנכסי בעלה \u0003שלא בפניו,\u0004 וכגון שנסע למדינת הים — \u0003לא תפרע אלא בשבועה,\u0004 שעדיין לא קיבלה כתובתה.","\u0003ואמר רב אחא שר הבירה: מעשה בא לפני ר' יצחק נפחא ל\u0004עיר \u0003אנטוכיא, ואמר: לא שנו\u0004 היתר זה, לגבות שלא בפניו, \u0003אלא\u0004 ל\u0003כתובת אשה משום חינא\u0004 \u0005[חן],\u0006 \u0003אבל בעל חוב\u0004 — \u0003לא\u0004 יכול לגבות חובו שלא בפני הלווה. \u0003ורבה אמר\u0004 בשם \u0003רב נחמן: אפילו בעל חוב נמי\u0004 \u0005[גם כן]\u0006 גובה באופן זה.","\u0003ואי חיישת\u0004 \u0005[ואם אתה חושש]\u0006 \u0003לשובר, התם נמי ניחוש\u0004 \u0005[שם גם כן נחשוש]\u0006 שלחייב הנמצא במדינת הים יש שובר על חוב זה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003התם\u0004 \u0005[שם]\u0006 אין חוששים לדבר \u0003כדאמרינן טעמא\u0004 \u0005[כמו שאמרנו\u0006 את \u0005הטעם]\u0006 — כדי \u0003שלא יהא כל אחד נוטל\u0004 (לווה) \u0003מעותיו של חבירו, והולך ויושב לו במדינת הים\u0004 בידיעה שלא יוכלו לגבות מנכסיו.","\u0003אמר רבא: הלכתא\u0004 \u0005[הלכה היא]:\u0006 \u0003אין נזקקין\u0004 בית הדין \u0003לנכסי יתומין\u0004 קטנים, כדי לפרוע חובות אביהם. \u0003ואם אמר\u0004 אביהם קודם מיתתו: \u0003\"תנו\u0004 לפלוני בחובו\" — \u0003נזקקין\u0004 לנכסיהם. ואולם יש להבחין, אם אמר: \"תנו \u0003שדה זו\u0004 לפלוני בחובו\", או שאמר: \"תנו \u0003מנה זו\u0004 לפלוני\" — \u0003נזקקין\u0004 לגבות מנכסיהם, \u0003ואין\u0004 הדיינים \u0003מעמידין\u0004 ליתומים הקטנים \u0003אפוטרופוס\u0004 לדון עם המלוה. אבל אם אמר: \"תנו \u0003שדה\u0004 לפלוני בחובו\" \u0003סתם,\u0004 ולא הגדיר איזו שדה, או שאמר: \"תנו \u0003מנה\u0004 לפלוני\" \u0003סתם\u0004 — \u0003נזקקין\u0004 לגבות מנכסיהם, \u0003ו\u0004אולם \u0003מעמידין אפוטרופוס,\u0004 שיפעל לטובתם, להשאיר בידם את הקרקעות הטובות.","לעומת זאת \u0003אמרי נהרדעי\u0004 \u0005[אומרים\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003בכולהו\u0004 \u0005[בכל]\u0006 המקרים שהאב אומר \"תנו\" \u0003נזקקין\u0004 בית הדין לנכסי יתומים, \u0003ומעמידין אפוטרופוס\u0004 שיפעל לטובתם, וגם כשאמר \"שדה זו\" או \"מנה זו\", \u0003לבד מ\u0004מקרה ש\u0003נמצאת\u0004 בידם \u0003שדה\u0004 שיש עדים המעידים \u0003שאינה שלו,\u0004 אלא גזולה בידו, מפני \u0003דאחזוקי סהדי בשקרי לא מחזקינן\u0004 \u0005[שלהחזיק את העדים כשקרנים אין אנו מחזיקים].\u0006","\u0003אמר רב אשי: הלכך\u0004 \u0005[על כן],\u0006 בחוב רגיל \u0003אזדקוקי לא מזדקקינן\u0004 \u0005[להזדקק אין אנו מזדקקים]\u0006 לנכסי יתומים קטנים, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רבא: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003אין נזקקין\u0004 לנכסי יתומים. \u0003ואי מזדקקינן\u0004 \u0005[ואם מזדקקים אנו],\u0006 וכגון במקרה שאמר \"תנו\" — \u0003מוקמינן\u0004 \u0005[מעמידים]\u0006 \u0003אפוטרופוס, דאמרי נהרדעי\u0004 \u0005[ש\u0006הרי \u0005אומרים\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003בכולהו\u0004 \u0005[בכולם]\u0006 \u0003נזקקין ומעמידין אפוטרופוס\u0004 ליתומים הקטנים, \u0003לבד\u0004 (חוץ) \u0003מנמצאת שדה שאינה שלו,\u0004 שאין הדיינים מעמידים אז אפוטרופוס, משום \u0003דאחזוקי סהדי בשקרי לא מחזקינן\u0004 \u0005[שלהחזיק\u0006 את ה\u0005עדים כשקרנים אין אנו מחזיקים].\u0006"],["\u0003המקדיש נכסיו והיתה עליו כתובת אשה,\u0004 ונכסי אדם משועבדים לתשלום כתובת אשתו, \u0003ר' אליעזר אומר: כשיגרשנה ידור\u0004 נדר שלא תהיה לו \u0003הנאה\u0004 ממנה, כדי שלא יערימו על ההקדש, ותגבה כתובתה מן ההקדש, ואחר כך יחזירנה. \u0003ר' יהושע אומר: אינו צריך. כיוצא בדבר אמר רבן שמעון בן גמליאל: אף הערב לאשה בכתובתה\u0004 שאם לא יפרע לה בעלה כתובתה תיפרע מן הערב, \u0003והיה בעלה מגרשה\u0004 ואין לו לפורעה — \u0003ידירנה\u0004 בעלה \u0003הנאה\u0004 שלא ייהנה ממנה, \u0003שמא יעשה קינוניא\u0004 (תחבולה משותפת) עם אשתו \u0003על נכסים של זה\u0004 (הערב), שתיטול האשה את נכסיו בכתובתה, \u0003ויחזיר\u0004 הבעל \u0003את אשתו,\u0004 וייהנו ממה שנטלה מהערב.","שנינו במשנה כי המקדיש נכסיו, כשמגרש את אשתו עליו לידור הנאה ממנה — לדעת ר' אליעזר, ולדעת ר' יהושע אינו צריך. ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]\u0006 ר' אליעזר ור' יהושע? ומשיבים: \u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 יש לחשוש ש\u0003אדם עושה קינוניא\u0004 אפילו \u0003על ההקדש,\u0004 ומשום כך הוא מגרש את אשתו, והנדר בא למנוע אפשרות זו, \u0003ור' יהושע סבר\u0004 \u0005[סבור]:\u0006 \u0003אין\u0004 לחשוש ש\u0003אדם עושה קינוניא על ההקדש.\u0004","ושואלים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב הונא: שכיב מרע\u0004 (חולה הנוטה למות) \u0003שהקדיש כל נכסיו, ואמר: \"מנה לפלוני בידי\"\u0004 — \u0003נאמן,\u0004 ויטול פלוני מנה מנכסיו, שכן \u0003חזקה אין\u0004 אדם \u0003עושה קינוניא על הקדש, לימא כתנאי אמרה לשמעתיה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005כ\u0006דבר השנוי במחלוקת \u0005תנאים אמר את הלכתו]?\u0006 שהרי לדעת ר' יהושע אין אדם עושה קינוניא על הקדש!","ודוחים: \u0003לא, עד כאן לא פליגי\u0004 \u0005[לא נחלקו]\u0006 במשנתנו \u0003אלא ב\u0004אדם \u0003בריא,\u0004 האם יש לחשוש שהוא עושה קינוניא על ההקדש, \u0003אבל בשכיב מרע\u0004 — \u0003דברי הכל אין\u0004 לחשוש ש\u0003אדם עושה קינוניא על ההקדש, מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 מפני שלו עצמו אין רווח בדבר, שהרי הוא עומד למות, ו\u0003אין אדם חוטא ולא לו,\u0004 כדי שירויח מכך אדם אחר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003בבריא דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003אין\u0004 \u0003אדם עושה קינוניא על הקדש,\u0004 אלא בוודאי יש לחשוש לכך, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בנדר שהודר ב\u0004פני \u0003רבים קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 וכגון שבית הדין מדירים אותו, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהושע, \u0005סבור]:\u0006 \u0003יש לו הפרה\u0004 (התרה) גם לנדר כזה, ולכן לא יועיל מה שידור הנאה ממנה ואפילו ברבים, שהרי יוכל ללכת לחכם ויתיר את נדרו, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר, \u0005סבור]:\u0006 נדר ברבים \u0003אין לו הפרה,\u0004 ולכן מדירים אותו בפני רבים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 אף \u0003נדר שהודר ברבים יש לו הפרה, והכא\u0004 \u0005[וכאן]\u0006 \u0003בנדר שהודר על דעת רבים קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 שבית הדין אומר לו: על דעתנו אתה נודר ממנה הנאה. ר' אליעזר סבור אין לנדר כזה התרה, ואילו ר' יהושע סבור שגם לנדר זה יש התרה, ולכן לא יועיל הדבר למנוע קינוניא בנכסי ההקדש.","ומקשים: \u0003ואלא הא דאמר\u0004 \u0005[זו שאמר]\u0006 \u0003אמימר: נדר שהודר ברבים יש לו הפרה,\u0004 ואילו נדר שהודר \u0003על דעת רבים אין לו הפרה\u0004 — \u0003לימא כתנאי אמרה לשמעתיה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005כ\u0006דבר השנוי במחלוקת \u0005תנאים אמר את הלכתו]?\u0006 \u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות: מה ששנינו \u0003ר' יהושע אומר: אינו צריך\u0004 לידור — אינו מתאים לדרך זו, שהרי \u0003\"אינו מועיל\" מיבעי ליה\u0004 \u0005[צריך היה לו לומר]!\u0006","\u0003אלא הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004ענין \u0003שאלה\u0004 על \u0003הקדש קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 האם יכול אדם להישאל אצל חכם על נדר הקדש, ויתיר לו את נדרו, כפי שהוא בשאר נדרים. ר' אליעזר סבור שאינו יכול להישאל על נדרו, ולכן יש לחשוש שאדם מגרש את אשתו כדי להוציא בדרך זו את נכסיו מן ההקדש. ור' יהושע סבור כי הואיל והוא יכול להישאל ולהתיר נדר הקדש, לכך אין לחשוש שעשה קינוניא.","ומוסיפים, \u0003והתניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003המקדיש\u0004 את \u0003נכסיו והיתה עליו כתובת אשה, ר' אליעזר אומר: כשהוא מגרשה ידור הנאה\u0004 ממנה, שמא עושה קינוניא על הקדש, \u0003ר' יהושע אומר: אינו צריך. ואמר\u0004 על כך \u0003ר' אלעזר בר' שמעון:\u0004 דברי ר' אליעזר \u0003הן הן דברי בית שמאי,\u0004 ודברי ר' יהושע \u0003הן הן דברי בית הלל,\u0004","\u0003שבית שמאי אומרים: הקדש,\u0004 למרות שנעשה ב\u0003טעות\u0004 — \u0003הקדש\u0004 הוא, ולכן אין אדם יכול להישאל על ההקדש ולומר שלא על דעת כן נדר. \u0003ובית הלל אומרים: הקדש טעות אינו הקדש,\u0004 ולכן יכול אדם להישאל על נדרו ולומר שנעשה בטעות, ויתירו לו.","שנינו במשנתנו, \u0003וכן היה רבן שמעון בן גמליאל אומר:\u0004 אף הערב לאשה בכתובתה, והיה בעלה מגרשה — ידירנה הנאה, שמא יעשה קינוניא על נכסים של הערב, שאם אין לבעל במה לפרוע — תיטול אשתו מנכסי הערב בכתובתה, ויחזיר הבעל את אשתו. ומספרים, \u0003משה בר עצרי ערבא דכלתיה הוה\u0004 \u0005[ערב של כלתו היה]\u0006 לפרעון הכתובה שהתחייב לה בנו, \u0003ורב הונא בריה\u0004 \u0005[בנו]\u0006 של משה בר עצרי \u0003צורבא מרבנן הוה\u0004 \u0005[תלמיד חכם היה],\u0006 \u0003ודחיקא ליה מילתא\u0004 \u0005[והיה דחוק לו הדבר]\u0006 כלומר, היה עני מאד. \u0003אמר אביי: ליכא דנסבי\u0004 \u0005[\u0006האם \u0005אין\u0006 מי \u0005שישיא]\u0006 \u0003עצה לרב הונא, דליגרש לדביתהו\u0004 \u0005[שיגרש את אשתו]\u0006 \u0003ותיתבע\u0004 האשה את \u0003כתובתה מאבוה\u0004 \u0005[מאביו]\u0006 שהיה ערב לתשלום הכתובה, \u0003ולהדרה מיהדרי\u0004 \u0005[ושיחזור\u0006 וישאנה\u0005],\u0006 וייהנו מהכסף שתקבל מאביו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והאנן\u0004 \u0005[והרי אנו]\u0006 \u0003ידור הנאה תנן\u0004 \u0005[שנינו]\u0006 במשנתנו, ואם כן לא יוכל לחזור ולשאת את אשתו! ושואלים: \u0003ואביי\u0004 מה סבור? ומשיבים: \u0003אטו כל דמגרש בבי דינא מגרש\u0004 \u0005[וכי כל מי שמגרש\u0006 את אשתו \u0005בבית דין מגרש]?\u0006 יגרשנה שלא בבית דין, וכך לא יכריחו אותו לידור הנאה ממנה, ויוכל להחזירה. ומספרים: \u0003לסוף איגלאי מלתא דכהן הוה\u0004 \u0005[לבסוף התגלה הדבר שכהן היה]\u0006 אותו רב הונא, ואם היה מגרש את אשתו לא יכול היה להחזירה. \u0003אמר אביי,\u0004 הוא שאומרים: \u0003בתר עניא אזלא עניותא\u0004 \u0005[אחרי העני הולכת העניות]\u0006 כלומר, קשה לעני לצאת מעניותו.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 יתכן ש\u0003אמר אביי הכי\u0004 \u0005[כך]\u0006 ונתן עצה זו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי\u0004 עצמו: \u0003איזהו רשע ערום\u0004 שדיברו עליו חכמים? \u0003זה המשיא\u0004 (הנותן) לאדם אחר \u0003עצה למכור בנכסים\u0004 שקיבל מחבירו כדי שיעברו אחרי מותו לפלוני, \u0003כ\u0004דעת \u0003רבן\u0004 שמעון בן \u0003גמליאל,\u0004 הסבור שהמכירה מועילה, ואותו פלוני לא יכול להוציאם מהקונה. הרי שלדעת אביי, הנותן עצה לעשות בנכסים דבר שהוא נגד כוונת הנותן נקרא \"רשע ערום\", וכיצד ייתכן שהציע להוציא ממון מן הערב לא לשם המטרה שהתחייב לה?","ומשיבים: כאשר אדם ערב ל\u0003בריה\u0004 \u0005[\u0006ל\u0005בנו]\u0006 \u0003שאני\u0004 \u0005[שונה\u0006 הדבר\u0005],\u0006 שהוא מוחל על כך, שהרי ממילא סופו ליורשו, \u0003ו\u0004כן כאשר נעשה הדבר לטובת \u0003צורבא מרבנן\u0004 \u0005[תלמיד חכם]\u0006 \u0003שאני\u0004 \u0005[שונה\u0006 הדין\u0005],\u0006 שראוי לסייע לו בעצה כזו, כדי שיוכל לשבת ולעסוק בתורה.","ומקשים: \u0003ותיפוק ליה\u0004 \u0005[ושתצא לו]\u0006 שאין תועלת בעצה זו, מפני ש\u0003ערב\u0004 של \u0003כתובה\u0004 באמת \u0003לא משתעבד\u0004 לתשלום הכתובה (כפי שיבואר להלן)!"],["ומשיבים: לא סתם ערב, אלא ערב \u0003קבלן הוה\u0004 \u0005[היה],\u0006 שקיבל על עצמו את תשלום החוב, והוא אכן משתעבד. ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]:\u0006 ערב \u0003קבלן, אף על גב דלית ליה\u0004 \u0005[אף על פי שאין לו]\u0006 \u0003נכסים ללוה\u0004 בשעת ההלוואה — בכל זאת \u0003משתעבד, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003אית ליה\u0004 \u0005[\u0006אם \u0005יש לו]\u0006 נכסים ללווה — \u0003משתעבד\u0004 ערב זה, \u0003לית ליה\u0004 \u0005[\u0006אם \u0005אין לו]\u0006 נכסים — \u0003לא\u0004 גומר הערב בלבו ו\u0003משתעבד, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 כיצד ניתן היה לגבות ממשה בר עצרי? והרי לא היו כלל נכסים לרב הונא בנו!","ומתרצים, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003רב הונא הוה ליה ואישתדוף\u0004 \u0005[היו לו\u0006 נכסים בשעה שקיבל אביו את הערבות על עצמו, \u0005והשתדפו]\u0006 ופחת ערכם. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אבא לגביה בריה שעבדה משעבד נפשיה\u0004 \u0005[האב לגבי בנו משעבד עצמו],\u0006 למרות שאין לבנו נכסים.","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 בענין זה: מי שהוא \u0003ערב\u0004 ל\u0003כתובה\u0004 — \u0003דברי הכל לא\u0004 גומר בלבו להיות \u0003משתעבד,\u0004 מי שהוא ערב \u0003קבלן\u0004 ל\u0003בעל חוב\u0004 — \u0003דברי הכל משתעבד,\u0004 אבל במי שהוא \u0003ערב\u0004 סתם ל\u0003בעל חוב, ו\u0004כן במי שהוא ערב \u0003קבלן\u0004 ל\u0003כתובה\u0004 — \u0003פליגי\u0004 \u0005[נחלקו]\u0006 חכמים, \u0003איכא למאן דאמר\u0004 \u0005[יש מי שאומר]:\u0006 \u0003אית ליה נכסי\u0004 \u0005[\u0006אם \u0005יש לו נכסים]\u0006 \u0003ללוה\u0004 או לבעל — \u0003משתעבד, לית ליה\u0004 \u0005[\u0006אם \u0005אין לו]\u0006 נכסים ללווה או לבעל — \u0003לא משתעבד; ואיכא למאן דאמר\u0004 \u0005[ויש מי שאומר]:\u0006 \u0003אף על גב דלית ליה\u0004 \u0005[אף על פי שאין לו]\u0006 נכסים ללווה או לבעל — \u0003משתעבד\u0004 הערב.","ומסכמים: \u0003והלכתא בכולהו\u0004 \u0005[והלכה\u0006 היא \u0005בכולם,\u0006 בכל המקרים\u0005]:\u0006 \u0003אף על גב דלית ליה\u0004 \u0005[אף על פי שאין לו]\u0006 למתחייב נכסים משל עצמו — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003משתעבד\u0004 הערב, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מערב\u0004 סתם ל\u0003כתובה, דאף על גב דאית ליה\u0004 \u0005[שאף על פי שיש לו]\u0006 לבעל באותה שעה נכסים — \u0003לא\u0004 גומר הערב בלבו להיות \u0003משתעבד, מאי טעמא\u0004 \u0005[\u0006ו\u0005מה טעם\u0006 הדבר\u0005]?\u0006 \u0003מצוה קעביד\u0004 \u0005[הוא עושה]\u0006 שעזר לה להחליט להינשא, ולכך נתכוון, ולא להשתעבד. \u0003ו\u0004כן \u0003לא מידי חסריה\u0004 \u0005[לא חיסר דבר]\u0006 מהאשה שישתעבד בגללו, שהרי לא הלוותה כסף לבעל על סמך הערבות.","ושבים לעיקר דין משנתנו, שהבא לגרש את אשתו, אם הקדיש נכסיו, או שהיה אדם אחר ערב לכתובתה, והיא באה לגבות כתובתה מן ההקדש או מן הערב לכתובה — צריך לידור הנאה ממנה, מחשש לקינוניא. מסופר: \u0003ההוא גברא דזבנינהו לנכסיה וקא גרשה לדביתהו\u0004 \u0005[\u0006מעשה ב\u0005איש אחד שמכר את נכסיו ו\u0006אחר כך \u0005גירש את אשתו],\u0006 ולא היה לבעל במה לפרוע את כתובתה, ובאה האשה לגבות את כתובתה מן הלקוחות, שקנו נכסים מן הבעל לאחר שנשאה. \u0003שלחה\u0004 \u0005[שלח\u0006 שאלה \u0005זו]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא:\u0004 כשהכתובה עומדת לגבייה מן ה\u0003ערב תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שהבעל נודר הנאה מגרושתו, כדי למנוע אפשרות לקינוניא, וכן כשהיא עומדת לגבייה מן ה\u0003הקדש תנן\u0004 \u0005[שנינו]\u0006 שכך הדין, אבל כשהכתובה עומדת להיגבות מ\u0003לוקח מהו\u0004 הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תנא כי רוכלא ניחשיב וניזיל\u0004 \u0005[\u0006וכי ה\u0005תנא כרוכל\u0006 המציע את מרכולתו \u0005ילך וימנה]\u0006 את כל האפשרויות? בוודאי שגם בגבייה מלקוחות צריך הבעל לידור הנאה מאשתו, מחשש לקינוניא.","\u0003נהרדעי אמרי\u0004 \u0005[חכמי נהרדעא אומרים]:\u0006 \u0003דתנן תנן\u0004 \u0005[\u0006מה \u0005ששנינו\u0006 במשנה \u0005שנינו],\u0006 \u0003דלא תנן לא תנן\u0004 \u0005[\u0006מה \u0005שלא שנינו לא שנינו],\u0006 ולדעתם, כשהכתובה נגבית מלקוחות אין הבעל צריך לידור הנאה. \u0003אמר רב משרשיא: מאי טעמא דנהרדעי\u0004 \u0005[מה טעמם של\u0006 חכמי \u0005נהרדעא]?\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003הקדש\u0004 — \u0003משום ריוח\u0004 של \u0003הקדש\u0004 הצריכו לידור הנאה, וכן לגבי \u0003ערב\u0004 לכתובה \u0003נמי\u0004 \u0005[גם כן]\u0006 הצריכו לידור הנאה — מפני ש\u0003מצוה הוא דעבד\u0004 \u0005[שעשה],\u0006 שסייע בידם להחליט להינשא, \u0003ולאו מידי חסריה\u0004 \u0005[ולא\u0006 קיבל ממנה \u0005דבר],\u0006 ולמרות זאת השתעבד (באותם מקרים שאמרו חכמים שהוא משתעבד), ויש מקום להדיר את הבעל, כדי שלא יימנעו אנשים מלעשות מצוה.","\u0003אלא לוקח\u0004 (קונה) השדה מן הבעל, \u0003מכדי מידע ידע דכל חד וחד איכא עליה כתובה\u0004 \u0005[הואיל וידוע הדבר שכל אחד ואחד\u0006 שנשוי \u0005יש עליו כתובה],\u0006 \u0003אמאי ניזיל וניזבון\u0004 \u0005[מדוע שילך ויקנה]\u0006 שדה כשיש עליה חשש של שיעבוד לכתובה? \u0003איהו הוא דאפסיד אנפשיה\u0004 \u0005[הוא שהפסיד לעצמו],\u0006 ואין מקום לגזור על הבעל שלא יוכל להחזיר את אשתו לעולם רק משום חשש טובת הלוקח.","\u0003המקדיש\u0004 כל \u0003נכסיו ו\u0004כבר \u0003היתה עליו\u0004 התחייבות לפרעון \u0003כתובת אשתו ו\u0004ל\u0003בעל חוב.\u0004 ואין לו ממה לפורעם, והם רוצים להוציא את הנכסים המשועבדים להם מיד ההקדש — \u0003אין האשה יכולה לגבות כתובתה\u0004 ישירות \u0003מן\u0004 הנכסים שביד \u0003ההקדש, ולא בעל חוב את חובו, אלא\u0004 צריך לפדות תחילה את הנכסים מיד ההקדש, ו\u0003הפודה\u0004 כלומר, הבעל או הלווה, \u0003פודה\u0004 אותם בזול, במחיר שאדם מוכן לפדות נכסים על מנת \u0003ליתן\u0004 אותם \u0003לאשה בכתובתה\u0004 \u0003ולבעל חוב את חובו.\u0004 ואם \u0003הקדיש תשעים מנה,\u0004 שכך היה שווי נכסיו, \u0003והיה חובו מאה מנה,\u0004 ונמצא שאין לו במה לפדות — \u0003מוסיף\u0004 המלוה ללווה \u0003עוד דינר, ו\u0004הלה \u0003פודה את הנכסים האלו\u0004 בזול, \u0003על מנת ליתן לאשה כתובתה ולבעל חוב את חובו.\u0004","ושואלים, \u0003למה לי למימר\u0004 \u0005[לומר]:\u0006 \u0003\"הפודה פודה\"?\u0004 כלומר, מדוע לא יתנוהו ישירות לבעל החוב? ומשיבים: \u0003משום\u0004 הסברו של \u0003ר' אבהו,\u0004 ש\u0003אמר ר' אבהו:\u0004 כדי \u0003שלא יאמרו\u0004 אנשים: \u0003הקדש יוצא\u0004 לחולין \u0003בלא פדיון.\u0004","על מה ששנינו: היה חובו מאה מנה והקדיש תשעים מנה — מוסיף עוד דינר ופודה וכו', מעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 היא, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: אם היה חובו\u0004 \u0003כנגד הקדשו\u0004 — \u0003פודה\u0004 הלווה באופן זה, שנותן סכום קטן בפדיון הנכסים, והמלוה (או האשה) מקבל את שלו,","\u0003ואם לאו\u0004 \u0005[לא],\u0006 שאין בנכסים שביד ההקדש כדי לכסות החוב — \u0003אינו פודה\u0004 את הנכסים אלא בשוויים. ושואלים: \u0003ו*\u0004 לדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003עד כמה\u0004 ניתן לפדות באופן זה? \u0003אמר רב הונא בר יהודה אמר רב ששת:\u0004 כשהנכסים שביד ההקדש שווים \u0003עד פלגא\u0004 \u0005[מחצית]\u0006 מהחוב. אבל אם הם שווים פחות ממחצית החוב — לא יפדה אותם אלא בשוויים.","\u0003אף על פי שאמרו\u0004 במשנה לעיל (כא,א) \u0003חייבי ערכין ממשכנין אותו,\u0004 שנכנסים הגזברים לביתו של הנודר ונוטלים מה שיש לו לצורך תשלום הנדר, \u0003נותנין\u0004 (משאירים) \u0003לו\u0004 מעות כדי \u0003מזון שלשים יום, וכסות\u0004 המספיקה ל\u0003שנים עשר חדש,\u0004 ו\u0003מטה מוצעת\u0004 (עם מצעים) \u0003וסנדליו ותפליו.\u0004 ומשאירים \u0003לו, אבל לא לאשתו ולבניו.\u0004","\u0003אם היה\u0004 החייב \u0003אומן\u0004 — \u0003נותן לו\u0004 הגזבר גם \u0003שני כלי אומנות מכל מין ומין\u0004 של מלאכתו, וכגון \u0003חרש\u0004 (נגר) — \u0003נותנין לו שני מצעדין\u0004 (מעצדים, מקצועות) \u0003ושני מגירות\u0004 (משורים). \u0003ר' אליעזר אומר: אם היה איכר\u0004 — \u0003נותן לו צמדו,\u0004 צמד הבקר שחורש בו, אם היה \u0003חמר,\u0004 מוביל משאות על חמורו — \u0003נותן לו חמורו.\u0004","\u0003היה לו מין אחד\u0004 של כלי אומנות \u0003מרובה\u0004 ממה שהתירו חכמים להשאיר בידו, \u0003ומין אחד מועט,\u0004 כגון שלושה מעצדים ומגירה אחת — \u0003אין אומר\u0004 לגזבר \u0003למכור את המרובה\u0004 (מעצד אחד) \u0003וליקח\u0004 (לקנות) \u0003מן המועט\u0004 (מגירה אחת), אלא נותנין לו שני מינין מן המרובה וכל שיש לו מן המועט. ומעירים: מה שנאמר שמשאירים לו תפילין, הוא במי שממשכנים אותו, אבל \u0003המקדיש\u0004 כל \u0003נכסיו\u0004 — \u0003מעלין\u0004 (נוטלים) \u0003לו תפיליו\u0004, מפני שהם בכלל כל נכסיו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005],\u0006 שמשאירים למעריך העני את כל מה שמנינו במשנתנו? ומשיבים, \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006"],["\u0003\"ואם מך הוא מערכך\"\u0004 (ויקרא כז, ח), ומן המלה המיותרת \"הוא\", שמשמעה הויה, חיות, למדים: \u0003החייהו מ\u0004תוך מה שהתחייב ב\u0003ערכך.\u0004","שנינו במשנה שמשאירים בידו מזון וכסות, לו \u0003אבל לא לאשתו ובניו.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שנאמר \u0003\"הוא מערכך\"\u0004 — אותו החייה מערכך, \u0003ולא אשתו ובניו\u0004 החייה \u0003מערכך.\u0004 שנינו במשנה, \u0003ר' אליעזר אומר: אם היה איכר נותן לו צמדו,\u0004 חמר נותן לו חמורו. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מדוע לדעתם נוטלים אותם ממנו? והרי משאירים לו כלי אומנות! ומשיבים: לדעתם, \u0003הנהו\u0004 \u0005[אלה],\u0006 צמד הבקר והחמור, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלי אומנות נינהו\u0004 \u0005[הם],\u0006 \u0003אלא\u0004 בכלל \u0003נכסים\u0004 \u0003נינהו\u0004 \u0005[הם].\u0006","","ועוד שנינו במשנה: \u0003היה לו מין אחד\u0004 מרובה, ממה שהתירו חכמים להשאיר בידו, ומין אחד מועט מן הקצבה, כגון שלושה מעצדים ומגירה אחת — אין מוכרים מן המרובה וקונים מן המועט. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, שהרי \u0003כי היכי דסגי ליה עד השתא\u0004 \u0005[כמו שהיה די לו עד עכשיו]\u0006 במגירה אחת, \u0003השתא נמי סגי ליה\u0004 \u0005[עכשיו גם כן די לו]!\u0006","ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003עד האידנא דהוה ליה לאושולי\u0004 \u0005[עד עכשיו שהיה לו להשאיל]\u0006 מן המעצדים המרובים שהיו לו, כשהיה זקוק למגירה נוספת, \u0003הוה מושלי ליה\u0004 \u0005[היו משאילים לו],\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 אחר הגבייה, \u0003דליכא דמשיל ליה\u0004 \u0005[שאין מי שישאיל לו]\u0006 בלא תמורה — \u0003לא\u0004 נשאיר בידו רק מגירה אחת, אלא ימכור מן המעצדים ויקנה מגירה, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין חוששים לכך.","שנינו במשנה: \u0003המקדיש את נכסיו מעלין\u0004 (נוטלים) \u0003לו תפילין\u0004 שלו. בענין זה מסופר, \u0003ההוא גברא דזבנינהו לנכסיה\u0004 \u0005[\u0006מעשה ב\u0005אדם אחד שמכר את\u0006 כל \u0005נכסיו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יימר, אמר להו\u0004 \u0005[להם]:\u0006 \u0003סליקו ליה\u0004 \u0005[חלצו לו]\u0006 \u0003תפילין\u0004 מראשו וידו, ותנום לקונה, שגם הם בכלל נכסיו. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 בסיפור זה? לשם מה הוצרך? הלא \u0003מתניתין\u0004 \u0005[משנה\u0006 מפורשת\u0005]\u0006 \u0003היא\u0004 ששנינו כאן לענין הקדש: \u0003המקדיש נכסיו מעלין לו תפיליו,\u0004 מפני שהם בכלל נכסיו!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במקדיש כל נכסיו, \u0003הוא\u0004 שאנו אומרים כן מפני \u0003דסבר מצוה קא עבידנא\u0004 \u0005[ש\u0006הוא \u0005סבור מצוה אני עושה],\u0006 \u0003אבל לענין זבוני\u0004 \u0005[מכר],\u0006 \u0003מצוה דגופיה לא זבין איניש\u0004 \u0005[מצוה ש\u0006עושה ב\u0005גופו,\u0006 כתפילין, \u0005אין אדם מוכר\u0006 שלא במפורש\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שתפילין בכלל נכסיו הם.","\u0003אחד המקדיש נכסיו, ואחד המעריך עצמו\u0004 ובית דין גובים מנכסיו, \u0003אין לו\u0004 זכות \u0003בכסות אשתו ולא בכסות בניו\u0004 של המקדיש והמעריך, \u0003ולא בצבע\u0004 (בבגד צבוע) \u0003שצבע לשמן\u0004 (עבורם), \u0003ולא בסנדלים חדשים שלקחן\u0004 (שקנה) \u0003לשמן,\u0004 ולכן אין גובים מהם. ועוד בדיני הקדש: \u0003אף על פי שאמרו\u0004 התגרים: \u0003עבדים נמכרין בכסותן לשבח,\u0004 \u0003שאם תלקח לו כסות\u0004 נאה ששווה \u0003שלשים דינר\u0004 הריהו \u0003משובח,\u0004 עולה שוויו ב\u0003מנה\u0004 (מאה דינר) נוספים, \u0003וכן פרה אם ממתינין אותה לאיטליס\u0004 (ליום השוק) \u0003משובחת היא\u0004 במחירה, \u0003וכן מרגלית, אם מעלין אותה לכרך\u0004 למוכרה שם \u0003משובחת היא\u0004 במחירה — אין מתחשבים בדבר, אלא \u0003אין להקדש אלא מקומו ושעתו.\u0004 ביחס למה ששנינו כי אין להקדש אלא מקומו ושעתו, מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 נאמר ביחס לפדיון מיד ההקדש: \u0003\"ונתן את הערכך ביום ההוא\"\u0004 (ויקרא כז, כג), ומן ההדגשה \"ביום ההוא\" יש ללמוד \u0003שלא ישהה מרגלית לקלים,\u0004 לעניים, בני הכפר, על מנת להעלותה לכרך, אלא אומדים אותה לפי מקומה. וממה שנאמר בהמשך הכתוב \u0003\"קדש לה' \"\u0004למדים ש\u0003סתם ההקדישות,\u0004 שאמר אדם: \"נכסי להקדש\" — ניתנים \u0003לבדק הבית,\u0004 ולא לכהנים.","","","","\u0003אין מקדישין\u0004 שדה אחוזה (נחלת אבות) \u0003לפני היובל\u0004 כשנשארו \u0003פחות משתי שנים\u0004 עד היובל, \u0003ולא גואלין\u0004 פודים שדה אחוזה \u0003אחר היובל פחות משנה אחת\u0004 אחר היובל. וכשגואלים, ומחשבים את סכום הפדיון לפי מספר השנים הנותרות עד היובל, \u0003אין מחשבין חדשים להקדש,\u0004 כדי לשלם פחות מן הסכום הקצוב לפדיון שנה שלימה, \u0003אבל הקדש\u0004 רשאי להיות \u0003מחשב חדשים\u0004 (כפי שיתבאר בגמרא).","שנינו במשנה: אין מקדישין לפני היובל פחות משתי שנים. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו בברייתא: \u0003מקדישין בין לפני היובל בין לאחר היובל, ובשנת היובל עצמה לא יקדיש, ואם הקדיש\u0004 בשנת היובל \u0003אינה קדושה.\u0004 הרי שניתן להקדיש לפני היובל!","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 בהסבר הדבר: אין כוונת המשנה לומר שלא ניתן להקדיש סמוך ליובל. אלא ש\u0003אין מקדישין ליגאל בגירוע\u0004 (בהפחתה לפי מנין השנים הנותרות עד היובל) בתוך \u0003פחות משתי שנים\u0004 עד היובל, אלא מי שעושה כן צריך לשלם את מלוא הערך, כאילו מקדיש ופודה בתחילת היובל — חמישים שקל לבית זרע חומר שעורים. \u0003וכיון\u0004 ש\u0003אין מקדישין ליגאל בגירוע פחות משתי שנים,\u0004 אמרו חכמים במשנתנו בלשון \"אין מקדישין\", לומר ש\u0003יהא אדם חס על נכסיו ואל יקדיש פחות משתי שנים\u0004 לפני היובל.","ובענין ששנינו בברייתא, שאם הקדיש שדה אחוזה בשנת היובל אינה קדושה, \u0003איתמר\u0004 \u0005[נאמרה]\u0006 מחלוקת אמוראים: \u0003המקדיש שדהו בשנת היובל עצמה, רב אמר: קדושה, ו\u0004אם רוצה לפדותה \u0003נותן\u0004 מחיר מלא של \u0003חמשים\u0004 שקלים לבית זרע חומר שעורים, \u0003ושמואל אמר: אינה קדושה כל עיקר,\u0004 ואינו צריך לתת דבר להקדש בפדיונה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: בשלמא\u0004 \u0005[נניח]\u0006 \u0003לענין מכירה\u0004 של שדה אחוזה לחבירו בשנת היובל עצמה, \u0003דפליג\u0004 \u0005[ש\u0006כמבואר בהמשך מסכת זו, \u0005חולק]\u0006 \u0003שמואל עליה\u0004 \u0005[על]\u0006 \u0003רב,\u0004 ואמר שאינה מכורה כל עיקר, \u0003איכא למימר\u0004 \u0005[יש לומר]\u0006 ש\u0003קל וחומר\u0004 הוא, וכפי שאמר שמואל בעצמו: \u0003ומה\u0004 שדה שהיתה \u0003מכורה כבר\u0004 — \u0003יוצאה עכשיו\u0004 ביובל, מיד הקונה לבעלים, זו \u0003שאינה מכורה\u0004 עדיין — \u0003אינו דין שלא תימכר\u0004 ביובל, כלומר, שלא יחול המכר?","\u0003אלא הכא\u0004 \u0005[כאן]\u0006 בהקדש, \u0003מי איכא למימר\u0004 \u0005[האם יש לומר]\u0006 \u0003קל וחומר\u0004 כזה? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הגיע יובל ולא נגאלה\u0004 שדה האחוזה על ידי בעליה — \u0003כהנים נכנסין לתוכה ונותנין דמיה\u0004 להקדש, אלו \u0003דברי ר' יהודה.\u0004 הרי ששדה שהקדישוה לפני היובל אינה יוצאת מיד ההקדש בלא פדיון, ואם כן, לא ניתן ללמוד מכאן שאם הקדישה בשנת היובל עצמה שתחזור לבעליה בלא פדיון! ומשיבים: \u0003שמואל כ\u0004דעת \u0003ר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר\u0004 כי הכהנים \u0003נכנסין\u0004 בשנת היובל \u0003ולא נותנין\u0004 דמים להקדש בפדיונה, ולפיכך יש לומר שאם הקדישה בשנת היובל אינה צריכה פדיון.",""],["\u0003ו\u0004לעומתו \u0003רב סבר\u0004 \u0005[סבור]:\u0006 גם אם נעמיד ברייתא זו כשיטת ר' שמעון, אין כאן קל וחומר, שכן \u0003סוף סוף לבעלים מי קהדרא\u0004 \u0005[האם\u0006 היא \u0005חוזרת]\u0006 בשנת היובל, שתלמד מכאן כי אם הקדישה ביובל אינה מקודשת? והרי \u0003לכהנים הוא דנפקא\u0004 \u0005[ש\u0006היא \u0005יוצאת],\u0006 ויש להבין כי השדה נשארה ביד ההקדש, \u0003וכהנים משולחן גבוה קא זכו\u0004 \u0005[הם זוכים]!\u0006","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור לדבריו\u0005]\u0006 של \u0003רב,\u0004 שהמקדיש שדהו ביובל הריהי קדושה, ופודה בחמישים שקלים לכל בית זרע חומר שעורים? ומשיבים, \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"ואם משנת היובל\u0004 יקדיש שדהו כערכך יקום\" (ויקרא כז, יז), כלומר, בערך המלא, של חמישים שקל לכל בית זרע חומר שעורים, האמור בפסוק הקודם, \u0003ו\u0004לשון \"משנת היובל\" משמעה ש\u0003שנת היובל\u0004 עצמה \u0003בכלל,\u0004 כאילו נאמר: \"ואם בשנת היובל יקדיש\".","ושואלים: \u0003ושמואל,\u0004 מה הוא משיב לכך? ומשיבים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ואם בשנת היובל\"?\u0004 והרי \u0003\"משנת היובל\" כתיב\u0004 \u0005[נאמר]\u0006 — \u0003משנת\u0004 (מהשנה) \u0003שאחר היובל.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב, היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 שם: \u0003\"אם משנת היובל\u0004 יקדיש שדהו כערכך יקום\" — בשנת היובל עצמה, ובכתוב שלאחריו (שם יח) נאמר: \u0003\"ואם אחר היובל\u0004 יקדיש שדהו וחישב לו הכהן את הכסף על פי השנים הנותרות ונגרע מערכך\" — בשנה שלאחר היובל. \u0003אלא לשמואל,\u0004 המפרש כי \"משנת היובל\" היא השנה שלאחר היובל, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מה שנאמר לאחר מכן \"ואם \u0003אחר היובל\"?\u0004 ומשיבים: \u0003אחר\u0004 השנה ש\u0003אחר\u0004 היובל.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דעת רב, ממה ששנינו בברייתא: \u0003מקדישין בין לפני היובל בין לאחר היובל, ובשנת היובל עצמה לא יקדיש, ואם הקדיש\u0004 — \u0003אינה קדושה!\u0004 ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003רב:\u0004 הכוונה היא ש\u0003אינה קדושה\u0004 להיגאל \u0003בגירוע\u0004 (בהפחתה), \u0003אבל קדוש ונותנין חמשים\u0004 שקל לבית זרע חומר שעורים.","ומתקשים: \u0003מכלל\u0004 הסבר זה אתה צריך לומר, כי לדעת רב, מה שאמרה הברייתא ש\u0003לפני היובל\u0004 מקדישים, כוונתה באותו אופן — שהשדה \u0003קדושה\u0004 אז \u0003ליגאל בגירוע;\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין מקדישין ליגאל בגירוע פחות משתי שנים\u0004 לפני היובל, אלא צריך לשלם את מלוא הערך!","אלא צריך ליישב את הדברים באופן אחר, \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003רב: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו,\u0006 הסבורה שאין מקדישים שדה אחוזה ביובל, כשיטת \u0005מי היא]?\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 הסבורים כי כשהכתוב משתמש בביטוי \"מיום פלוני\" — אין אותו יום בכלל, ואף כאן כשנאמר \"משנת היובל יקדיש\" אין שנת היובל בכלל, \u0003ואנא דאמרי\u0004 \u0005[ו\u0006אילו \u0005אני שאמרתי]\u0006 שאפשר להקדיש ביובל, סבור \u0003כ\u0004שיטת \u0003רבי,\u0004 ש\u0003אמר:\u0004 כשאמר הכתוב \"כי כל אוכל חמץ... מיום הראשון עד יום השביעי\" (שמות יב, טו), \"מיום ה\u0003ראשון\"\u0004 — \u0003ו\u0004היום ה\u0003ראשון\u0004 עצמו אף הוא \u0003בכלל,\u0004 וכשאמר הכתוב \"עד יום ה\u0003שביעי\"\u0004 — \u0003ושביעי בכלל; הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003\"שנת\u0004 היובל יקדיש\" — \u0003ושנת היובל\u0004 עצמה \u0003בכלל.\u0004 ושואלים: והרי שנינו במשנה בלא חולק, כי הפודה שדה אחוזה צריך לתת עבור כל שנה שנותרה עד היובל סלע ופונדיון (אחד מארבעים ושמונה בסלע) לבית זרע חומר שעורים, והוא ערך הפדיון המלא (חמישים סלע) כשהוא מתחלק לארבעים ותשע שנים.","ו\u0003אי\u0004 \u0005[אם]\u0006 רב סבור \u0003כ\u0004הבנתו בשיטת \u0003רבי,\u0004 שניתן להקדיש גם בשנת היובל עצמה, \u0003פונדיון מאי עבידתיה\u0004 \u0005[מה מעשיו],\u0006 כלומר, מדוע צריך להוסיפו? והרי יש לחלק את חמישים הסלעים בחמישים השנים שבהן ניתן להקדיש, ומגיע לכל שנה סלע במדוייק!","\u0003וכי תימא לית ליה\u0004 \u0005[ואם תאמר\u0006 ש\u0005אין לו]\u0006 שרבי אינו סבור שצריך להוסיף פונדיון — \u0003והתנן\u0004 \u0005[והרי שנינו]:\u0006 \u0003הקדיש\u0004 שדה אחוזה \u0003שתים ושלש שנים לפני היובל, רבי אומר, אומר אני: נותן סלע ופונדיון\u0004 לכל שנה! ומשיבים: לשיטת רב, \u0003רבי כר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר:\u0004 \u0003שנת חמשים עולה לכאן ולכאן,\u0004 שהיא נחשבת גם כשנה הראשונה ליובל הבא, ונמצא שיש למעשה ארבעים ותשע שנים ביובל, ולכן פדיון כל שנה הוא סלע ופונדיון.","ושואלים: \u0003ל\u0004שיטת \u0003שמואל,\u0004 שרבי מודה שאי אפשר להקדיש בשנת היובל עצמה, אלא רק בשנה שלאחריה, \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003רבי,\u0004 שאמר שנותן סלע ופונדיון לשנה, \u0003כרבנן\u0004 \u0005[כחכמים\u0006 החולקים על ר' יהודה\u0005]\u0006 \u0003סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ששנת החמישים אינה נחשבת כתחילת היובל הבא? \u0003דאי\u0004 \u0005[ש\u0006הרי \u0005אם]\u0006 הוא סבור \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 שיש ארבעים ותשע שנה ביובל, וניתן להקדיש רק בשנה שלאחר היובל, כלומר ארבעים ושמונה שנים לכל היותר, הלא \u0003סלע ושתי פונדיונות מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לתת\u0005]\u0006 כשהוא פודה בשנה זו — חמישים שקלים, שהוא ערך הפדיון המלא, כשהוא מחולק לארבעים ושמונה! ומשיבים: אמנם כן, \u0003על כרחך ל\u0004שיטת \u0003שמואל, רבי\u0004 — \u0003כרבנן\u0004 \u0005[כחכמים]\u0006 \u0003סבירא ליה\u0004 \u0005[סבור הוא].\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה למחלוקת רב ושמואל ממה ששנינו במשנתנו: \u0003ולא גואלין אחר היובל פחות משנה. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003שמואל\u0004 הסבור כי אין מקדישים בשנת היובל עצמה, מובן מה שנאמר ש\u0003לא גואלין לאחר\u0004 ה\u0003יובל פחות משנה,\u0004 אבל לא בשנת היובל עצמה — מפני שלא ניתן אז להקדיש, וממילא גם אין צורך לגאול. \u0003אלא לרב מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 לא גואלין \u0003אחר\u0004 ה\u0003יובל\u0004 פחות מ\u0003שנה?\u0004 והלא ניתן להקדיש ולגאול בשנת היובל עצמה!","ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שהכוונה היא \u0003אחר\u0004 ה\u0003יובל\u0004 \u0003ממש? מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אחר יובל\u0004 —"],["\u0003באמצע יובל,\u0004 כלומר, בכל אחת מן השנים שבין יובל ליובל, ומה שנאמר \"אין גואלין פחות משנה\" כוונתו \u0003דכל כמה דלא מליא ליה שנה לא מגרע ליה\u0004 \u0005[שכל זמן שלא מלאה לו שנה\u0006 שלימה \u0005אינו גורע לו\u0006 מהתשלום\u0005],\u0006 ולדוגמה, אם נותרו חמש וחצי שנים עד היובל — נותן ששה סלעים וששה פונדיונים, ולא חמישה וחצי סלעים וחמישה וחצי פונדיונים.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו\u0006 בזה\u0005]\u0006 התנא, ש\u0003אין מחשבין חדשים עם ההקדש? הא בהדיא קתני\u0004 \u0005[הרי במפורש הוא שונה]\u0006 בהמשך: \u0003אין מחשבין חדשים עם ההקדש!\u0004 ומשיבים: אכן אין זה דין נוסף, אלא \u0003מה טעם קאמר\u0004 \u0005[\u0006הוא \u0005אומר]:\u0006 \u0003מה טעם לא גואלין לאחר יובל, פחות משנה\u0004 שלימה — \u0003משום\u0004 ש\u0003אין מחשבין חדשים עם ההקדש.\u0004","ובענין ששנינו במשנתנו: \u0003אין מחשבין חדשים\u0004 להקדש, אבל ההקדש מחשב חדשים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003מנין שאין מחשבין חדשים עם ההקדש? תלמוד לומר: \"וחשב לו הכהן את הכסף על פי השנים הנותרות\u0004 עד שנת היובל ונגרע מערכך\" (ויקרא כז, יח) — \u0003שנים אתה מחשב, ואי\u0004 (ואין) \u0003אתה מחשב חדשים\u0004 בודדים לעצמם.","\u0003מניין שאם אתה\u0004 הכהן \u0003רוצה לעשות חדשים לשנה,\u0004 להחשיב אותם כאילו עברה שנה שלימה, אתה \u0003עושה? היכי דמי\u0004 \u0005[\u0006ו\u0005כיצד בדיוק הדבר],\u0006 \u0003כגון דאקדשיה בפלגא דארבעין ותמני\u0004 \u0005[שהקדיש אותה באמצע\u0006 השנה \u0005הארבעים ושמונה],\u0006 והוא רוצה לפדותה עכשיו, מנין שאם רצה הכהן לחשב את החודשים שעברו כשנה שלימה, ויפדה הפודה את השדה במחיר מלא, ולא בגרעון כסף, כדין המקדיש שנה לפני היובל?","\u0003תלמוד לומר: \"וחשב לו הכהן\", מכל מקום,\u0004 ללמד שהדבר תלוי בחישובו של הכהן.","\u0003המקדיש שדהו בשעת\u0004 (בזמן שנוהג) \u0003היובל,\u0004 והוא רוצה לפדותה — \u0003נותן ב\u0004עבור \u0003זרע חומר שעורים חמשים שקל כסף\u0004 (ויקרא כז, טז). \u0003היו שם\u0004 בשדה \u0003נקעים\u0004 (שקעים) \u0003עמוקים עשרה טפחים, או סלעים גבוהים עשרה טפחים\u0004 — \u0003אינן נמדדין עמה,\u0004 אבל היו \u0003פחות מכאן\u0004 (מעשרה טפחים) — \u0003נמדדין עמה.\u0004","\u0003הקדישה שתים\u0004 או \u0003שלש שנים לפני היובל\u0004 — \u0003נותן סלע ופונדיון ל\u0004כל \u0003שנה. ואם אמר: הריני נותן דבר שנה בשנה,\u0004 ולא משלם את כל הסכום כעת — \u0003אין שומעין לו, אלא נותן את כולו כאחד. אחד בעלים ואחד כל האדם\u0004 בדיני הפדיון, ו\u0003מה\u0004 ההבדל \u0003בין בעלים לכל אדם? אלא שבעלים נותנין\u0004 (מוסיפים) \u0003חומש,\u0004 כנאמר בתורה: \"ואם גאל יגאל את השדה המקדיש אותו ויסף חמשית כסף ערכך עליו\" (ויקרא כז, יט), \u0003וכל אדם אין נותנין חומש.\u0004","בביאור דברי המשנה \u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \"זרע חומר שעורים בחמשים שקל כסף\" (ויקרא כז, טז), הוא שטח שזורעים בו \u0003כור\u0004 (שלושים סאה) \u0003זרע, ולא\u0004 שטח שמוציאים ממנו \u0003כור תבואה,\u0004 שהוא קטן בהרבה. ומשערים את השטח הדרוש לזריעת כור ב\u0003מפולת\u0004 (זריעת) \u0003יד,\u0004 שהזרעים נופלים מידו של אדם, \u0003ולא\u0004 ב\u0003מפולת שוורים,\u0004 שהזרעים נופלים מכלי מנוקב שגוררים השוורים בשעת החרישה, ונופלים ממנו זרעים רבים ביחד, ונמצא שטח הזריעה קטן משל מפולת יד. ועוד \u0003תני\u0004 \u0005[שנה]\u0006 \u0003לוי\u0004 בברייתא: \u0003לא\u0004 זריעה באופן \u0003מעבה\u0004 (צפוף) \u0003ולא\u0004 באופן \u0003מידק\u0004 (דליל) \u0003אלא\u0004 באופן בינוני. שנינו במשנה:","\u0003היו שם נקעים עמוקים\u0004 עשרה טפחים אינן נמדדין עמה. ושואלים: \u0003וליקדשו באנפי נפשייהו\u0004 \u0005[ושיתקדשו בפני עצמם],\u0006 שהרי הם ראויים לזריעה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמדובר ששטחם קטן, ו\u0003כיון דלא הוו\u0004 \u0005[שלא היו]\u0006 בפני עצמם \u0003בית\u0004 זרע של \u0003כור\u0004 שעורים \u0003לא הוו קדשי\u0004 \u0005[לא התקדשו]\u0006 — \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 נאמר בתורה \"ואם משדה אחוזתו יקדיש איש לה' \" (ויקרא כז, טז), \u0003\"שדה\" מה תלמוד\u0004 (בא) \u0003לומר?\u0004 והלא ניתן היה לכתוב \"ואם מאחוזתו\"! \u0003לפי שנאמר\u0004 בהמשך הכתוב: \"והיה ערכך לפי זרעו \u0003זרע חומר שעורים בחמשים שקל כסף\",\u0004 יכול אתה לומר: \u0003אין לי אלא שהקדיש כענין הזה,\u0004 קרקע הראויה לזריעת חומר (כור) שעורים, \u0003מנין לרבות\u0004 קרקע הראויה לזריעת \u0003לתך\u0004 (חצי כור), \u0003וחצי לתך, סאה\u0004 (אחד משלושים בכור), \u0003ותרקב\u0004 (חצי סאה), \u0003ו\u0004אפילו \u0003חצי תרקב? תלמוד לומר: \"שדה\", מכל מקום,\u0004 שאפשר להקדיש אפילו מעט קרקע!","\u0003אמר מר עוקבא בר חמא: הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003בנקעים מלאים מים, דלאו\u0004 \u0005[שלא]\u0006 \u0003בני זריעה נינהו\u0004 \u0005[הם],\u0006 ולפיכך אינם נמדדים עמה, שהרי \"זרע\" אמר הכתוב. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר מלשון המשנה \"היו שם נקעים עמוקים עשרה טפחים או סלעים גבוהים עשרה טפחים\", \u0003דקתני\u0004 \u0005[ש\u0006הוא \u0005שונה]\u0006 נקעים \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003סלעים\u0004 שאינם ראויים לזריעה, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אפילו היו הסלעים גבוהים או הנקעים עמוקים \u0003פחות מכאן\u0004 (מעשרה טפחים), \u0003נמי\u0004 \u0005[גם כן]\u0006 לא יצטרפו, ומדוע נאמר במשנה שהם נמדדים עמה? ומשיבים: \u0003הנהו\u0004 \u0005[אלה]\u0006 נקעי המים — \u0003נגאני דארעא מיקרו\u0004 \u0005[חריצי הקרקע נקראים],\u0006 והסלעים — \u0003שידרי דארעא מיקרו\u0004 \u0005[שדראות של הקרקע נקראים],\u0006 שבטלים הם לקרקע.","שנינו במשנה: \u0003הקדישה שתים ושלש\u0004 שנים לפני היובל — נותן סלע ופונדיון לשנה. ומביאים: \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 נאמר בתורה: \"ואם אחר היובל יקדיש שדהו וחשב לו הכהן את הכסף על פי השנים הנותרות עד שנת היובל ונגרע מערכך\" (ויקרא כז, יח), והמלים","\u0003\"ונגרע מערכך\",\u0004 שהן מיותרות לכאורה, מלמדות כי \u0003אף\u0004 \u0003מן ההקדש\u0004 השנים מגרעות, \u0003שאם אכלה\u0004 \u0003הקדש,\u0004 נהנה מפירותיה \u0003שנה או שתים, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003לא אכלה\u0004 ההקדש, \u0003אלא שהיתה לפניו\u0004 בלא שימוש — \u0003נותן סלע ופונדיון לשנה,\u0004 לפי השנים הנותרות עד היובל.","שנינו במשנה: \u0003ואם אמר \"הריני נותן\u0004 דבר שנה בשנה\" אין שומעין לו, אלא נותן את כולו כאחד. במקורו של דין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003מנין שאם אמרו בעלים הרינו נותנין דבר שנה בשנה, שאין שומעין להם? תלמוד לומר: \"וחשב לו הכהן את הכסף\",\u0004 והייתור \"את הכסף\" מלמד — \u0003עד שיהא\u0004 ה\u0003כסף כולו כאחד.\u0004 ו\u0003אחד בעלים ואחד כל אדם\u0004 בדין זה, ו\u0003מה בין בעלים לכל אדם? שהבעלים נותנין חומש, וכל אדם אין נותנין חומש.\u0004","\u0003הקדישה ו\u0004אחר כך \u0003גאלה\u0004 בעצמו מההקדש — \u0003אינה יוצאה מידו\u0004 לכהנים \u0003ביובל. גאלה בנו\u0004 — \u0003יוצאה\u0004 וחוזרת \u0003לאביו ביובל. גאלה\u0004 איש \u0003אחר, או אחד מהקרובים\u0004 האחרים\u0003,\u0004 וחזר \u0003וגאלה\u0004 הבעלים \u0003מידו\u0004 — \u0003יוצאה לכהנים ביובל.\u0004","\u0003גאלה אחד מן הכהנים\u0004 מן ההקדש, והגיע היובל, \u0003והרי היא תחת ידו, לא יאמר: הואיל והיא יוצאה לכהנים ביובל והרי היא תחת ידי\u0004 — \u0003הרי היא שלי, אלא יוצאה מתחת ידו ומתחלקת לכל אחיו הכהנים.\u0004"],["שנינו במשנתנו, כי המקדיש שדה אחוזתו, ולא גאלה מיד ההקדש, אם גאלה הוא או בנו — הריהי של האב ביובל, ואם גאלה אחר — יוצאה לכהנים ביובל. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 נאמר בתורה: \"ואם לא יגאל את השדה ואם מכר את השדה לאיש אחר...","והיה השדה בצאתו ביובל קודש לה' כשדה החרם — לכהן תהיה אחוזתו\" (ויקרא כז, כ—כא), \"ו \u0003אם לא יגאל את השדה\"\u0004 — מדבר ב\u0003בעלים\u0004 שלא גאלה, \u0003\"ואם מכר את השדה\"\u0004 — מדבר ב\u0003גיזבר\u0004 של ההקדש שמכרה לאיש אחר, ללמד שבשני מקרים אלה יוצאת השדה לידי הכהנים.","ומה שנאמר \u0003\"לאיש אחר\"\u0004 בא ללמדנו — דוקא \u0003לאחר, ולא לבן\u0004 של המקדיש, שאם מכרה הגזבר לבן — יוצאת השדה לאביו ביובל ולא לכהנים. ושואלים, \u0003אתה אומר: לאחר\u0004 כוונתו — \u0003ולא לבן, או אינו\u0004 כך, \u0003אלא: לאחר\u0004 — \u0003ולא לאח\u0004 של המקדיש! ודוחים: \u0003כשהוא אומר\u0004 \"ל \u0003איש\"\u0004 — \u0003הרי אח אמור,\u0004 שהוא כלול ב\"איש\", \u0003הא מה אני מקיים \"אחר\"\u0004 — \u0003ולא לבן.\u0004","ושואלים: \u0003ומה ראית לרבות את הבן\u0004 שדינו כדין האב, \u0003ולהוציא את האח?\u0004 ומשיבים: \u0003מרבה אני\u0004 את \u0003הבן, שכן קם תחת אביו ליעידה,\u0004 שהקונה אמה עבריה מאביה יכול לקדשה לאשה, לעצמו או לבנו, אבל אינו יכול ליעדה לאחר, \u0003ולעבד עברי,\u0004 שכאשר הבן יורש את אביו — חייב העבד העברי לעבוד אותו, ואינו משתחרר במות הבעלים, מה שאין כן כשהיורש הוא האח.","ואומרים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003מרבה אני את האח,\u0004 \u0003שכן קם תחת אחיו לייבום,\u0004 שאם מת אחיו בלא בנים עליו לייבם את אשתו! ודוחים: \u0003כלום יש יבום אלא במקום שאין בן\u0004 לאחיו שמת, \u0003הא\u0004 אם \u0003יש\u0004 לו \u0003בן\u0004 — \u0003אין יבום,\u0004 ומכאן שהבן קם תחת אביו יותר מן האח!","ושואלים: לשם מה צריך לפרוך באופן זה? \u0003ותיפוק ליה\u0004 \u0005[ותצא לו\u0006 הוכחה\u0005]\u0006 שהבן עדיף על האח, משום \u0003דהכא תרתי\u0004 \u0005[שכאן,\u0006 בבן, יש \u0005שני\u0006 טעמים\u0005],\u0006 יעידה ועבד עברי, \u0003והכא חדא\u0004 \u0005[וכאן,\u0006 באח רק טעם \u0005אחד],\u0006 יבום!","ומשיבים: \u0003משום\u0004 שהדין שהבן ולא האח משתעבד ב\u0003עבד עברי\u0004 לא נכתב במפורש בתורה, אלא \u0003מהאי פירכא נמי הוא דנפקא ליה\u0004 \u0005[מאותה פירכה\u0006 עצמה \u0005גם כן הוא שיוצא לו\u0006 הדין\u0005]:\u0006 \u0003כלום יש יבום אלא במקום שאין בן,\u0004 ונמצא שזהו הבסיס העיקרי לדין זה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה בר אבוה: בת\u0004 שגאלה מן ההקדש שדה אחוזה שהקדיש אביה, \u0003מהו שתעמיד\u0004 את ה\u0003שדה לאביה\u0004 ביובל? וצדדי השאלה: \u0003כיון\u0004 ש\u0003לענין\u0004 מצות \u0003יבום,\u0004 אם נותר למת \u0003בן\u0004 או \u0003בת כי הדדי פטרי\u0004 \u0005[זו כמו זה פוטרים]\u0006 את אשת האב מיבום, לפיכך \u0003מוקמה\u0004 \u0005[מעמידה]\u0006 כאן הבת את השדה לאביה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003לענין נחלה בת במקום\u0004 שיש \u0003בן כי\u0004 \u0005[כמו]\u0006 \u0003אחר דמיא\u0004 \u0005[נחשבת]\u0006 ואינה יורשת, לפיכך אף כאן \u0003לא מוקמה\u0004 \u0005[אינה מעמידה]\u0006 את השדה לאביה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל\u0004 מי \u0003שהוא\u0004 נחשב \u0003אחר במקום\u0004 שיש \u0003בן\u0004 — אינו מעמיד את השדה ביד האב, \u0003והא נמי\u0004 \u0005[וזו גם כן,\u0006 הבת\u0005]\u0006 \u0003במקום בן כי\u0004 \u0005[כמו]\u0006 \u0003אחר דמיא\u0004 \u0005[נחשבת],\u0006 ולכן אינה מעמידה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: אשה\u0004 שהקדישה שדה אחוזה שלה, \u0003מי\u0004 מיורשיה \u0003מעמיד לה\u0004 את ה\u0003שדה\u0004 ביובל, אם פודה אותה מיד ההקדש? האם \u0003הבעל מוקים\u0004 \u0005[מעמיד]\u0006 \u0003לה, שכן\u0004 הוא זה ש\u0003יורשה\u0004 אם מתה בחייו, ולא בנה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 ה\u0003בן\u0004 הוא \u0003מוקים\u0004 \u0005[מעמיד]\u0006 \u0003לה\u0004 שדה שהקדישה, \u0003שכן\u0004 כאשר הבן יורשה הריהו \u0003נוטל\u0004 \u0003ב\u0004נכס ש\u0003ראוי\u0004 היה ליפול לידיה (כגון בירושה) \u0003כ\u0004פי שהוא יורש \u0003ב\u0004נכס שכבר \u0003מוחזק\u0004 בידה? שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ועוד בעניינים אלה, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רמי בר חמא מרב חסדא:\u0004 \u0003הקדישה\u0004 את שדה אחוזתו \u0003פחות משתי שנים לפני היובל,\u0004 ולא גאלה, \u0003מהו שתצא\u0004 \u0003לכהנים?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003מאי דעתיך\u0004 \u0005[מה דעתך],\u0006 מדוע אתה סבור שתחזור אליו? שהרי לאחר שנאמר: \u0003\"ונגרע מערכך\"\u0004 (ויקרא כז, יח), ללמד שהשדה נגאלת בגרעון כסף לפי השנים הנותרות עד היובל, אומר הכתוב: \u0003\"והיה השדה בצאתו ביובל\u0004 קדש לה'... לכהן תהיה אחוזתו\" (שם, כא), ומכאן אתה למד ששדה שהיא \u0003בת גירעון\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יוצאת ביובל לכהנים, אבל שדה \u0003דלאו\u0004 \u0005[שאינה]\u0006 \u0003בת גירעון,\u0004 וכגון שהקדישוה בתוך שנתיים לפני היובל, ואפשר לפדותה רק במחיר מלא של חמישים שקל לבית זרע כור שעורים (ראה לעיל כד,א) — \u0003לא\u0004 תצא ביובל לכהנים, אלא תחזור לבעליה.","על כך יש להשיב: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 כאשר הכתוב מגדיר מתי יוצאת השדה לכהנים, נאמר: \"ו \u0003אם לא יגאל השדה\u0004 וכו' \u0003והיה השדה בצאתו ביובל\u0004 קדש לה'... לכהן תהיה אחוזתו\" (שם כ—כא), ומכאן אתה למד שכל שדה שניתן לגואלה בכלל זה, \u0003והאי נמי\u0004 \u0005[וזו גם כן],\u0006 השדה שהקדישוה בתוך שנתיים לפני היובל — \u0003בת גאולה היא,\u0004 ולפיכך תצא ביובל לכהנים.","שנינו במשנה: \u0003גאלה אחד מן הכהנים,\u0004 והרי היא תחת ידו, לא יאמר: הואיל והיא יוצאה לכהנים ביובל, והרי היא תחת ידי — הרי היא שלי, אלא יוצאה מתחת ידו ומתחלקת לכל אחיו הכהנים. ומביאים בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 מה שנאמר במקדיש שדה אחוזתו ולא גאלה: \"והיה השדה בצאתו ביובל קדש לה'... \u0003לכהן תהיה אחזתו\"\u0004 (ויקרא כז, כא), \u0003מה תלמוד לומר?\u0004 והרי די לומר \"לכהן תהיה\"!","אלא דבר זה למדנו מכאן: \u0003מנין לשדה שיוצא לכהנים ביובל, וגאלה\u0004 לפני כן \u0003אחד מן הכהנים, מנין שלא יאמר: \"הואיל ו\u0004דין שדה זו ש\u0003יוצאה לכהן,\u0004 ו\u0003הרי\u0004 היא כבר \u0003תחת ידי, ו\u0004לפיכך \u0003תהא\u0004 \u0003שלי? ו\u0004הרי \u0003דין\u0004 (קל וחומר) \u0003הוא:\u0004 אם \u0003ב\u0004שדה \u0003של אחרים,\u0004 שקנו מן ההקדש ולא גאלו — \u0003אני זוכה\u0004 ביובל, \u0003בשל עצמי,\u0004 שקניתי מן ההקדש — \u0003לא כל שכן\u0004 שאזכה ביובל?","\u0003תלמוד לומר: \"אחזתו\",\u0004 לדייק: דווקא שדה \u0003אחוזה\u0004 שירש מאבותיו, היא \u0003שלו, ואין\u0004 שדה \u0003זה\u0004 שלא גאלה בעליה \u0003שלו. הא כיצד\u0004 יהא דין השדה? \u0003יוצא מתחת ידו ומתחלקת לאחיו הכהנים.\u0004","המקדיש שדה אחוזתו, ו\u0003הגיע יובל ולא נגאלה\u0004 השדה מיד ההקדש, לא על ידי המקדיש ולא על ידי אדם אחר, \u0003הכהנים נכנסין לתוכה ונותנין את דמיה\u0004 להקדש, אלו \u0003דברי ר' יהודה. ר' שמעון אומר: נכנסין\u0004 לתוכה \u0003ולא נותנין\u0004 את דמיה.","\u0003ר' אליעזר אומר: לא נכנסין ולא נותנין, אלא\u0004 נשארת ביד ההקדש, ו\u0003נקראת \"שדה רטושין\"\u0004 (שדה עזובה) \u0003עד היובל השני.\u0004 אם \u0003הגיע היובל השני ו\u0004עדיין \u0003לא נגאלה, נקראת\u0004 \u0003\"רטושי רטושין\" עד היובל השלישי,\u0004 ו\u0003לעולם אין הכהנים נכנסין לתוכה\u0004 ביובל \u0003עד שיגאלנה אחר\u0004 תחילה מיד ההקדש.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה,\u0004 שהכהנים הנכנסים לשדה הקדש ביובל נותנים את דמיה להקדש? ומשיבים: \u0003גמר\u0004 \u0005[למד]\u0006 הוא בגזירה שווה \u0003\"קדש\" \"קדש\" ממקדיש בית,\u0004","\u0003מה להלן,\u0004 במקדיש בית, שנאמר בו: \"ואיש כי יקדיש את ביתו קודש לה' \" (ויקרא כז, יד), אינו יוצא מיד ההקדש אלא \u0003בדמים,\u0004 שנאמר: \"כאשר יעריך אותו הכהן כן יקום\" (שם) — \u0003אף כאן,\u0004 בשדה היוצאת לכהנים, שנאמר בה: \"והיה השדה בצאתו ביובל קודש לה'... לכהן תהיה אחוזתו\" (שם כא) — אינה יוצאת מיד ההקדש אלא \u0003בדמים.\u0004","\u0003ו\u0004אילו \u0003ר' שמעון,\u0004 הסבור כי אין הכהנים צריכים לתת את דמי השדה להקדש, הוא \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"קדש\" \"קדש\" מכבשי עצרת,\u0004 הבאים יחד עם שתי הלחם, \u0003מה להלן,\u0004 בכבשי עצרת, שנאמר בהם: \"קודש יהיו לה' לכהן\" (שם כג, כ) הריהם ניתנים לכהנים \u0003בחנם,\u0004 ככל מתנות הכהנים — \u0003אף כאן,\u0004 שדה היוצאת ביובל, שנאמר בה \"קודש\" — ניתנת לכהנים \u0003בחנם.\u0004","ושואלים: \u0003ור' יהודה נמי ניליף\u0004 \u0005[גם כן שילמד]\u0006 \u0003מכבשי עצרת!\u0004 ומשיבים: \u0003דנין קדשי בדק הבית\u0004"]]};
